window.SP = {"courses": [{"n": 1, "name": "Mathematics foundations", "blurb": "Number sense, units, geometry, trigonometry, statistics, vectors and the habits of mathematical thinking: the toolkit every other course uses.", "mods": [{"id": "1.1", "title": "Numbers and arithmetic fluency"}, {"id": "1.2", "title": "Units, measurement and dimensional analysis"}, {"id": "1.3", "title": "Geometry"}, {"id": "1.4", "title": "Trigonometry"}, {"id": "1.5", "title": "Probability and statistics"}, {"id": "1.6", "title": "Vectors"}, {"id": "1.7", "title": "Mathematical thinking"}], "cap": "Estimating Earth from a shadow", "wb": "pages/c1-workbook.html", "ex": "pages/c1-explorer.html", "exn": "Maths Workbench", "reader": "docs/C1-Mathematics-Theory-Reader.pdf", "comp": "docs/C1-Mathematics-Visual-Companion.pdf", "wbpdf": "docs/C1-Mathematics-Workbook.pdf", "cardspdf": "docs/C1-Mathematics-Flashcards.pdf", "vid": "video/C1-Mathematics-Animated-Explainer.mp4"}, {"n": 2, "name": "Algebra", "blurb": "Expressions, equations, functions, quadratics, exponentials and logarithms, and a first look at calculus: the language every science is written in.", "mods": [{"id": "2.1", "title": "Expressions and simplifying"}, {"id": "2.2", "title": "Linear equations and inequalities"}, {"id": "2.3", "title": "Rearranging formulas"}, {"id": "2.4", "title": "Functions and graphs"}, {"id": "2.5", "title": "Systems of equations"}, {"id": "2.6", "title": "Quadratics and polynomials"}, {"id": "2.7", "title": "Exponentials and logarithms"}, {"id": "2.8", "title": "Calculus intuition"}], "cap": "Modelling a cooling cup of coffee", "wb": "pages/c2-workbook.html", "ex": "pages/c2-explorer.html", "exn": "Function Lab", "reader": "docs/C2-Algebra-Theory-Reader.pdf", "comp": "docs/C2-Algebra-Visual-Companion.pdf", "wbpdf": "docs/C2-Algebra-Workbook.pdf", "cardspdf": "docs/C2-Algebra-Flashcards.pdf", "vid": "video/C2-Algebra-Animated-Explainer.mp4"}, {"n": 3, "name": "Physics", "blurb": "Motion, forces, energy, momentum, waves, electricity, magnetism, heat, and the modern physics of relativity, quanta and the nucleus.", "mods": [{"id": "3.1", "title": "Motion (kinematics)"}, {"id": "3.2", "title": "Forces and Newton's laws"}, {"id": "3.3", "title": "Energy, work and power"}, {"id": "3.4", "title": "Momentum, collisions and rotation"}, {"id": "3.5", "title": "Waves and sound"}, {"id": "3.6", "title": "Electricity and circuits"}, {"id": "3.7", "title": "Magnetism and electromagnetism"}, {"id": "3.8", "title": "Thermodynamics and heat"}, {"id": "3.9", "title": "Modern physics"}], "cap": "A satellite's journey", "wb": "pages/c3-workbook.html", "ex": "pages/c3-explorer.html", "exn": "Physics Lab", "reader": "docs/C3-Physics-Theory-Reader.pdf", "comp": "docs/C3-Physics-Visual-Companion.pdf", "wbpdf": "docs/C3-Physics-Workbook.pdf", "cardspdf": "docs/C3-Physics-Flashcards.pdf", "vid": "video/C3-Physics-Animated-Explainer.mp4"}, {"n": 4, "name": "Chemistry", "blurb": "Atoms, the periodic table, bonding, the mole, gases, reactions, equilibrium, acids and redox, and the organic chemistry of life.", "mods": [{"id": "4.1", "title": "Matter and atomic structure"}, {"id": "4.2", "title": "The periodic table"}, {"id": "4.3", "title": "Bonding and molecular shape"}, {"id": "4.4", "title": "The mole and stoichiometry"}, {"id": "4.5", "title": "States of matter and gas laws"}, {"id": "4.6", "title": "Energy, rates and equilibrium"}, {"id": "4.7", "title": "Acids, bases and redox"}, {"id": "4.8", "title": "Organic chemistry essentials"}], "cap": "Investigating an antacid tablet", "wb": "pages/c4-workbook.html", "ex": "pages/c4-explorer.html", "exn": "Chemistry Lab", "reader": "docs/C4-Chemistry-Theory-Reader.pdf", "comp": "docs/C4-Chemistry-Visual-Companion.pdf", "wbpdf": "docs/C4-Chemistry-Workbook.pdf", "cardspdf": "docs/C4-Chemistry-Flashcards.pdf", "vid": "video/C4-Chemistry-Animated-Explainer.mp4"}, {"n": 5, "name": "Astronomy", "blurb": "The sky, gravity and orbits, light, the Solar System, the lives and deaths of stars, galaxies and the history of the universe.", "mods": [{"id": "5.1", "title": "The sky and the history of astronomy"}, {"id": "5.2", "title": "Gravity and orbits"}, {"id": "5.3", "title": "Light as messenger"}, {"id": "5.4", "title": "The Solar System"}, {"id": "5.5", "title": "Stars"}, {"id": "5.6", "title": "Stellar death"}, {"id": "5.7", "title": "Galaxies"}, {"id": "5.8", "title": "Cosmology"}], "cap": "Characterising a star with a planet", "wb": "pages/c5-workbook.html", "ex": "pages/c5-explorer.html", "exn": "Sky Lab", "reader": "docs/C5-Astronomy-Theory-Reader.pdf", "comp": "docs/C5-Astronomy-Visual-Companion.pdf", "wbpdf": "docs/C5-Astronomy-Workbook.pdf", "cardspdf": "docs/C5-Astronomy-Flashcards.pdf", "vid": "video/C5-Astronomy-Animated-Explainer.mp4"}, {"n": 6, "name": "Biology", "blurb": "The chemistry of life, cells, metabolism, DNA and genes, inheritance, evolution, the human body, microbes and immunity, and ecosystems.", "mods": [{"id": "6.1", "title": "The chemistry of life"}, {"id": "6.2", "title": "Cells"}, {"id": "6.3", "title": "Metabolism"}, {"id": "6.4", "title": "DNA, genes and protein synthesis"}, {"id": "6.5", "title": "Inheritance and genetics"}, {"id": "6.6", "title": "Evolution and natural selection"}, {"id": "6.7", "title": "Human body systems"}, {"id": "6.8", "title": "Microbes, immunity and disease"}, {"id": "6.9", "title": "Ecology and ecosystems"}], "cap": "Tracking an outbreak", "wb": "pages/c6-workbook.html", "ex": "pages/c6-explorer.html", "exn": "Life Lab", "reader": "docs/C6-Biology-Theory-Reader.pdf", "comp": "docs/C6-Biology-Visual-Companion.pdf", "wbpdf": "docs/C6-Biology-Workbook.pdf", "cardspdf": "docs/C6-Biology-Flashcards.pdf", "vid": "video/C6-Biology-Animated-Explainer.mp4"}], "pilot": {"n": 23, "name": "Rearranging formulas", "blurb": "The full-length pilot module: changing the subject of a formula, the single most useful algebra skill for physics, chemistry and biology.", "mods": [{"id": "2.3P", "title": "Rearranging formulas (pilot)"}], "cap": "", "wb": "pages/m23-workbook.html", "ex": "pages/untangler.html", "exn": "Formula Untangler", "reader": "docs/M2.3-Theory-Reader.pdf", "comp": "docs/M2.3-Visual-Companion.pdf", "wbpdf": "docs/M2.3-Workbook.pdf", "cardspdf": "docs/M2.3-Flashcards.pdf", "vid": "video/M2.3-Animated-Explainer.mp4"}};
window.SP_CARDS = [{"id": "1.1-e1", "m": "1.1", "c": 1, "k": "equation", "f": "Write the equation: Percentage change", "tex": "\\%\\ \\mathrm{change} = \\frac{\\mathrm{new} - \\mathrm{old}}{\\mathrm{old}} \\times 100"}, {"id": "1.1-e2", "m": "1.1", "c": 1, "k": "equation", "f": "Write the equation: Multiplying powers", "tex": "(a \\times 10^m)(b \\times 10^n) = ab \\times 10^{m+n}"}, {"id": "1.1-e3", "m": "1.1", "c": 1, "k": "equation", "f": "Write the equation: Dividing powers", "tex": "\\frac{a \\times 10^m}{b \\times 10^n} = \\frac{a}{b} \\times 10^{m-n}"}, {"id": "1.1-e4", "m": "1.1", "c": 1, "k": "equation", "f": "Write the equation: Negative and zero powers", "tex": "10^{-n} = \\frac{1}{10^n},\\qquad 10^0 = 1"}, {"id": "1.1-k1", "m": "1.1", "c": 1, "k": "key idea", "f": "Complete the key idea: Percentage change is …", "b": "Percentage change is measured against the starting value"}, {"id": "1.1-k2", "m": "1.1", "c": 1, "k": "key idea", "f": "Complete the key idea: In scientific notation, …", "b": "In scientific notation, multiply coefficients and add exponents"}, {"id": "1.1-k3", "m": "1.1", "c": 1, "k": "key idea", "f": "Complete the key idea: Estimate first; it tells …", "b": "Estimate first; it tells you whether a calculated answer is sensible"}, {"id": "1.1-k4", "m": "1.1", "c": 1, "k": "key idea", "f": "Complete the key idea: Report results to the …", "b": "Report results to the precision of your least precise input"}, {"id": "1.1-q1", "m": "1.1", "c": 1, "k": "quick check", "f": "What is 10⁻³ as a fraction?", "b": "1/1000"}, {"id": "1.1-q2", "m": "1.1", "c": 1, "k": "quick check", "f": "(2 × 10³) × (3 × 10⁴) equals", "b": "6 × 10⁷"}, {"id": "1.1-q3", "m": "1.1", "c": 1, "k": "quick check", "f": "A price falls 50% then rises 50%. It ends at", "b": "75% of the original. The rise is 50% of a smaller base."}, {"id": "1.1-q4", "m": "1.1", "c": 1, "k": "quick check", "f": "The prefix 'micro' means", "b": "10⁻⁶"}, {"id": "1.1-p1", "m": "1.1", "c": 1, "k": "problem", "f": "A jacket priced at $180 is reduced by 35%. What is the sale price?", "b": "117 dollars. 180 − 63 = 117. Or directly: 0.65 × 180 = 117."}, {"id": "1.1-p2", "m": "1.1", "c": 1, "k": "problem", "f": "A town's population grows from 24 000 to 27 600. What is the percentage increase?", "b": "15 %. 3600 ÷ 24 000 = 0.15, which is 15%."}, {"id": "1.1-p3", "m": "1.1", "c": 1, "k": "problem", "f": "Support for a policy rises from 40% to 50%. Which statement is correct?", "b": "It rose by 10 percentage points, or 25%. Relative to the starting 40, that is 10 ÷ 40 = 25%."}, {"id": "1.1-p4", "m": "1.1", "c": 1, "k": "problem", "f": "Calculate (6 × 10⁵) × (4 × 10⁻²). Give the answer as an ordinary number.", "b": "2.4e+04. 24 × 10³ = 2.4 × 10⁴ = 24 000."}, {"id": "1.1-p5", "m": "1.1", "c": 1, "k": "problem", "f": "Light travels at 3.0 × 10⁸ m/s. The Sun is 1.5 × 10¹¹ m away. How many seconds does sunlight take to reach Earth?", "b": "500 s. 0.5 × 10³ = 500 s, a little over eight minutes."}, {"id": "1.1-p6", "m": "1.1", "c": 1, "k": "problem", "f": "A red blood cell is about 8 micrometres across. How many would fit side by side across 1 centimetre?", "b": "1250. 10⁻² ÷ (8 × 10⁻⁶) = 0.125 × 10⁴ = 1250."}, {"id": "1.1-p7", "m": "1.1", "c": 1, "k": "problem", "f": "A calculator gives 3.14159265 for a result whose inputs were measured to 3 significant figures. How should you report it?", "b": "3.14. 3.14."}, {"id": "1.1-p8", "m": "1.1", "c": 1, "k": "problem", "f": "Estimate, to the nearest power of ten, how many times your heart beats in an 80-year life. Show your assumptions.", "b": "About 70 beats a minute × 60 minutes × 24 hours × 365 days × 80 years. Rounding: 70 × 60 ≈ 4 × 10³ per hour; × 24 ≈ 10⁵ per day; × 365 ≈ 3.7 × 10⁷ per year; × 80 ≈ 3 × 10⁹. So roughly three billion, of order 10⁹."}, {"id": "1.2-e1", "m": "1.2", "c": 1, "k": "equation", "f": "Write the equation: The newton in base units", "tex": "1\\ \\mathrm{N} = 1\\ \\mathrm{kg\\,m\\,s^{-2}}"}, {"id": "1.2-e2", "m": "1.2", "c": 1, "k": "equation", "f": "Write the equation: Area and volume conversions", "tex": "1\\ \\mathrm{m^2} = 10^4\\ \\mathrm{cm^2},\\qquad 1\\ \\mathrm{m^3} = 10^6\\ \\mathrm{cm^3} = 1000\\ \\mathrm{L}"}, {"id": "1.2-e3", "m": "1.2", "c": 1, "k": "equation", "f": "Write the equation: Dimensional argument for a pendulum", "tex": "[T] = \\sqrt{\\frac{[L]}{[g]}} = \\sqrt{\\frac{\\mathrm{m}}{\\mathrm{m\\,s^{-2}}}} = \\mathrm{s}"}, {"id": "1.2-e4", "m": "1.2", "c": 1, "k": "equation", "f": "Write the equation: Percentage uncertainty", "tex": "\\%\\ \\mathrm{uncertainty} = \\frac{\\Delta x}{x} \\times 100"}, {"id": "1.2-k1", "m": "1.2", "c": 1, "k": "key idea", "f": "Complete the key idea: Convert to SI …", "b": "Convert to SI base units before substituting"}, {"id": "1.2-k2", "m": "1.2", "c": 1, "k": "key idea", "f": "Complete the key idea: Conversion factors equal one; raise …", "b": "Conversion factors equal one; raise them to the power of the unit"}, {"id": "1.2-k3", "m": "1.2", "c": 1, "k": "key idea", "f": "Complete the key idea: Both sides of an …", "b": "Both sides of an equation must have the same dimensions"}, {"id": "1.2-k4", "m": "1.2", "c": 1, "k": "key idea", "f": "Complete the key idea: Averaging reduces random …", "b": "Averaging reduces random error, not systematic error"}, {"id": "1.2-q1", "m": "1.2", "c": 1, "k": "quick check", "f": "The SI base unit of mass is the", "b": "kilogram"}, {"id": "1.2-q2", "m": "1.2", "c": 1, "k": "quick check", "f": "1 m³ equals how many cm³?", "b": "1 000 000"}, {"id": "1.2-q3", "m": "1.2", "c": 1, "k": "quick check", "f": "Averaging many readings reduces", "b": "random error"}, {"id": "1.2-q4", "m": "1.2", "c": 1, "k": "quick check", "f": "Which quantity could be added to a speed?", "b": "another speed"}, {"id": "1.2-p1", "m": "1.2", "c": 1, "k": "problem", "f": "Convert 90 km/h into metres per second.", "b": "25 m/s. 90 000 ÷ 3600 = 25 m/s."}, {"id": "1.2-p2", "m": "1.2", "c": 1, "k": "problem", "f": "A room is 4.0 m by 3.5 m. What is its floor area in square centimetres?", "b": "1.400e+05 cm². 1 m² = 10⁴ cm², so 14 × 10⁴ = 1.4 × 10⁵ cm²."}, {"id": "1.2-p3", "m": "1.2", "c": 1, "k": "problem", "f": "A tank holds 2.5 cubic metres of water. How many litres is that?", "b": "2500 L. 2.5 × 1000 = 2500 L."}, {"id": "1.2-p4", "m": "1.2", "c": 1, "k": "problem", "f": "Which of these equations is dimensionally impossible? (v speed, t time, a acceleration, s distance)", "b": "s = v + at. s = v + at adds metres to metres-per-second: impossible."}, {"id": "1.2-p5", "m": "1.2", "c": 1, "k": "problem", "f": "What are the SI base units of a joule?", "b": "kg m² s⁻². N = kg m s⁻², so J = kg m² s⁻²."}, {"id": "1.2-p6", "m": "1.2", "c": 1, "k": "problem", "f": "A length is measured as 25.0 ± 0.5 cm. What is the percentage uncertainty?", "b": "2 %. 0.02 × 100 = 2%."}, {"id": "1.2-p8", "m": "1.2", "c": 1, "k": "problem", "f": "A friend averages 50 readings from a scale that always reads 0.2 kg too high. Explain why the average is still wrong, and what kind of error this is.", "b": "This is a systematic error: every reading is shifted by the same 0.2 kg in the same direction. Averaging cancels random scatter but not a constant offset, so the mean is still 0.2 kg too high. The fix is to calibrate the scale, for example by weighing a known mass, and correct for the offset."}, {"id": "1.3-e1", "m": "1.3", "c": 1, "k": "equation", "f": "Write the equation: Pythagoras' theorem", "tex": "a^2 + b^2 = c^2"}, {"id": "1.3-e2", "m": "1.3", "c": 1, "k": "equation", "f": "Write the equation: Diagonal of a box", "tex": "d = \\sqrt{a^2 + b^2 + c^2}"}, {"id": "1.3-e3", "m": "1.3", "c": 1, "k": "equation", "f": "Write the equation: Scaling of length, area and volume", "tex": "L \\to kL,\\quad A \\to k^2 A,\\quad V \\to k^3 V"}, {"id": "1.3-e4", "m": "1.3", "c": 1, "k": "equation", "f": "Write the equation: Circle", "tex": "C = 2\\pi r,\\qquad A = \\pi r^2"}, {"id": "1.3-e5", "m": "1.3", "c": 1, "k": "equation", "f": "Write the equation: Sphere", "tex": "A = 4\\pi r^2,\\qquad V = \\frac{4}{3}\\pi r^3"}, {"id": "1.3-k1", "m": "1.3", "c": 1, "k": "key idea", "f": "Complete the key idea: Pythagoras: hypotenuse squared equals …", "b": "Pythagoras: hypotenuse squared equals the sum of the other two squares"}, {"id": "1.3-k2", "m": "1.3", "c": 1, "k": "key idea", "f": "Complete the key idea: Scale lengths by k: …", "b": "Scale lengths by k: areas by k², volumes by k³"}, {"id": "1.3-k3", "m": "1.3", "c": 1, "k": "key idea", "f": "Complete the key idea: Circle: C = 2πr, A = …", "b": "Circle: C = 2πr, A = πr². Sphere: A = 4πr², V = (4/3)πr³"}, {"id": "1.3-k4", "m": "1.3", "c": 1, "k": "key idea", "f": "Complete the key idea: Surface-to-volume ratio …", "b": "Surface-to-volume ratio falls as size grows"}, {"id": "1.3-q1", "m": "1.3", "c": 1, "k": "quick check", "f": "A right triangle has legs 6 and 8. The hypotenuse is", "b": "10"}, {"id": "1.3-q2", "m": "1.3", "c": 1, "k": "quick check", "f": "Scale lengths by 3. Volume scales by", "b": "27"}, {"id": "1.3-q3", "m": "1.3", "c": 1, "k": "quick check", "f": "The surface area of a sphere is", "b": "4πr²"}, {"id": "1.3-q4", "m": "1.3", "c": 1, "k": "quick check", "f": "Angles in a triangle add to", "b": "180°"}, {"id": "1.3-p1", "m": "1.3", "c": 1, "k": "problem", "f": "A ladder 5.0 m long leans against a wall with its foot 1.4 m from the wall. How high up the wall does it reach?", "b": "4.8 m. h² = 25 − 1.96 = 23.04, so h = 4.8 m."}, {"id": "1.3-p2", "m": "1.3", "c": 1, "k": "problem", "f": "What is the area of a circle of diameter 10 cm?", "b": "78.54 cm². A = π × 5² ≈ 78.5 cm²."}, {"id": "1.3-p3", "m": "1.3", "c": 1, "k": "problem", "f": "A box measures 30 cm × 40 cm × 120 cm. How long is the longest straight rod that fits inside?", "b": "130 cm. = √(900 + 1600 + 14 400) = √16 900 = 130 cm."}, {"id": "1.3-p4", "m": "1.3", "c": 1, "k": "problem", "f": "A model car is built at 1:20 scale. Its paintwork covers 0.15 m². What area of paint covers the real car?", "b": "60 m². 0.15 × 400 = 60 m²."}, {"id": "1.3-p5", "m": "1.3", "c": 1, "k": "problem", "f": "If you double the radius of a sphere, by what factor does its volume increase?", "b": "8 ×. 2³ = 8."}, {"id": "1.3-p6", "m": "1.3", "c": 1, "k": "problem", "f": "Earth's radius is about 6.37 × 10⁶ m. Treating it as a sphere, what is its volume?", "b": "1.083e+21 m³. r³ = 2.58 × 10²⁰; × 4.19 gives about 1.08 × 10²¹ m³."}, {"id": "1.3-p7", "m": "1.3", "c": 1, "k": "problem", "f": "A cube's side length triples. Its surface-area-to-volume ratio", "b": "falls to one third. Ratio scales by 9/27 = 1/3."}, {"id": "1.3-p8", "m": "1.3", "c": 1, "k": "problem", "f": "Use the square-cube law to explain why elephants have proportionally thicker legs than gazelles.", "b": "Weight goes with volume, so it scales with length cubed. The strength of a leg bone goes with its cross-sectional area, which scales with length squared. A larger animal built to the same proportions would carry far more weight per unit of bone area, so the bones would fail. To compensate, large animals need disproportionately thick legs."}, {"id": "1.4-e1", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: Trigonometric ratios", "tex": "\\sin\\theta = \\frac{\\mathrm{opp}}{\\mathrm{hyp}},\\quad \\cos\\theta = \\frac{\\mathrm{adj}}{\\mathrm{hyp}},\\quad \\tan\\theta = \\frac{\\mathrm{opp}}{\\mathrm{adj}}"}, {"id": "1.4-e2", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: Resolving a vector of size F at angle θ", "tex": "F_x = F\\cos\\theta,\\qquad F_y = F\\sin\\theta"}, {"id": "1.4-e3", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: Degrees and radians", "tex": "\\pi\\ \\mathrm{rad} = 180^\\circ"}, {"id": "1.4-e4", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: Arc length", "tex": "s = r\\theta"}, {"id": "1.4-e5", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: Pythagorean identity", "tex": "\\sin^2\\theta + \\cos^2\\theta = 1"}, {"id": "1.4-e6", "m": "1.4", "c": 1, "k": "equation", "f": "Write the equation: General sinusoid", "tex": "y = A\\sin(\\omega t + \\phi),\\qquad T = \\frac{2\\pi}{\\omega}"}, {"id": "1.4-k1", "m": "1.4", "c": 1, "k": "key idea", "f": "Complete the key idea: SOH CAH TOA in …", "b": "SOH CAH TOA in right triangles; inverse functions give angles"}, {"id": "1.4-k2", "m": "1.4", "c": 1, "k": "key idea", "f": "Complete the key idea: Resolve vectors with cos for …", "b": "Resolve vectors with cos for the adjacent component and sin for the opposite"}, {"id": "1.4-k3", "m": "1.4", "c": 1, "k": "key idea", "f": "Complete the key idea: π radians = 180°; arc …", "b": "π radians = 180°; arc length s = rθ (θ in radians)"}, {"id": "1.4-k4", "m": "1.4", "c": 1, "k": "key idea", "f": "Complete the key idea: Sine waves: …", "b": "Sine waves: amplitude, period and phase"}, {"id": "1.4-q1", "m": "1.4", "c": 1, "k": "quick check", "f": "tan θ equals", "b": "opp/adj"}, {"id": "1.4-q2", "m": "1.4", "c": 1, "k": "quick check", "f": "180° in radians is", "b": "π"}, {"id": "1.4-q3", "m": "1.4", "c": 1, "k": "quick check", "f": "A 10 N force at 60° to the horizontal has a horizontal component of", "b": "5 N. 10 cos 60° = 5 N."}, {"id": "1.4-q4", "m": "1.4", "c": 1, "k": "quick check", "f": "The period of y = sin(ωt) is", "b": "2π/ω"}, {"id": "1.4-p1", "m": "1.4", "c": 1, "k": "problem", "f": "A ramp rises at 12° and is 4.0 m long along its surface. How high does it rise?", "b": "0.8316 m. h = 4.0 × sin 12° ≈ 0.83 m."}, {"id": "1.4-p2", "m": "1.4", "c": 1, "k": "problem", "f": "Convert 45° to radians, as a decimal.", "b": "0.7854 rad. 45π/180 = π/4 ≈ 0.785 rad."}, {"id": "1.4-p3", "m": "1.4", "c": 1, "k": "problem", "f": "From 50 m away, the top of a tower is at an angle of elevation of 35°. How tall is the tower (ignoring eye height)?", "b": "35.01 m. height = 50 × tan 35° ≈ 35 m."}, {"id": "1.4-p4", "m": "1.4", "c": 1, "k": "problem", "f": "A rope pulls a sled with 200 N at 25° above the horizontal. What is the horizontal component of the pull?", "b": "181.3 N. 200 × cos 25° ≈ 181 N."}, {"id": "1.4-p5", "m": "1.4", "c": 1, "k": "problem", "f": "A wheel of radius 0.30 m turns through 2.5 radians. How far does a point on the rim travel?", "b": "0.75 m. 0.30 × 2.5 = 0.75 m."}, {"id": "1.4-p6", "m": "1.4", "c": 1, "k": "problem", "f": "A right triangle has opposite side 7 and hypotenuse 10. Find the angle, in degrees.", "b": "44.43 °. θ = sin⁻¹(0.7) ≈ 44.4°."}, {"id": "1.4-p7", "m": "1.4", "c": 1, "k": "problem", "f": "The wave y = 3 sin(2t) has amplitude and period", "b": "3 and π. Period = 2π/ω = 2π/2 = π."}, {"id": "1.4-p8", "m": "1.4", "c": 1, "k": "problem", "f": "Explain, using the unit circle, why sin²θ + cos²θ = 1 for every angle.", "b": "On the unit circle, the point at angle θ has coordinates (cos θ, sin θ). Its distance from the centre is always the radius, 1. By Pythagoras, the horizontal and vertical distances satisfy cos²θ + sin²θ = 1² = 1, whatever θ is."}, {"id": "1.5-e1", "m": "1.5", "c": 1, "k": "equation", "f": "Write the equation: Addition rule (mutually exclusive)", "tex": "P(A\\ \\mathrm{or}\\ B) = P(A) + P(B)"}, {"id": "1.5-e2", "m": "1.5", "c": 1, "k": "equation", "f": "Write the equation: Multiplication rule (independent)", "tex": "P(A\\ \\mathrm{and}\\ B) = P(A)\\,P(B)"}, {"id": "1.5-e3", "m": "1.5", "c": 1, "k": "equation", "f": "Write the equation: Conditional probability", "tex": "P(A\\,|\\,B) = \\frac{P(A\\ \\mathrm{and}\\ B)}{P(B)}"}, {"id": "1.5-e4", "m": "1.5", "c": 1, "k": "equation", "f": "Write the equation: Standard deviation (sample)", "tex": "s = \\sqrt{\\frac{\\sum (x_i - \\bar{x})^2}{n-1}}"}, {"id": "1.5-e5", "m": "1.5", "c": 1, "k": "equation", "f": "Write the equation: Standard error of the mean", "tex": "\\mathrm{SE} = \\frac{s}{\\sqrt{n}}"}, {"id": "1.5-k1", "m": "1.5", "c": 1, "k": "key idea", "f": "Complete the key idea: Exclusive events: add …", "b": "Exclusive events: add probabilities. Independent events: multiply"}, {"id": "1.5-k2", "m": "1.5", "c": 1, "k": "key idea", "f": "Complete the key idea: Conditional probability: P(A|B) = …", "b": "Conditional probability: P(A|B) = P(A and B) / P(B)"}, {"id": "1.5-k3", "m": "1.5", "c": 1, "k": "key idea", "f": "Complete the key idea: Normal distribution: 68% …", "b": "Normal distribution: 68% within 1σ, 95% within 2σ"}, {"id": "1.5-k4", "m": "1.5", "c": 1, "k": "key idea", "f": "Complete the key idea: Standard error = σ/√n; …", "b": "Standard error = σ/√n; more data shrinks it slowly"}, {"id": "1.5-q1", "m": "1.5", "c": 1, "k": "quick check", "f": "For independent events A and B, P(A and B) is", "b": "P(A) × P(B)"}, {"id": "1.5-q2", "m": "1.5", "c": 1, "k": "quick check", "f": "About what percentage of a normal distribution lies within 1 SD of the mean?", "b": "68%"}, {"id": "1.5-q3", "m": "1.5", "c": 1, "k": "quick check", "f": "Taking 100 readings instead of 25 changes the standard error by a factor of", "b": "1/2"}, {"id": "1.5-q4", "m": "1.5", "c": 1, "k": "quick check", "f": "Physicists' '5-sigma' standard is", "b": "far stricter than p = 0.05"}, {"id": "1.5-p1", "m": "1.5", "c": 1, "k": "problem", "f": "A fair coin is tossed three times. What is the probability of three heads? Give a decimal.", "b": "0.125. ½ × ½ × ½ = 1/8 = 0.125."}, {"id": "1.5-p2", "m": "1.5", "c": 1, "k": "problem", "f": "Two dice are rolled. What is the probability that the total is 7? Give a decimal.", "b": "0.1667. 6 ÷ 36 = 1/6 ≈ 0.167."}, {"id": "1.5-p3", "m": "1.5", "c": 1, "k": "problem", "f": "Find the mean of these timings in seconds: 2.1, 2.3, 1.9, 2.2, 2.0.", "b": "2.1 s. 10.5 ÷ 5 = 2.1 s."}, {"id": "1.5-p4", "m": "1.5", "c": 1, "k": "problem", "f": "A set of measurements has standard deviation 0.40 s. You take 16 readings. What is the standard error of the mean?", "b": "0.1 s. 0.40 ÷ √16 = 0.40 ÷ 4 = 0.10 s."}, {"id": "1.5-p5", "m": "1.5", "c": 1, "k": "problem", "f": "Heights are normally distributed with mean 170 cm and SD 10 cm. Roughly what fraction are between 150 cm and 190 cm?", "b": "95%. About 95%."}, {"id": "1.5-p6", "m": "1.5", "c": 1, "k": "problem", "f": "In a class, 60% study physics and, of those, 30% also study chemistry. What fraction of the class studies both? Give a decimal.", "b": "0.18. 0.6 × 0.3 = 0.18."}, {"id": "1.5-p8", "m": "1.5", "c": 1, "k": "problem", "f": "To halve the standard error of a mean, how many more readings do you need? Explain.", "b": "Four times as many. The standard error is s/√n, so it shrinks with the square root of n. To divide it by 2 you must multiply √n by 2, which means multiplying n by 4. Precision improves slowly with more data."}, {"id": "1.6-e1", "m": "1.6", "c": 1, "k": "equation", "f": "Write the equation: Magnitude", "tex": "|\\mathbf{a}| = \\sqrt{a_x^2 + a_y^2}"}, {"id": "1.6-e2", "m": "1.6", "c": 1, "k": "equation", "f": "Write the equation: Direction", "tex": "\\theta = \\tan^{-1}\\left(\\frac{a_y}{a_x}\\right)"}, {"id": "1.6-e3", "m": "1.6", "c": 1, "k": "equation", "f": "Write the equation: Addition by components", "tex": "\\mathbf{a} + \\mathbf{b} = (a_x + b_x,\\ a_y + b_y)"}, {"id": "1.6-e4", "m": "1.6", "c": 1, "k": "equation", "f": "Write the equation: Dot product, components", "tex": "\\mathbf{a}\\cdot\\mathbf{b} = a_x b_x + a_y b_y + a_z b_z"}, {"id": "1.6-e5", "m": "1.6", "c": 1, "k": "equation", "f": "Write the equation: Dot product, geometric", "tex": "\\mathbf{a}\\cdot\\mathbf{b} = |\\mathbf{a}|\\,|\\mathbf{b}|\\cos\\theta"}, {"id": "1.6-k1", "m": "1.6", "c": 1, "k": "key idea", "f": "Complete the key idea: Vectors have magnitude …", "b": "Vectors have magnitude and direction; scalars only magnitude"}, {"id": "1.6-k2", "m": "1.6", "c": 1, "k": "key idea", "f": "Complete the key idea: Magnitude = √(x² …", "b": "Magnitude = √(x² + y²); direction from tan⁻¹(y/x)"}, {"id": "1.6-k3", "m": "1.6", "c": 1, "k": "key idea", "f": "Complete the key idea: Add vectors …", "b": "Add vectors by adding components"}, {"id": "1.6-k4", "m": "1.6", "c": 1, "k": "key idea", "f": "Complete the key idea: a · b = a_x b_x …", "b": "a · b = a_x b_x + a_y b_y = |a||b| cos θ; zero when perpendicular"}, {"id": "1.6-q1", "m": "1.6", "c": 1, "k": "quick check", "f": "Displacement differs from distance because it", "b": "includes direction"}, {"id": "1.6-q2", "m": "1.6", "c": 1, "k": "quick check", "f": "(1, 2) + (3, −1) =", "b": "(4, 1)"}, {"id": "1.6-q3", "m": "1.6", "c": 1, "k": "quick check", "f": "The dot product of perpendicular vectors is", "b": "zero"}, {"id": "1.6-q4", "m": "1.6", "c": 1, "k": "quick check", "f": "A dot product is a", "b": "scalar"}, {"id": "1.6-p1", "m": "1.6", "c": 1, "k": "problem", "f": "Find the magnitude of the vector (6, 8).", "b": "10. = 10."}, {"id": "1.6-p2", "m": "1.6", "c": 1, "k": "problem", "f": "Which of these is a vector?", "b": "velocity. Only velocity needs a direction."}, {"id": "1.6-p3", "m": "1.6", "c": 1, "k": "problem", "f": "A walker goes 3 km east then 4 km north. What is the size of her displacement?", "b": "5 km. √(9 + 16) = 5 km."}, {"id": "1.6-p4", "m": "1.6", "c": 1, "k": "problem", "f": "Add (2, −5) and (7, 1). What is the magnitude of the result?", "b": "9.849. √(81 + 16) = √97 ≈ 9.85."}, {"id": "1.6-p5", "m": "1.6", "c": 1, "k": "problem", "f": "A plane flies at 250 km/h on a heading 30° north of east. What is its northward velocity component?", "b": "125 km/h. 250 × sin 30° = 125 km/h."}, {"id": "1.6-p6", "m": "1.6", "c": 1, "k": "problem", "f": "Calculate the dot product of (3, −2, 4) and (1, 5, 2).", "b": "1. 3 − 10 + 8 = 1."}, {"id": "1.6-p8", "m": "1.6", "c": 1, "k": "problem", "f": "Two vectors have a dot product of zero, and neither is the zero vector. What can you conclude, and why?", "b": "They are perpendicular. The dot product equals |a||b|cos θ. Neither magnitude is zero, so cos θ must be zero, which means θ = 90°."}, {"id": "1.7-e1", "m": "1.7", "c": 1, "k": "equation", "f": "Write the equation: Sum of two even numbers", "tex": "2m + 2n = 2(m+n)"}, {"id": "1.7-e2", "m": "1.7", "c": 1, "k": "equation", "f": "Write the equation: Root two, contradiction step", "tex": "\\sqrt{2} = \\frac{a}{b}\\ \\Rightarrow\\ a^2 = 2b^2"}, {"id": "1.7-e3", "m": "1.7", "c": 1, "k": "equation", "f": "Write the equation: Sum of first n integers (proved by pairing)", "tex": "1 + 2 + \\cdots + n = \\frac{n(n+1)}{2}"}, {"id": "1.7-k1", "m": "1.7", "c": 1, "k": "key idea", "f": "Complete the key idea: Theorems are proved from definitions …", "b": "Theorems are proved from definitions and axioms; they do not get overturned"}, {"id": "1.7-k2", "m": "1.7", "c": 1, "k": "key idea", "f": "Complete the key idea: One counter-example disproves a …", "b": "One counter-example disproves a general claim; one example proves nothing"}, {"id": "1.7-k3", "m": "1.7", "c": 1, "k": "key idea", "f": "Complete the key idea: Proof by contradiction: …", "b": "Proof by contradiction: assume the opposite, derive nonsense"}, {"id": "1.7-k4", "m": "1.7", "c": 1, "k": "key idea", "f": "Complete the key idea: Every model has …", "b": "Every model has assumptions; know where they break"}, {"id": "1.7-q1", "m": "1.7", "c": 1, "k": "quick check", "f": "One example that agrees with a general claim", "b": "proves nothing in general"}, {"id": "1.7-q2", "m": "1.7", "c": 1, "k": "quick check", "f": "√2 is", "b": "irrational"}, {"id": "1.7-q3", "m": "1.7", "c": 1, "k": "quick check", "f": "Checking what a formula predicts when a quantity goes to zero is a", "b": "limiting case"}, {"id": "1.7-q4", "m": "1.7", "c": 1, "k": "quick check", "f": "Every model", "b": "leaves something out"}, {"id": "1.7-p1", "m": "1.7", "c": 1, "k": "problem", "f": "Someone claims 'all prime numbers are odd'. What settles it?", "b": "The counter-example 2. 2 is prime and even."}, {"id": "1.7-p2", "m": "1.7", "c": 1, "k": "problem", "f": "Use the formula n(n+1)/2 to find 1 + 2 + … + 100.", "b": "5050. 100 × 101 ÷ 2 = 5050."}, {"id": "1.7-p3", "m": "1.7", "c": 1, "k": "problem", "f": "Prove that the product of two odd numbers is odd.", "b": "Write the odd numbers as 2m + 1 and 2n + 1. Their product is 4mn + 2m + 2n + 1 = 2(2mn + m + n) + 1, which is one more than an even number, so it is odd."}, {"id": "1.7-p4", "m": "1.7", "c": 1, "k": "problem", "f": "A model of a falling stone ignores air resistance. For which object does this assumption fail most badly?", "b": "a feather. A feather is light with a large surface."}, {"id": "1.7-p5", "m": "1.7", "c": 1, "k": "problem", "f": "Exponential growth predicts a bacterial colony doubling forever. Which observation shows the model has broken down?", "b": "Growth slows as nutrients run out. Slowing growth signals that limit."}, {"id": "1.7-p6", "m": "1.7", "c": 1, "k": "problem", "f": "A student derives that the time for a ball to fall a height h is t = √(2h/g). Check the formula in the limit h → 0 and by units.", "b": "If h = 0 then t = 0, which is right: no fall takes no time. Units: h in m, g in m/s², so h/g has units s², and its square root is s, a time. Both checks pass."}, {"id": "1.7-p7", "m": "1.7", "c": 1, "k": "problem", "f": "In a proof by contradiction, you", "b": "assume the statement is false and derive an impossibility. That is the definition of the method."}, {"id": "1.7-p8", "m": "1.7", "c": 1, "k": "problem", "f": "Explain why a scientific theory can be overturned but a mathematical theorem cannot.", "b": "A theorem follows by logic from stated definitions and axioms, so it stays true as long as those assumptions hold; nothing observed in the world can change a deduction. A scientific theory makes claims about the world and is tested against evidence, so new observations can show it is wrong or limited, as Newton's mechanics was shown to fail at very high speeds."}, {"id": "2.1-e1", "m": "2.1", "c": 2, "k": "equation", "f": "Write the equation: Distributive law", "tex": "a(b + c) = ab + ac"}, {"id": "2.1-e2", "m": "2.1", "c": 2, "k": "equation", "f": "Write the equation: Expanding two brackets", "tex": "(a + b)(c + d) = ac + ad + bc + bd"}, {"id": "2.1-e3", "m": "2.1", "c": 2, "k": "equation", "f": "Write the equation: Index laws", "tex": "x^a x^b = x^{a+b},\\quad \\frac{x^a}{x^b} = x^{a-b},\\quad (x^a)^b = x^{ab}"}, {"id": "2.1-e4", "m": "2.1", "c": 2, "k": "equation", "f": "Write the equation: Negative and fractional indices", "tex": "x^{-n} = \\frac{1}{x^n},\\qquad x^{1/n} = \\sqrt[n]{x}"}, {"id": "2.1-e5", "m": "2.1", "c": 2, "k": "equation", "f": "Write the equation: Difference of two squares", "tex": "a^2 - b^2 = (a - b)(a + b)"}, {"id": "2.1-k1", "m": "2.1", "c": 2, "k": "key idea", "f": "Complete the key idea: Only like …", "b": "Only like terms combine"}, {"id": "2.1-k2", "m": "2.1", "c": 2, "k": "key idea", "f": "Complete the key idea: Expanding and factorising are …", "b": "Expanding and factorising are inverses: check one with the other"}, {"id": "2.1-k3", "m": "2.1", "c": 2, "k": "key idea", "f": "Complete the key idea: xᵃxᵇ = xᵃ⁺ᵇ; (xᵃ)ᵇ = xᵃᵇ; …", "b": "xᵃxᵇ = xᵃ⁺ᵇ; (xᵃ)ᵇ = xᵃᵇ; x⁻ⁿ = 1/xⁿ; x^(1/n) is the nth root"}, {"id": "2.1-q1", "m": "2.1", "c": 2, "k": "quick check", "f": "3x and 3x² are", "b": "unlike terms"}, {"id": "2.1-q2", "m": "2.1", "c": 2, "k": "quick check", "f": "x⁻² equals", "b": "1/x²"}, {"id": "2.1-q3", "m": "2.1", "c": 2, "k": "quick check", "f": "x² + 5x + 6 factorises as", "b": "(x + 2)(x + 3)"}, {"id": "2.1-q4", "m": "2.1", "c": 2, "k": "quick check", "f": "x^(1/2) means", "b": "√x"}, {"id": "2.1-p1", "m": "2.1", "c": 2, "k": "problem", "f": "Simplify 4x + 3y − x + 2y.", "b": "3x + 5y. Collect y terms: 3y + 2y = 5y."}, {"id": "2.1-p2", "m": "2.1", "c": 2, "k": "problem", "f": "Expand 5(2x − 3).", "b": "10x − 15. Multiply each term by 5."}, {"id": "2.1-p3", "m": "2.1", "c": 2, "k": "problem", "f": "Expand (x + 4)(x − 2).", "b": "x² + 2x − 8. x² + 2x − 8."}, {"id": "2.1-p4", "m": "2.1", "c": 2, "k": "problem", "f": "Factorise x² − 7x + 12.", "b": "(x − 3)(x − 4). Two numbers with sum −7 and product 12: −3 and −4."}, {"id": "2.1-p5", "m": "2.1", "c": 2, "k": "problem", "f": "Factorise 9x² − 25.", "b": "(3x − 5)(3x + 5). Difference of two squares: (3x)² − 5²."}, {"id": "2.1-p6", "m": "2.1", "c": 2, "k": "problem", "f": "Evaluate 8^(2/3).", "b": "4. 2² = 4."}, {"id": "2.1-p7", "m": "2.1", "c": 2, "k": "problem", "f": "Simplify (x³ × x⁵) ÷ x².", "b": "x⁶. Divide: subtract to get x⁶."}, {"id": "2.2-e1", "m": "2.2", "c": 2, "k": "equation", "f": "Write the equation: Straight line", "tex": "y = mx + c"}, {"id": "2.2-e2", "m": "2.2", "c": 2, "k": "equation", "f": "Write the equation: Inequality sign flip", "tex": "-x > 3\\ \\Rightarrow\\ x < -3"}, {"id": "2.2-e3", "m": "2.2", "c": 2, "k": "equation", "f": "Write the equation: Gradient between two points", "tex": "m = \\frac{y_2 - y_1}{x_2 - x_1}"}, {"id": "2.2-k1", "m": "2.2", "c": 2, "k": "key idea", "f": "Complete the key idea: Do the same to …", "b": "Do the same to both sides; check by substitution"}, {"id": "2.2-k2", "m": "2.2", "c": 2, "k": "key idea", "f": "Complete the key idea: Multiplying or dividing an …", "b": "Multiplying or dividing an inequality by a negative flips its direction"}, {"id": "2.2-k3", "m": "2.2", "c": 2, "k": "key idea", "f": "Complete the key idea: Gradient = rise ÷ run; …", "b": "Gradient = rise ÷ run; in science it usually means something physical"}, {"id": "2.2-q1", "m": "2.2", "c": 2, "k": "quick check", "f": "Solve 2x = 18 − x.", "b": "x = 6"}, {"id": "2.2-q2", "m": "2.2", "c": 2, "k": "quick check", "f": "Dividing an inequality by −3", "b": "reverses its direction"}, {"id": "2.2-q3", "m": "2.2", "c": 2, "k": "quick check", "f": "In y = 3x − 5, the intercept is", "b": "−5"}, {"id": "2.2-q4", "m": "2.2", "c": 2, "k": "quick check", "f": "A line with gradient 0 is", "b": "horizontal"}, {"id": "2.2-p1", "m": "2.2", "c": 2, "k": "problem", "f": "Solve 4x + 7 = 31.", "b": "6. Divide by 4: x = 6."}, {"id": "2.2-p2", "m": "2.2", "c": 2, "k": "problem", "f": "Solve 3(x − 2) = 15.", "b": "7. 3x = 21, x = 7."}, {"id": "2.2-p3", "m": "2.2", "c": 2, "k": "problem", "f": "Solve x/4 + 2 = x/2 − 1.", "b": "12. 12 = x."}, {"id": "2.2-p4", "m": "2.2", "c": 2, "k": "problem", "f": "Solve 5 − 2x > 11.", "b": "x < −3. Divide by −2 and flip: x < −3."}, {"id": "2.2-p5", "m": "2.2", "c": 2, "k": "problem", "f": "Find the gradient of the line through (1, 3) and (5, 11).", "b": "2. = 2."}, {"id": "2.2-p6", "m": "2.2", "c": 2, "k": "problem", "f": "A taxi charges a $4 flag fall plus $2.50 per km. How far can you go for $29?", "b": "10 km. 2.5d = 25, d = 10 km."}, {"id": "2.2-p7", "m": "2.2", "c": 2, "k": "problem", "f": "On a graph of distance (m) against time (s), the gradient represents", "b": "speed. Gradient = change in distance ÷ change in time = speed."}, {"id": "2.3-e1", "m": "2.3", "c": 2, "k": "equation", "f": "Write the equation: Simple pendulum", "tex": "T = 2\\pi\\sqrt{\\frac{L}{g}}"}, {"id": "2.3-e2", "m": "2.3", "c": 2, "k": "equation", "f": "Write the equation: Rearranged for g", "tex": "g = \\frac{4\\pi^2 L}{T^2}"}, {"id": "2.3-e3", "m": "2.3", "c": 2, "k": "equation", "f": "Write the equation: Thin lens, rearranged for v", "tex": "\\frac{1}{f} = \\frac{1}{u} + \\frac{1}{v}\\ \\Rightarrow\\ v = \\frac{uf}{u - f}"}, {"id": "2.3-k1", "m": "2.3", "c": 2, "k": "key idea", "f": "Complete the key idea: Undo operations in reverse …", "b": "Undo operations in reverse order, applied to both whole sides"}, {"id": "2.3-k2", "m": "2.3", "c": 2, "k": "key idea", "f": "Complete the key idea: Flip only whole …", "b": "Flip only whole sides, never individual terms"}, {"id": "2.3-k3", "m": "2.3", "c": 2, "k": "key idea", "f": "Complete the key idea: Target twice: …", "b": "Target twice: collect, factor, divide"}, {"id": "2.3-q1", "m": "2.3", "c": 2, "k": "quick check", "f": "To solve T = 2π√(L/g) for g, the first step is", "b": "divide by 2π"}, {"id": "2.3-q2", "m": "2.3", "c": 2, "k": "quick check", "f": "If the target appears twice, you should", "b": "collect and factor"}, {"id": "2.3-q3", "m": "2.3", "c": 2, "k": "quick check", "f": "v = √(2E/m). If E is quadrupled, v", "b": "doubles"}, {"id": "2.3-q4", "m": "2.3", "c": 2, "k": "quick check", "f": "Taking the reciprocal is allowed", "b": "of a whole side only"}, {"id": "2.3-p7", "m": "2.3", "c": 2, "k": "problem", "f": "A pendulum clock must have a period of 2.00 s where g = 9.81 m/s². How long is the pendulum?", "b": "0.994 m. = 9.81 × 4 ÷ 39.48 ≈ 0.994 m."}, {"id": "2.3-p8", "m": "2.3", "c": 2, "k": "problem", "f": "From 1/f = 1/u + 1/v, a student writes f = u + v. The mistake is", "b": "flipping individual terms. The reciprocal of a sum is not the sum of reciprocals: 1/2 + 1/2 = 1, but 2 + 2 ≠ 1."}, {"id": "2.4-e1", "m": "2.4", "c": 2, "k": "equation", "f": "Write the equation: General transformation", "tex": "y = a\\,f\\left(b(x - h)\\right) + k"}, {"id": "2.4-e2", "m": "2.4", "c": 2, "k": "equation", "f": "Write the equation: Vertex form of a parabola", "tex": "y = a(x - h)^2 + k"}, {"id": "2.4-e3", "m": "2.4", "c": 2, "k": "equation", "f": "Write the equation: Composite and inverse", "tex": "(f \\circ g)(x) = f(g(x)),\\qquad f^{-1}(f(x)) = x"}, {"id": "2.4-k1", "m": "2.4", "c": 2, "k": "key idea", "f": "Complete the key idea: A function gives …", "b": "A function gives exactly one output per input"}, {"id": "2.4-k2", "m": "2.4", "c": 2, "k": "key idea", "f": "Complete the key idea: Domain: allowed …", "b": "Domain: allowed inputs. Range: resulting outputs"}, {"id": "2.4-k3", "m": "2.4", "c": 2, "k": "key idea", "f": "Complete the key idea: f(x − h) + k shifts …", "b": "f(x − h) + k shifts right h and up k; −f(x) reflects in the x-axis"}, {"id": "2.4-q1", "m": "2.4", "c": 2, "k": "quick check", "f": "A function can map one input to", "b": "exactly one output"}, {"id": "2.4-q2", "m": "2.4", "c": 2, "k": "quick check", "f": "y = f(x) + 3 is shifted", "b": "up 3"}, {"id": "2.4-q3", "m": "2.4", "c": 2, "k": "quick check", "f": "y = −f(x) is", "b": "reflected in the x-axis"}, {"id": "2.4-q4", "m": "2.4", "c": 2, "k": "quick check", "f": "The domain of 1/x excludes", "b": "x = 0"}, {"id": "2.4-p1", "m": "2.4", "c": 2, "k": "problem", "f": "If f(x) = 3x² − 2, find f(4).", "b": "46. = 46."}, {"id": "2.4-p2", "m": "2.4", "c": 2, "k": "problem", "f": "What is the domain of f(x) = √(x − 5)?", "b": "x ≥ 5. The quantity under the root must be ≥ 0: x − 5 ≥ 0."}, {"id": "2.4-p3", "m": "2.4", "c": 2, "k": "problem", "f": "The graph of y = (x + 3)² is the graph of y = x² shifted", "b": "3 left. x − h with h = −3: shift left by 3."}, {"id": "2.4-p4", "m": "2.4", "c": 2, "k": "problem", "f": "The vertex of y = 2(x − 1)² + 5 is at", "b": "(1, 5). Vertex form a(x − h)² + k has vertex (h, k)."}, {"id": "2.4-p5", "m": "2.4", "c": 2, "k": "problem", "f": "If f(x) = 2x + 1 and g(x) = x², find f(g(3)).", "b": "19. f(9) = 19."}, {"id": "2.4-p6", "m": "2.4", "c": 2, "k": "problem", "f": "What is the inverse of f(x) = (x − 4)/3?", "b": "3x + 4. So f⁻¹(x) = 3x + 4."}, {"id": "2.4-p7", "m": "2.4", "c": 2, "k": "problem", "f": "Which function has a vertical asymptote at x = 2?", "b": "y = 1/(x − 2). Division by zero at x = 2."}, {"id": "2.4-p8", "m": "2.4", "c": 2, "k": "problem", "f": "Sketch in words how y = −2(x − 3)² + 4 relates to y = x².", "b": "Shift right 3, stretch vertically by a factor of 2, reflect upside down, then shift up 4. It is an upside-down parabola, narrower than y = x², with its highest point at (3, 4)."}, {"id": "2.5-e1", "m": "2.5", "c": 2, "k": "equation", "f": "Write the equation: General two-variable system", "tex": "a_1 x + b_1 y = c_1,\\qquad a_2 x + b_2 y = c_2"}, {"id": "2.5-e2", "m": "2.5", "c": 2, "k": "equation", "f": "Write the equation: Elimination step", "tex": "(2x + 3y) - (2x - y) = 12 - 4\\ \\Rightarrow\\ 4y = 8"}, {"id": "2.5-k1", "m": "2.5", "c": 2, "k": "key idea", "f": "Complete the key idea: Substitute when one …", "b": "Substitute when one variable is easy to isolate"}, {"id": "2.5-k2", "m": "2.5", "c": 2, "k": "key idea", "f": "Complete the key idea: Eliminate by …", "b": "Eliminate by matching coefficients and subtracting"}, {"id": "2.5-k3", "m": "2.5", "c": 2, "k": "key idea", "f": "Complete the key idea: Solution = intersection; …", "b": "Solution = intersection; parallel lines mean no solution"}, {"id": "2.5-q1", "m": "2.5", "c": 2, "k": "quick check", "f": "Elimination works by", "b": "cancelling one variable"}, {"id": "2.5-q2", "m": "2.5", "c": 2, "k": "quick check", "f": "Parallel lines give", "b": "no solution"}, {"id": "2.5-q3", "m": "2.5", "c": 2, "k": "quick check", "f": "Three unknowns generally need", "b": "three equations"}, {"id": "2.5-q4", "m": "2.5", "c": 2, "k": "quick check", "f": "Solve x = 2y and x + y = 9: y =", "b": "3"}, {"id": "2.5-p1", "m": "2.5", "c": 2, "k": "problem", "f": "Solve x + y = 10 and x − y = 4.", "b": "x = 7, y = 3. y = 3."}, {"id": "2.5-p2", "m": "2.5", "c": 2, "k": "problem", "f": "Solve 3x + 2y = 16 and x − y = 2. What is x?", "b": "4. 3(y + 2) + 2y = 16 → 5y = 10 → y = 2, x = 4."}, {"id": "2.5-p3", "m": "2.5", "c": 2, "k": "problem", "f": "Solve 2x + 5y = 19 and 3x − 2y = 0. What is y?", "b": "3. Subtract: 19y = 57, y = 3."}, {"id": "2.5-p4", "m": "2.5", "c": 2, "k": "problem", "f": "Adult tickets cost $15 and child tickets $8. 40 tickets raised $467. How many adult tickets were sold?", "b": "21. 15a + 8(40 − a) = 467 → 7a = 147 → a = 21."}, {"id": "2.5-p5", "m": "2.5", "c": 2, "k": "problem", "f": "The system y = 2x + 1 and y = 2x − 3 has", "b": "no solution. Same gradient, different intercepts: parallel lines."}, {"id": "2.5-p6", "m": "2.5", "c": 2, "k": "problem", "f": "How many litres of 10% salt solution must be mixed with 30% solution to make 20 L of 25% solution?", "b": "5 L. 0.1x + 0.3(20 − x) = 5 → −0.2x = −1 → x = 5 L."}, {"id": "2.5-p8", "m": "2.5", "c": 2, "k": "problem", "f": "Explain geometrically why two linear equations in two unknowns can have exactly one, none, or infinitely many solutions, but never exactly two.", "b": "Each equation is a straight line. Two distinct straight lines either cross at exactly one point or are parallel and never meet. If they are the same line, every point is shared. Two straight lines cannot cross twice."}, {"id": "2.6-e1", "m": "2.6", "c": 2, "k": "equation", "f": "Write the equation: Quadratic formula", "tex": "x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}"}, {"id": "2.6-e2", "m": "2.6", "c": 2, "k": "equation", "f": "Write the equation: Discriminant", "tex": "\\Delta = b^2 - 4ac"}, {"id": "2.6-e3", "m": "2.6", "c": 2, "k": "equation", "f": "Write the equation: Factor theorem", "tex": "p(k) = 0\\ \\Leftrightarrow\\ (x - k)\\ \\mathrm{is\\ a\\ factor}"}, {"id": "2.6-e4", "m": "2.6", "c": 2, "k": "equation", "f": "Write the equation: Vertex of y = ax² + bx + c", "tex": "x_{\\mathrm{vertex}} = -\\frac{b}{2a}"}, {"id": "2.6-k1", "m": "2.6", "c": 2, "k": "key idea", "f": "Complete the key idea: Quadratic formula …", "b": "Quadratic formula solves every quadratic"}, {"id": "2.6-k2", "m": "2.6", "c": 2, "k": "key idea", "f": "Complete the key idea: Discriminant > 0: two …", "b": "Discriminant > 0: two roots; = 0: one; < 0: none"}, {"id": "2.6-k3", "m": "2.6", "c": 2, "k": "key idea", "f": "Complete the key idea: If p(k) = 0 …", "b": "If p(k) = 0 then (x − k) is a factor"}, {"id": "2.6-q1", "m": "2.6", "c": 2, "k": "quick check", "f": "If b² − 4ac < 0, the quadratic has", "b": "no real roots"}, {"id": "2.6-q2", "m": "2.6", "c": 2, "k": "quick check", "f": "A cubic has at most how many real roots?", "b": "3"}, {"id": "2.6-q3", "m": "2.6", "c": 2, "k": "quick check", "f": "The vertex of y = ax² + bx + c is at x =", "b": "−b/2a"}, {"id": "2.6-q4", "m": "2.6", "c": 2, "k": "quick check", "f": "x² − 4 = 0 has roots", "b": "±2"}, {"id": "2.6-p1", "m": "2.6", "c": 2, "k": "problem", "f": "Solve x² − 9x + 20 = 0.", "b": "4 and 5. Factorise: (x − 4)(x − 5) = 0."}, {"id": "2.6-p2", "m": "2.6", "c": 2, "k": "problem", "f": "Use the quadratic formula to find the larger root of 2x² − 3x − 5 = 0.", "b": "2.5. x = (3 ± 7)/4: 2.5 or −1."}, {"id": "2.6-p3", "m": "2.6", "c": 2, "k": "problem", "f": "Find the discriminant of 3x² + 4x + 2.", "b": "-8. = −8, so no real roots."}, {"id": "2.6-p4", "m": "2.6", "c": 2, "k": "problem", "f": "Find the x-coordinate of the vertex of y = x² − 6x + 11.", "b": "3. = 3."}, {"id": "2.6-p5", "m": "2.6", "c": 2, "k": "problem", "f": "A ball's height is h = 20t − 5t² metres. After how many seconds does it land?", "b": "4 s. t = 0 (launch) or t = 4 s."}, {"id": "2.6-p6", "m": "2.6", "c": 2, "k": "problem", "f": "For the same ball, h = 20t − 5t², what is the maximum height?", "b": "20 m. h = 40 − 20 = 20 m."}, {"id": "2.6-p7", "m": "2.6", "c": 2, "k": "problem", "f": "p(x) = x³ − 6x² + 11x − 6 and p(1) = 0. Which is a factor?", "b": "x − 1. Factor theorem: p(1) = 0 means (x − 1) is a factor."}, {"id": "2.6-p8", "m": "2.6", "c": 2, "k": "problem", "f": "For which value of k does x² + kx + 9 = 0 have exactly one root (k > 0)?", "b": "6. k = 6."}, {"id": "2.7-e1", "m": "2.7", "c": 2, "k": "equation", "f": "Write the equation: Discrete growth", "tex": "N = N_0(1 + r)^t"}, {"id": "2.7-e2", "m": "2.7", "c": 2, "k": "equation", "f": "Write the equation: Continuous growth and decay", "tex": "N = N_0 e^{kt}"}, {"id": "2.7-e3", "m": "2.7", "c": 2, "k": "equation", "f": "Write the equation: Log laws", "tex": "\\log(ab) = \\log a + \\log b,\\quad \\log\\frac{a}{b} = \\log a - \\log b,\\quad \\log a^n = n\\log a"}, {"id": "2.7-e4", "m": "2.7", "c": 2, "k": "equation", "f": "Write the equation: Half-life", "tex": "t_{1/2} = \\frac{\\ln 2}{k}"}, {"id": "2.7-e5", "m": "2.7", "c": 2, "k": "equation", "f": "Write the equation: Solving an exponential", "tex": "a^x = b\\ \\Rightarrow\\ x = \\frac{\\ln b}{\\ln a}"}, {"id": "2.7-k1", "m": "2.7", "c": 2, "k": "key idea", "f": "Complete the key idea: Exponential: multiply by …", "b": "Exponential: multiply by the same factor each step"}, {"id": "2.7-k2", "m": "2.7", "c": 2, "k": "key idea", "f": "Complete the key idea: Logs undo exponentials; …", "b": "Logs undo exponentials; log(aᵇ) = b log a"}, {"id": "2.7-k3", "m": "2.7", "c": 2, "k": "key idea", "f": "Complete the key idea: Half-life and doubling time are …", "b": "Half-life and doubling time are constant; t½ = ln 2 / k"}, {"id": "2.7-k4", "m": "2.7", "c": 2, "k": "key idea", "f": "Complete the key idea: Log scales: …", "b": "Log scales: +1 means ×10"}, {"id": "2.7-q1", "m": "2.7", "c": 2, "k": "quick check", "f": "log(ab) equals", "b": "log a + log b"}, {"id": "2.7-q2", "m": "2.7", "c": 2, "k": "quick check", "f": "After 2 half-lives, the fraction remaining is", "b": "¼"}, {"id": "2.7-q3", "m": "2.7", "c": 2, "k": "quick check", "f": "ln is the logarithm to base", "b": "e"}, {"id": "2.7-q4", "m": "2.7", "c": 2, "k": "quick check", "f": "On a log scale, an increase of 2 means", "b": "×100"}, {"id": "2.7-p1", "m": "2.7", "c": 2, "k": "problem", "f": "Evaluate log₁₀ 10 000.", "b": "4. 10⁴ = 10 000."}, {"id": "2.7-p2", "m": "2.7", "c": 2, "k": "problem", "f": "A sample has a half-life of 6 hours. What fraction remains after 18 hours? Give a decimal.", "b": "0.125. (½)³ = 0.125."}, {"id": "2.7-p3", "m": "2.7", "c": 2, "k": "problem", "f": "Solve 2ˣ = 50, to 3 significant figures.", "b": "5.644. = 3.912 ÷ 0.693 ≈ 5.64."}, {"id": "2.7-p4", "m": "2.7", "c": 2, "k": "problem", "f": "$1000 is invested at 5% a year compounded annually. What is it worth after 10 years?", "b": "1629 dollars. ≈ $1629."}, {"id": "2.7-p5", "m": "2.7", "c": 2, "k": "problem", "f": "Using the rule of 70, estimate the doubling time for growth of 7% a year.", "b": "10 years. 70 ÷ 7 = 10 years."}, {"id": "2.7-p6", "m": "2.7", "c": 2, "k": "problem", "f": "A substance decays with k = 0.1 per day. What is its half-life?", "b": "6.931 days. 0.693 ÷ 0.1 ≈ 6.93 days."}, {"id": "2.7-p7", "m": "2.7", "c": 2, "k": "problem", "f": "How many times more acidic is a solution of pH 2 than one of pH 5?", "b": "1000 ×. 10³ = 1000."}, {"id": "2.7-p8", "m": "2.7", "c": 2, "k": "problem", "f": "Simplify ln(e⁵) + log₁₀(100).", "b": "7. 5 + 2 = 7."}, {"id": "2.8-e1", "m": "2.8", "c": 2, "k": "equation", "f": "Write the equation: Definition of the derivative", "tex": "\\frac{dy}{dx} = \\lim_{h \\to 0}\\frac{f(x + h) - f(x)}{h}"}, {"id": "2.8-e2", "m": "2.8", "c": 2, "k": "equation", "f": "Write the equation: Power rule", "tex": "\\frac{d}{dx}x^n = n x^{n-1}"}, {"id": "2.8-e3", "m": "2.8", "c": 2, "k": "equation", "f": "Write the equation: Two special derivatives", "tex": "\\frac{d}{dx}e^x = e^x,\\qquad \\frac{d}{dx}\\sin x = \\cos x"}, {"id": "2.8-e4", "m": "2.8", "c": 2, "k": "equation", "f": "Write the equation: Area under a curve", "tex": "\\int_a^b f(x)\\,dx"}, {"id": "2.8-e5", "m": "2.8", "c": 2, "k": "equation", "f": "Write the equation: Integrating a power", "tex": "\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C\\quad (n \\neq -1)"}, {"id": "2.8-k1", "m": "2.8", "c": 2, "k": "key idea", "f": "Complete the key idea: Derivative = instantaneous rate …", "b": "Derivative = instantaneous rate of change = gradient of the tangent"}, {"id": "2.8-k2", "m": "2.8", "c": 2, "k": "key idea", "f": "Complete the key idea: Power rule: …", "b": "Power rule: d/dx(xⁿ) = nxⁿ⁻¹"}, {"id": "2.8-k3", "m": "2.8", "c": 2, "k": "key idea", "f": "Complete the key idea: Derivative zero …", "b": "Derivative zero at peaks and troughs"}, {"id": "2.8-k4", "m": "2.8", "c": 2, "k": "key idea", "f": "Complete the key idea: Integral = area under …", "b": "Integral = area under the curve = accumulated total"}, {"id": "2.8-q1", "m": "2.8", "c": 2, "k": "quick check", "f": "The derivative of a constant is", "b": "0"}, {"id": "2.8-q2", "m": "2.8", "c": 2, "k": "quick check", "f": "Velocity is the derivative of", "b": "position"}, {"id": "2.8-q3", "m": "2.8", "c": 2, "k": "quick check", "f": "The area under a speed-time graph gives", "b": "distance"}, {"id": "2.8-q4", "m": "2.8", "c": 2, "k": "quick check", "f": "d/dx(eˣ) =", "b": "eˣ"}, {"id": "2.8-p1", "m": "2.8", "c": 2, "k": "problem", "f": "Differentiate y = x⁴.", "b": "4x³. Bring down 4, reduce power to 3."}, {"id": "2.8-p2", "m": "2.8", "c": 2, "k": "problem", "f": "Differentiate y = 3x² + 5x − 7.", "b": "6x + 5. 3 × 2x + 5 + 0."}, {"id": "2.8-p3", "m": "2.8", "c": 2, "k": "problem", "f": "For y = x³ − 2x, find the gradient at x = 2.", "b": "10. At x = 2: 12 − 2 = 10."}, {"id": "2.8-p4", "m": "2.8", "c": 2, "k": "problem", "f": "A ball's height is h = 30t − 5t². What is its velocity, dh/dt, at t = 1 s?", "b": "20 m/s. At t = 1: 20 m/s."}, {"id": "2.8-p5", "m": "2.8", "c": 2, "k": "problem", "f": "For h = 30t − 5t², at what time is the ball at its highest?", "b": "3 s. t = 3 s."}, {"id": "2.8-p6", "m": "2.8", "c": 2, "k": "problem", "f": "A car's speed rises steadily from 0 to 20 m/s in 10 s. How far does it travel in that time (area under the graph)?", "b": "100 m. ½ × 10 × 20 = 100 m."}, {"id": "2.8-p7", "m": "2.8", "c": 2, "k": "problem", "f": "Evaluate the integral of 2x from x = 0 to x = 3.", "b": "9. 3² − 0² = 9."}, {"id": "2.8-p8", "m": "2.8", "c": 2, "k": "problem", "f": "Explain in words what dV/dt = −0.5 litres per minute means for a draining tank.", "b": "The volume of water V is changing over time t at a rate of −0.5 litres per minute: the tank is losing half a litre every minute at that moment. The negative sign means volume is decreasing."}, {"id": "3.1-e1", "m": "3.1", "c": 3, "k": "equation", "f": "Write the equation: Constant-acceleration equations", "tex": "v = u + at,\\quad s = ut + \\frac{1}{2}at^2,\\quad v^2 = u^2 + 2as,\\quad s = \\frac{(u+v)t}{2}"}, {"id": "3.1-e2", "m": "3.1", "c": 3, "k": "equation", "f": "Write the equation: Launch components", "tex": "u_x = u\\cos\\theta,\\qquad u_y = u\\sin\\theta"}, {"id": "3.1-e3", "m": "3.1", "c": 3, "k": "equation", "f": "Write the equation: Range on level ground", "tex": "R = \\frac{u^2\\sin 2\\theta}{g}"}, {"id": "3.1-k1", "m": "3.1", "c": 3, "k": "key idea", "f": "Complete the key idea: Gradient of x–t is velocity; gradient …", "b": "Gradient of x–t is velocity; gradient of v–t is acceleration; area under v–t is displacement"}, {"id": "3.1-k2", "m": "3.1", "c": 3, "k": "key idea", "f": "Complete the key idea: SUVAT equations …", "b": "SUVAT equations need constant acceleration"}, {"id": "3.1-k3", "m": "3.1", "c": 3, "k": "key idea", "f": "Complete the key idea: Projectiles: horizontal and …", "b": "Projectiles: horizontal and vertical motions are independent"}, {"id": "3.1-q1", "m": "3.1", "c": 3, "k": "quick check", "f": "The area under a velocity–time graph gives", "b": "displacement"}, {"id": "3.1-q2", "m": "3.1", "c": 3, "k": "quick check", "f": "A car at constant speed around a bend is", "b": "accelerating"}, {"id": "3.1-q3", "m": "3.1", "c": 3, "k": "quick check", "f": "Ignoring air, a projectile's horizontal velocity", "b": "stays constant"}, {"id": "3.1-q4", "m": "3.1", "c": 3, "k": "quick check", "f": "Range on level ground is greatest at", "b": "45°"}, {"id": "3.1-p1", "m": "3.1", "c": 3, "k": "problem", "f": "A cyclist accelerates from 2 m/s to 8 m/s in 4 s. What is her acceleration?", "b": "1.5 m/s². (8 − 2) ÷ 4 = 1.5 m/s²."}, {"id": "3.1-p2", "m": "3.1", "c": 3, "k": "problem", "f": "A stone is dropped from rest. How fast is it falling after 3 s? (g = 9.8 m/s²)", "b": "29.4 m/s. v = u + at = 0 + 9.8 × 3."}, {"id": "3.1-p3", "m": "3.1", "c": 3, "k": "problem", "f": "How far does that stone fall in 3 s?", "b": "44.1 m. ½ × 9.8 × 9 = 44.1 m."}, {"id": "3.1-p4", "m": "3.1", "c": 3, "k": "problem", "f": "A car travelling at 25 m/s brakes at 5 m/s². What is its stopping distance?", "b": "62.5 m. 0 = 625 − 10s, s = 62.5 m."}, {"id": "3.1-p5", "m": "3.1", "c": 3, "k": "problem", "f": "A ball is thrown straight up at 14 m/s. How high does it go?", "b": "10 m. s = 196 ÷ 19.6 = 10 m."}, {"id": "3.1-p6", "m": "3.1", "c": 3, "k": "problem", "f": "A ball rolls off a 1.25 m high table at 3.0 m/s. How far from the table does it land?", "b": "1.515 m. Horizontal: 3.0 × 0.505 ≈ 1.5 m."}, {"id": "3.1-p8", "m": "3.1", "c": 3, "k": "problem", "f": "At the top of a ball's flight, its acceleration is", "b": "9.8 m/s² downwards. Gravity still acts. Velocity is momentarily zero, not acceleration."}, {"id": "3.2-e1", "m": "3.2", "c": 3, "k": "equation", "f": "Write the equation: Newton's second law", "tex": "F_{\\mathrm{net}} = ma"}, {"id": "3.2-e2", "m": "3.2", "c": 3, "k": "equation", "f": "Write the equation: Weight", "tex": "W = mg"}, {"id": "3.2-e3", "m": "3.2", "c": 3, "k": "equation", "f": "Write the equation: Friction", "tex": "F_f \\leq \\mu N"}, {"id": "3.2-e4", "m": "3.2", "c": 3, "k": "equation", "f": "Write the equation: Centripetal acceleration and force", "tex": "a = \\frac{v^2}{r},\\qquad F = \\frac{mv^2}{r}"}, {"id": "3.2-k1", "m": "3.2", "c": 3, "k": "key idea", "f": "Complete the key idea: Net force …", "b": "Net force = mass × acceleration"}, {"id": "3.2-k2", "m": "3.2", "c": 3, "k": "key idea", "f": "Complete the key idea: Action–reaction pairs …", "b": "Action–reaction pairs act on different objects"}, {"id": "3.2-k3", "m": "3.2", "c": 3, "k": "key idea", "f": "Complete the key idea: Free-body diagram first, then …", "b": "Free-body diagram first, then resolve and apply F = ma"}, {"id": "3.2-k4", "m": "3.2", "c": 3, "k": "key idea", "f": "Complete the key idea: Circular motion needs …", "b": "Circular motion needs an inward force mv²/r"}, {"id": "3.2-q1", "m": "3.2", "c": 3, "k": "quick check", "f": "A body moving at constant velocity has net force", "b": "zero"}, {"id": "3.2-q2", "m": "3.2", "c": 3, "k": "quick check", "f": "Doubling mass with the same force", "b": "halves acceleration"}, {"id": "3.2-q3", "m": "3.2", "c": 3, "k": "quick check", "f": "Centripetal force points", "b": "towards the centre"}, {"id": "3.2-q4", "m": "3.2", "c": 3, "k": "quick check", "f": "Third-law force pairs act on", "b": "different objects"}, {"id": "3.2-p1", "m": "3.2", "c": 3, "k": "problem", "f": "What net force gives a 1200 kg car an acceleration of 2.5 m/s²?", "b": "3000 N. F = ma = 1200 × 2.5."}, {"id": "3.2-p2", "m": "3.2", "c": 3, "k": "problem", "f": "What is the weight of a 65 kg person on Earth (g = 9.8 m/s²)?", "b": "637 N. W = mg = 65 × 9.8."}, {"id": "3.2-p3", "m": "3.2", "c": 3, "k": "problem", "f": "A 10 kg box is pushed with 50 N across a floor where friction is 20 N. What is its acceleration?", "b": "3 m/s². a = 30 ÷ 10 = 3 m/s²."}, {"id": "3.2-p4", "m": "3.2", "c": 3, "k": "problem", "f": "A 5 kg block sits on a frictionless 30° slope. What is its acceleration down the slope?", "b": "4.9 m/s². a = g sin 30° = 4.9 m/s²."}, {"id": "3.2-p5", "m": "3.2", "c": 3, "k": "problem", "f": "A crate of mass 40 kg rests on the floor. The coefficient of friction is 0.30. What horizontal force is needed to start it sliding?", "b": "117.6 N. F = μN = 0.30 × 392 ≈ 118 N."}, {"id": "3.2-p6", "m": "3.2", "c": 3, "k": "problem", "f": "A 0.5 kg ball on a 0.8 m string is swung in a horizontal circle at 4 m/s. What is the tension (ignore gravity)?", "b": "10 N. 0.5 × 16 ÷ 0.8 = 10 N."}, {"id": "3.2-p7", "m": "3.2", "c": 3, "k": "problem", "f": "A book rests on a table. The reaction partner (Newton's third law) of the book's weight is", "b": "the book's gravitational pull on Earth. The weight is Earth pulling the book. Its partner is the book pulling Earth."}, {"id": "3.3-e1", "m": "3.3", "c": 3, "k": "equation", "f": "Write the equation: Work", "tex": "W = Fd\\cos\\theta"}, {"id": "3.3-e2", "m": "3.3", "c": 3, "k": "equation", "f": "Write the equation: Kinetic energy", "tex": "E_k = \\frac{1}{2}mv^2"}, {"id": "3.3-e3", "m": "3.3", "c": 3, "k": "equation", "f": "Write the equation: Gravitational potential energy", "tex": "E_p = mgh"}, {"id": "3.3-e4", "m": "3.3", "c": 3, "k": "equation", "f": "Write the equation: Power", "tex": "P = \\frac{E}{t} = Fv"}, {"id": "3.3-e5", "m": "3.3", "c": 3, "k": "equation", "f": "Write the equation: Efficiency", "tex": "\\eta = \\frac{E_{\\mathrm{useful}}}{E_{\\mathrm{in}}} \\times 100\\%"}, {"id": "3.3-k1", "m": "3.3", "c": 3, "k": "key idea", "f": "Complete the key idea: Work = force × …", "b": "Work = force × distance in the direction of the force"}, {"id": "3.3-k2", "m": "3.3", "c": 3, "k": "key idea", "f": "Complete the key idea: KE = ½mv²; GPE …", "b": "KE = ½mv²; GPE = mgh; total energy is conserved"}, {"id": "3.3-k3", "m": "3.3", "c": 3, "k": "key idea", "f": "Complete the key idea: Power = energy ÷ …", "b": "Power = energy ÷ time; a kWh is energy"}, {"id": "3.3-k4", "m": "3.3", "c": 3, "k": "key idea", "f": "Complete the key idea: Efficiency = useful …", "b": "Efficiency = useful out ÷ total in"}, {"id": "3.3-q1", "m": "3.3", "c": 3, "k": "quick check", "f": "The unit of energy is the", "b": "joule"}, {"id": "3.3-q2", "m": "3.3", "c": 3, "k": "quick check", "f": "Doubling speed multiplies kinetic energy by", "b": "4"}, {"id": "3.3-q3", "m": "3.3", "c": 3, "k": "quick check", "f": "A kilowatt-hour measures", "b": "energy"}, {"id": "3.3-q4", "m": "3.3", "c": 3, "k": "quick check", "f": "Holding a weight still does how much work on it?", "b": "zero"}, {"id": "3.3-p1", "m": "3.3", "c": 3, "k": "problem", "f": "How much work is done lifting a 20 kg box 1.5 m? (g = 9.8)", "b": "294 J. 20 × 9.8 × 1.5 = 294 J."}, {"id": "3.3-p2", "m": "3.3", "c": 3, "k": "problem", "f": "What is the kinetic energy of a 1000 kg car at 20 m/s?", "b": "2.000e+05 J. ½ × 1000 × 400 = 200 000 J."}, {"id": "3.3-p3", "m": "3.3", "c": 3, "k": "problem", "f": "A ball is dropped from 5.0 m. Ignoring air resistance, how fast is it moving when it hits the ground?", "b": "9.899 m/s. √(98) ≈ 9.9 m/s."}, {"id": "3.3-p4", "m": "3.3", "c": 3, "k": "problem", "f": "A 60 kg climber gains 300 m of height in 20 minutes. What is her average power output against gravity?", "b": "147 W. ÷ 1200 s ≈ 147 W."}, {"id": "3.3-p5", "m": "3.3", "c": 3, "k": "problem", "f": "A 2.0 kW kettle runs for 3 minutes. How many joules does it use?", "b": "3.600e+05 J. = 360 000 J."}, {"id": "3.3-p6", "m": "3.3", "c": 3, "k": "problem", "f": "A motor uses 500 J of electrical energy to lift a load, gaining 350 J of potential energy. What is its efficiency?", "b": "70 %. 350 ÷ 500 = 0.70."}, {"id": "3.3-p7", "m": "3.3", "c": 3, "k": "problem", "f": "A rope pulls a sled 10 m with 80 N at 30° to the ground. How much work is done?", "b": "692.8 J. 80 × 10 × 0.866 ≈ 693 J."}, {"id": "3.4-e1", "m": "3.4", "c": 3, "k": "equation", "f": "Write the equation: Momentum", "tex": "p = mv"}, {"id": "3.4-e2", "m": "3.4", "c": 3, "k": "equation", "f": "Write the equation: Impulse", "tex": "F\\,\\Delta t = \\Delta p"}, {"id": "3.4-e3", "m": "3.4", "c": 3, "k": "equation", "f": "Write the equation: Conservation of momentum", "tex": "m_1u_1 + m_2u_2 = m_1v_1 + m_2v_2"}, {"id": "3.4-e4", "m": "3.4", "c": 3, "k": "equation", "f": "Write the equation: Torque", "tex": "\\tau = Fr_\\perp"}, {"id": "3.4-e5", "m": "3.4", "c": 3, "k": "equation", "f": "Write the equation: Angular momentum", "tex": "L = I\\omega"}, {"id": "3.4-k1", "m": "3.4", "c": 3, "k": "key idea", "f": "Complete the key idea: Momentum p = …", "b": "Momentum p = mv; impulse FΔt = Δp"}, {"id": "3.4-k2", "m": "3.4", "c": 3, "k": "key idea", "f": "Complete the key idea: Total momentum is …", "b": "Total momentum is conserved without external forces"}, {"id": "3.4-k3", "m": "3.4", "c": 3, "k": "key idea", "f": "Complete the key idea: Elastic collisions conserve …", "b": "Elastic collisions conserve KE; inelastic do not"}, {"id": "3.4-k4", "m": "3.4", "c": 3, "k": "key idea", "f": "Complete the key idea: Torque = force × …", "b": "Torque = force × perpendicular distance; angular momentum is conserved"}, {"id": "3.4-q1", "m": "3.4", "c": 3, "k": "quick check", "f": "Momentum is", "b": "a vector"}, {"id": "3.4-q2", "m": "3.4", "c": 3, "k": "quick check", "f": "In all collisions without external forces, what is conserved?", "b": "momentum"}, {"id": "3.4-q3", "m": "3.4", "c": 3, "k": "quick check", "f": "Torque depends on force and", "b": "perpendicular distance from pivot"}, {"id": "3.4-q4", "m": "3.4", "c": 3, "k": "quick check", "f": "Impulse equals", "b": "change in momentum"}, {"id": "3.4-p1", "m": "3.4", "c": 3, "k": "problem", "f": "What is the momentum of a 0.16 kg cricket ball moving at 30 m/s?", "b": "4.8 kg m/s. p = mv = 0.16 × 30."}, {"id": "3.4-p2", "m": "3.4", "c": 3, "k": "problem", "f": "A 1500 kg car at 20 m/s hits a stationary 1000 kg car and they lock together. What is their speed just after?", "b": "12 m/s. v = 30 000 ÷ 2500 = 12 m/s."}, {"id": "3.4-p3", "m": "3.4", "c": 3, "k": "problem", "f": "A 0.06 kg tennis ball arrives at 20 m/s and leaves in the opposite direction at 30 m/s. What impulse did the racket give?", "b": "3 N s. = 3.0 N s."}, {"id": "3.4-p4", "m": "3.4", "c": 3, "k": "problem", "f": "If that contact lasted 0.005 s, what was the average force?", "b": "600 N. F = Δp/Δt = 3.0 ÷ 0.005 = 600 N."}, {"id": "3.4-p5", "m": "3.4", "c": 3, "k": "problem", "f": "Airbags reduce injury mainly because they", "b": "increase collision time. Same Δp over a longer time means smaller force."}, {"id": "3.4-p6", "m": "3.4", "c": 3, "k": "problem", "f": "A 30 N force acts at right angles to a spanner 0.25 m from the bolt. What is the torque?", "b": "7.5 N m. τ = Fr = 30 × 0.25."}, {"id": "3.4-p7", "m": "3.4", "c": 3, "k": "problem", "f": "A 4.0 kg rifle fires a 0.010 kg bullet at 600 m/s. What is the rifle's recoil speed?", "b": "1.5 m/s. 4v = 0.01 × 600, v = 1.5 m/s."}, {"id": "3.4-p8", "m": "3.4", "c": 3, "k": "problem", "f": "A spinning skater pulls in her arms, halving her moment of inertia. Her rotation rate", "b": "doubles. Halve I, double ω."}, {"id": "3.5-e1", "m": "3.5", "c": 3, "k": "equation", "f": "Write the equation: Wave equation", "tex": "v = f\\lambda,\\qquad T = \\frac{1}{f}"}, {"id": "3.5-e2", "m": "3.5", "c": 3, "k": "equation", "f": "Write the equation: String fixed at both ends", "tex": "\\lambda_n = \\frac{2L}{n},\\qquad f_n = \\frac{nv}{2L}"}, {"id": "3.5-e3", "m": "3.5", "c": 3, "k": "equation", "f": "Write the equation: Doppler, moving source", "tex": "f' = f\\,\\frac{v}{v \\mp v_s}"}, {"id": "3.5-k1", "m": "3.5", "c": 3, "k": "key idea", "f": "Complete the key idea: Transverse: perpendicular …", "b": "Transverse: perpendicular oscillation; longitudinal: parallel"}, {"id": "3.5-k2", "m": "3.5", "c": 3, "k": "key idea", "f": "Complete the key idea: v = fλ; speed …", "b": "v = fλ; speed is set by the medium"}, {"id": "3.5-k3", "m": "3.5", "c": 3, "k": "key idea", "f": "Complete the key idea: Waves superpose; standing …", "b": "Waves superpose; standing waves have fixed nodes"}, {"id": "3.5-k4", "m": "3.5", "c": 3, "k": "key idea", "f": "Complete the key idea: Doppler: approaching …", "b": "Doppler: approaching source, higher frequency"}, {"id": "3.5-q1", "m": "3.5", "c": 3, "k": "quick check", "f": "v = fλ: doubling frequency in the same medium", "b": "halves wavelength"}, {"id": "3.5-q2", "m": "3.5", "c": 3, "k": "quick check", "f": "Destructive interference occurs when", "b": "peak meets trough"}, {"id": "3.5-q3", "m": "3.5", "c": 3, "k": "quick check", "f": "Points on a standing wave that never move are", "b": "nodes"}, {"id": "3.5-q4", "m": "3.5", "c": 3, "k": "quick check", "f": "A receding source sounds", "b": "lower"}, {"id": "3.5-p1", "m": "3.5", "c": 3, "k": "problem", "f": "A wave has frequency 50 Hz and wavelength 4 m. What is its speed?", "b": "200 m/s. v = fλ = 50 × 4."}, {"id": "3.5-p2", "m": "3.5", "c": 3, "k": "problem", "f": "What is the period of a 250 Hz sound?", "b": "0.004 s. T = 1/f = 1/250."}, {"id": "3.5-p3", "m": "3.5", "c": 3, "k": "problem", "f": "Sound travels at 340 m/s. What is the wavelength of a 440 Hz note?", "b": "0.7727 m. λ = v/f = 340 ÷ 440 ≈ 0.77 m."}, {"id": "3.5-p4", "m": "3.5", "c": 3, "k": "problem", "f": "You see lightning and hear thunder 3 s later. Sound travels at 340 m/s. How far away was the strike?", "b": "1020 m. d = 340 × 3 = 1020 m."}, {"id": "3.5-p5", "m": "3.5", "c": 3, "k": "problem", "f": "A guitar string 0.65 m long carries waves at 420 m/s. What is its fundamental (n = 1) frequency?", "b": "323.1 Hz. 420 ÷ 1.3 ≈ 323 Hz."}, {"id": "3.5-p6", "m": "3.5", "c": 3, "k": "problem", "f": "Sound passes from air into water, where it travels faster. Its frequency", "b": "stays the same. Frequency is set by the source; wavelength changes instead."}, {"id": "3.5-p7", "m": "3.5", "c": 3, "k": "problem", "f": "Sound waves are", "b": "longitudinal. Air molecules oscillate along the direction of travel."}, {"id": "3.6-e1", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Current", "tex": "I = \\frac{Q}{t}"}, {"id": "3.6-e2", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Potential difference", "tex": "V = \\frac{E}{Q}"}, {"id": "3.6-e3", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Ohm's law", "tex": "V = IR"}, {"id": "3.6-e4", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Series resistance", "tex": "R = R_1 + R_2 + \\cdots"}, {"id": "3.6-e5", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Parallel resistance", "tex": "\\frac{1}{R} = \\frac{1}{R_1} + \\frac{1}{R_2} + \\cdots"}, {"id": "3.6-e6", "m": "3.6", "c": 3, "k": "equation", "f": "Write the equation: Electrical power", "tex": "P = VI = I^2R = \\frac{V^2}{R}"}, {"id": "3.6-k1", "m": "3.6", "c": 3, "k": "key idea", "f": "Complete the key idea: Current = charge per …", "b": "Current = charge per second; voltage = energy per coulomb"}, {"id": "3.6-k2", "m": "3.6", "c": 3, "k": "key idea", "f": "Complete the key idea: V = …", "b": "V = IR"}, {"id": "3.6-k3", "m": "3.6", "c": 3, "k": "key idea", "f": "Complete the key idea: Series: R adds, current …", "b": "Series: R adds, current same. Parallel: 1/R adds, voltage same"}, {"id": "3.6-k4", "m": "3.6", "c": 3, "k": "key idea", "f": "Complete the key idea: P = VI …", "b": "P = VI = I²R = V²/R"}, {"id": "3.6-q1", "m": "3.6", "c": 3, "k": "quick check", "f": "One ampere is one", "b": "coulomb per second"}, {"id": "3.6-q2", "m": "3.6", "c": 3, "k": "quick check", "f": "Adding a resistor in parallel makes the total resistance", "b": "smaller"}, {"id": "3.6-q3", "m": "3.6", "c": 3, "k": "quick check", "f": "Components in series share the same", "b": "current"}, {"id": "3.6-q4", "m": "3.6", "c": 3, "k": "quick check", "f": "A kilowatt-hour is a unit of", "b": "energy"}, {"id": "3.6-p1", "m": "3.6", "c": 3, "k": "problem", "f": "A current of 2 A flows for 30 s. How much charge passes?", "b": "60 C. Q = It = 2 × 30."}, {"id": "3.6-p2", "m": "3.6", "c": 3, "k": "problem", "f": "A 12 V supply drives current through a 4 Ω resistor. What is the current?", "b": "3 A. I = V/R = 12 ÷ 4."}, {"id": "3.6-p3", "m": "3.6", "c": 3, "k": "problem", "f": "Resistors of 3 Ω, 5 Ω and 12 Ω are connected in series. What is the total resistance?", "b": "20 Ω. Add them: 3 + 5 + 12."}, {"id": "3.6-p4", "m": "3.6", "c": 3, "k": "problem", "f": "A 6 Ω and a 12 Ω resistor are connected in parallel. What is the combined resistance?", "b": "4 Ω. R = 4 Ω."}, {"id": "3.6-p5", "m": "3.6", "c": 3, "k": "problem", "f": "A 230 V heater draws 8 A. What is its power?", "b": "1840 W. P = VI = 230 × 8."}, {"id": "3.6-p6", "m": "3.6", "c": 3, "k": "problem", "f": "A 60 W lamp runs on 230 V. What is its resistance when lit?", "b": "881.7 Ω. 52 900 ÷ 60 ≈ 882 Ω."}, {"id": "3.6-p7", "m": "3.6", "c": 3, "k": "problem", "f": "A 2.4 kW appliance runs for 2.5 hours. Electricity costs 30 cents per kWh. What does it cost, in dollars?", "b": "1.8 dollars. 6 × $0.30 = $1.80."}, {"id": "3.6-p8", "m": "3.6", "c": 3, "k": "problem", "f": "Power is transmitted at higher voltage mainly to", "b": "reduce current and so I²R heating losses. Loss I²R falls with the square of current."}, {"id": "3.7-e1", "m": "3.7", "c": 3, "k": "equation", "f": "Write the equation: Force on a current", "tex": "F = BIL\\sin\\theta"}, {"id": "3.7-e2", "m": "3.7", "c": 3, "k": "equation", "f": "Write the equation: Force on a moving charge", "tex": "F = qvB\\sin\\theta"}, {"id": "3.7-e3", "m": "3.7", "c": 3, "k": "equation", "f": "Write the equation: Faraday's law", "tex": "\\varepsilon = -N\\frac{\\Delta\\Phi}{\\Delta t}"}, {"id": "3.7-e4", "m": "3.7", "c": 3, "k": "equation", "f": "Write the equation: Ideal transformer", "tex": "\\frac{V_s}{V_p} = \\frac{N_s}{N_p}"}, {"id": "3.7-k1", "m": "3.7", "c": 3, "k": "key idea", "f": "Complete the key idea: Currents create …", "b": "Currents create magnetic fields"}, {"id": "3.7-k2", "m": "3.7", "c": 3, "k": "key idea", "f": "Complete the key idea: Force on a current …", "b": "Force on a current in a field: F = BIL (perpendicular)"}, {"id": "3.7-k3", "m": "3.7", "c": 3, "k": "key idea", "f": "Complete the key idea: Changing magnetic …", "b": "Changing magnetic flux induces a voltage"}, {"id": "3.7-k4", "m": "3.7", "c": 3, "k": "key idea", "f": "Complete the key idea: Transformers: Vs/Vp = Ns/Np; …", "b": "Transformers: Vs/Vp = Ns/Np; light is an electromagnetic wave"}, {"id": "3.7-q1", "m": "3.7", "c": 3, "k": "quick check", "f": "A current-carrying wire produces", "b": "a magnetic field"}, {"id": "3.7-q2", "m": "3.7", "c": 3, "k": "quick check", "f": "A step-down transformer has", "b": "fewer secondary turns"}, {"id": "3.7-q3", "m": "3.7", "c": 3, "k": "quick check", "f": "Induced voltage depends on", "b": "the rate of change of flux"}, {"id": "3.7-q4", "m": "3.7", "c": 3, "k": "quick check", "f": "Maxwell showed light is", "b": "an electromagnetic wave"}, {"id": "3.7-p1", "m": "3.7", "c": 3, "k": "problem", "f": "A 0.5 m wire carrying 4 A lies at right angles to a 0.2 T field. What force acts on it?", "b": "0.4 N. F = BIL = 0.2 × 4 × 0.5."}, {"id": "3.7-p2", "m": "3.7", "c": 3, "k": "problem", "f": "A transformer has 500 primary turns and 25 secondary turns. With 240 V in, what is the output voltage?", "b": "12 V. Vs = Vp × Ns/Np = 240 × 25/500."}, {"id": "3.7-p3", "m": "3.7", "c": 3, "k": "problem", "f": "An electron (q = 1.6 × 10⁻¹⁹ C) moves at 2 × 10⁶ m/s perpendicular to a 0.01 T field. What force acts on it?", "b": "3.200e-15 N. 1.6 × 10⁻¹⁹ × 2 × 10⁶ × 0.01 = 3.2 × 10⁻¹⁵ N."}, {"id": "3.7-p4", "m": "3.7", "c": 3, "k": "problem", "f": "A magnet is held still inside a coil. The induced current is", "b": "zero. Induction needs a changing flux."}, {"id": "3.7-p5", "m": "3.7", "c": 3, "k": "problem", "f": "Who first showed that an electric current produces a magnetic field?", "b": "Ørsted. Ørsted, 1820."}, {"id": "3.7-p6", "m": "3.7", "c": 3, "k": "problem", "f": "A coil of 200 turns sees its flux change by 0.03 Wb in 0.1 s. What size of voltage is induced?", "b": "60 V. ε = NΔΦ/Δt = 200 × 0.03 ÷ 0.1 = 60 V."}, {"id": "3.7-p7", "m": "3.7", "c": 3, "k": "problem", "f": "Transformers do not work with steady direct current because", "b": "there is no changing magnetic field. Induction requires change."}, {"id": "3.7-p8", "m": "3.7", "c": 3, "k": "problem", "f": "Explain in a few sentences how a bicycle dynamo lights a lamp.", "b": "The wheel spins a magnet near a coil (or a coil near a magnet). The magnetic flux through the coil keeps changing, which by Faraday's law induces a voltage. That voltage drives a current through the lamp. The faster you ride, the faster the flux changes, so the lamp glows brighter."}, {"id": "3.8-e1", "m": "3.8", "c": 3, "k": "equation", "f": "Write the equation: Kelvin and Celsius", "tex": "T(\\mathrm{K}) = T(^\\circ\\mathrm{C}) + 273"}, {"id": "3.8-e2", "m": "3.8", "c": 3, "k": "equation", "f": "Write the equation: Specific heat", "tex": "Q = mc\\,\\Delta T"}, {"id": "3.8-e3", "m": "3.8", "c": 3, "k": "equation", "f": "Write the equation: Latent heat", "tex": "Q = mL"}, {"id": "3.8-e4", "m": "3.8", "c": 3, "k": "equation", "f": "Write the equation: First law", "tex": "\\Delta U = Q - W"}, {"id": "3.8-e5", "m": "3.8", "c": 3, "k": "equation", "f": "Write the equation: Maximum (Carnot) efficiency", "tex": "\\eta_{\\max} = 1 - \\frac{T_c}{T_h}"}, {"id": "3.8-k1", "m": "3.8", "c": 3, "k": "key idea", "f": "Complete the key idea: Temperature in kelvin …", "b": "Temperature in kelvin = °C + 273"}, {"id": "3.8-k2", "m": "3.8", "c": 3, "k": "key idea", "f": "Complete the key idea: Q = mcΔT for heating; …", "b": "Q = mcΔT for heating; Q = mL for change of state"}, {"id": "3.8-k3", "m": "3.8", "c": 3, "k": "key idea", "f": "Complete the key idea: First law: ΔU …", "b": "First law: ΔU = Q − W"}, {"id": "3.8-k4", "m": "3.8", "c": 3, "k": "key idea", "f": "Complete the key idea: Second law: heat flows hot to …", "b": "Second law: heat flows hot to cold; entropy never decreases; η ≤ 1 − Tc/Th"}, {"id": "3.8-q1", "m": "3.8", "c": 3, "k": "quick check", "f": "Absolute zero is", "b": "0 K"}, {"id": "3.8-q2", "m": "3.8", "c": 3, "k": "quick check", "f": "Heat flows spontaneously from", "b": "hot to cold"}, {"id": "3.8-q3", "m": "3.8", "c": 3, "k": "quick check", "f": "During boiling, temperature", "b": "stays constant"}, {"id": "3.8-q4", "m": "3.8", "c": 3, "k": "quick check", "f": "The first law of thermodynamics is about", "b": "conservation of energy"}, {"id": "3.8-p1", "m": "3.8", "c": 3, "k": "problem", "f": "Convert 25 °C to kelvin.", "b": "298 K. 25 + 273."}, {"id": "3.8-p2", "m": "3.8", "c": 3, "k": "problem", "f": "How much energy raises 2.0 kg of water by 10 K? (c = 4200 J/kg K)", "b": "8.4e+04 J. Q = mcΔT = 2 × 4200 × 10."}, {"id": "3.8-p3", "m": "3.8", "c": 3, "k": "problem", "f": "How much energy melts 0.5 kg of ice at 0 °C? (L = 3.34 × 10⁵ J/kg)", "b": "1.670e+05 J. Q = mL = 0.5 × 3.34 × 10⁵ = 1.67 × 10⁵ J."}, {"id": "3.8-p4", "m": "3.8", "c": 3, "k": "problem", "f": "A 2 kW kettle heats 1.5 kg of water from 20 °C to 100 °C. Ignoring losses, how long does it take?", "b": "252 s. t = Q/P = 252 s."}, {"id": "3.8-p5", "m": "3.8", "c": 3, "k": "problem", "f": "A gas gains 500 J of heat and does 200 J of work on its surroundings. What is the change in its internal energy?", "b": "300 J. ΔU = Q − W = 500 − 200."}, {"id": "3.8-p6", "m": "3.8", "c": 3, "k": "problem", "f": "What is the maximum efficiency of an engine running between 600 K and 300 K?", "b": "50 %. 1 − 300/600 = 0.5."}, {"id": "3.8-p7", "m": "3.8", "c": 3, "k": "problem", "f": "A refrigerator moves heat from cold to hot. Does this break the second law?", "b": "No, because work is supplied and more entropy is produced outside. The second law forbids this happening spontaneously, not with work input."}, {"id": "3.8-p8", "m": "3.8", "c": 3, "k": "problem", "f": "Explain why steam at 100 °C causes worse burns than water at 100 °C.", "b": "When steam condenses on skin it releases its latent heat of vaporisation, about 2.26 million joules per kilogram, before it even starts cooling as water. Water at 100 °C only releases heat as it cools. So the same mass of steam delivers far more energy to the skin."}, {"id": "3.9-e1", "m": "3.9", "c": 3, "k": "equation", "f": "Write the equation: Lorentz factor and time dilation", "tex": "\\gamma = \\frac{1}{\\sqrt{1 - v^2/c^2}},\\qquad t = \\gamma t_0"}, {"id": "3.9-e2", "m": "3.9", "c": 3, "k": "equation", "f": "Write the equation: Mass–energy equivalence", "tex": "E = mc^2"}, {"id": "3.9-e3", "m": "3.9", "c": 3, "k": "equation", "f": "Write the equation: Photon energy", "tex": "E = hf = \\frac{hc}{\\lambda}"}, {"id": "3.9-e4", "m": "3.9", "c": 3, "k": "equation", "f": "Write the equation: Spectral line", "tex": "\\Delta E = E_{\\mathrm{upper}} - E_{\\mathrm{lower}} = hf"}, {"id": "3.9-e5", "m": "3.9", "c": 3, "k": "equation", "f": "Write the equation: Radioactive decay", "tex": "N = N_0\\left(\\frac{1}{2}\\right)^{t/t_{1/2}}"}, {"id": "3.9-k1", "m": "3.9", "c": 3, "k": "key idea", "f": "Complete the key idea: Light speed is the same …", "b": "Light speed is the same for all observers; moving clocks run slow"}, {"id": "3.9-k2", "m": "3.9", "c": 3, "k": "key idea", "f": "Complete the key idea: E = mc²: …", "b": "E = mc²: mass is concentrated energy"}, {"id": "3.9-k3", "m": "3.9", "c": 3, "k": "key idea", "f": "Complete the key idea: Photons: E = …", "b": "Photons: E = hf; atoms emit specific frequencies"}, {"id": "3.9-k4", "m": "3.9", "c": 3, "k": "key idea", "f": "Complete the key idea: Half-life is constant; fission …", "b": "Half-life is constant; fission and fusion release mass as energy"}, {"id": "3.9-q1", "m": "3.9", "c": 3, "k": "quick check", "f": "E = mc² says", "b": "mass and energy are equivalent"}, {"id": "3.9-q2", "m": "3.9", "c": 3, "k": "quick check", "f": "Photon energy is proportional to", "b": "frequency"}, {"id": "3.9-q3", "m": "3.9", "c": 3, "k": "quick check", "f": "After 3 half-lives, the fraction remaining is", "b": "1/8"}, {"id": "3.9-q4", "m": "3.9", "c": 3, "k": "quick check", "f": "Moving clocks", "b": "run slow"}, {"id": "3.9-p1", "m": "3.9", "c": 3, "k": "problem", "f": "How much energy is equivalent to 1 g of mass? (c = 3 × 10⁸ m/s)", "b": "9.000e+13 J. = 9 × 10¹³ J."}, {"id": "3.9-p2", "m": "3.9", "c": 3, "k": "problem", "f": "What is the energy of a photon of green light, frequency 5.6 × 10¹⁴ Hz? (h = 6.63 × 10⁻³⁴ J s)", "b": "3.713e-19 J. E = hf = 6.63 × 10⁻³⁴ × 5.6 × 10¹⁴ ≈ 3.7 × 10⁻¹⁹ J."}, {"id": "3.9-p3", "m": "3.9", "c": 3, "k": "problem", "f": "A radioactive isotope has a half-life of 8 days. What fraction remains after 24 days? Give a decimal.", "b": "0.125. (½)³ = 0.125."}, {"id": "3.9-p4", "m": "3.9", "c": 3, "k": "problem", "f": "A sample of wood has 25% of its original carbon-14. How old is it? (half-life 5730 years)", "b": "1.146e+04 years. 2 × 5730 = 11 460 years."}, {"id": "3.9-p6", "m": "3.9", "c": 3, "k": "problem", "f": "In the photoelectric effect, increasing the brightness of light below the threshold frequency", "b": "ejects no electrons. Each photon must individually have enough energy; more low-energy photons don't help."}, {"id": "3.9-p7", "m": "3.9", "c": 3, "k": "problem", "f": "The Sun produces energy mainly by", "b": "fusion of hydrogen into helium. Hydrogen fusion in the core."}, {"id": "3.9-p8", "m": "3.9", "c": 3, "k": "problem", "f": "Why does each element produce its own pattern of spectral lines?", "b": "Electrons in an atom can only occupy certain energy levels, and the spacing of those levels depends on the element's nuclear charge and electron arrangement. When an electron drops between levels it emits a photon with energy exactly equal to the gap, E = hf, so only certain frequencies appear. Different elements have different level spacings and so different line patterns."}, {"id": "4.1-e1", "m": "4.1", "c": 4, "k": "equation", "f": "Write the equation: Mass number", "tex": "A = Z + N"}, {"id": "4.1-e2", "m": "4.1", "c": 4, "k": "equation", "f": "Write the equation: Relative atomic mass", "tex": "A_r = \\sum (\\mathrm{isotope\\ mass} \\times \\mathrm{fractional\\ abundance})"}, {"id": "4.1-e3", "m": "4.1", "c": 4, "k": "equation", "f": "Write the equation: Sodium's configuration", "tex": "\\mathrm{Na}:\\ 1s^2\\,2s^2\\,2p^6\\,3s^1\\ \\ (2,8,1)"}, {"id": "4.1-k1", "m": "4.1", "c": 4, "k": "key idea", "f": "Complete the key idea: Z = protons (defines …", "b": "Z = protons (defines the element); A = protons + neutrons"}, {"id": "4.1-k2", "m": "4.1", "c": 4, "k": "key idea", "f": "Complete the key idea: Isotopes differ …", "b": "Isotopes differ in neutron number only"}, {"id": "4.1-k3", "m": "4.1", "c": 4, "k": "key idea", "f": "Complete the key idea: Valence electrons …", "b": "Valence electrons decide chemistry"}, {"id": "4.1-k4", "m": "4.1", "c": 4, "k": "key idea", "f": "Complete the key idea: Shells fill 2, 8, …", "b": "Shells fill 2, 8, 8 for the first 20 elements"}, {"id": "4.1-q1", "m": "4.1", "c": 4, "k": "quick check", "f": "The nucleus contains", "b": "protons and neutrons"}, {"id": "4.1-q2", "m": "4.1", "c": 4, "k": "quick check", "f": "An atom with 8 protons and 10 electrons is", "b": "a 2− ion"}, {"id": "4.1-q3", "m": "4.1", "c": 4, "k": "quick check", "f": "Mass number is", "b": "protons + neutrons"}, {"id": "4.1-q4", "m": "4.1", "c": 4, "k": "quick check", "f": "Maximum electrons in the first shell:", "b": "2"}, {"id": "4.1-p1", "m": "4.1", "c": 4, "k": "problem", "f": "How many neutrons are in an atom of iron-56 (Z = 26)?", "b": "30. N = A − Z = 56 − 26."}, {"id": "4.1-p2", "m": "4.1", "c": 4, "k": "problem", "f": "What defines which element an atom is?", "b": "number of protons. The atomic number, Z, the proton count."}, {"id": "4.1-p3", "m": "4.1", "c": 4, "k": "problem", "f": "How many electrons does a Mg²⁺ ion have? (Mg: Z = 12)", "b": "10. 2+ means two lost: 10."}, {"id": "4.1-p4", "m": "4.1", "c": 4, "k": "problem", "f": "Give the shell arrangement of chlorine (Z = 17).", "b": "2, 8, 7. Fill 2, then 8, then the remaining 7."}, {"id": "4.1-p5", "m": "4.1", "c": 4, "k": "problem", "f": "Boron is 20% boron-10 and 80% boron-11. What is its relative atomic mass?", "b": "10.8. = 10.8."}, {"id": "4.1-p6", "m": "4.1", "c": 4, "k": "problem", "f": "Carbon-12 and carbon-14 differ in", "b": "neutrons. Isotopes differ only in neutron number."}, {"id": "4.1-p7", "m": "4.1", "c": 4, "k": "problem", "f": "How many valence electrons does sulfur (Z = 16) have?", "b": "6. Outer shell: 6."}, {"id": "4.1-p8", "m": "4.1", "c": 4, "k": "problem", "f": "Explain why isotopes of the same element have almost identical chemistry.", "b": "Chemistry is decided by electrons, especially the valence electrons. Isotopes have the same number of protons and therefore the same number and arrangement of electrons. Only the neutron count differs, which changes the mass slightly but not how the atom bonds."}, {"id": "4.2-e1", "m": "4.2", "c": 4, "k": "equation", "f": "Write the equation: Ionisation (first)", "tex": "\\mathrm{X(g)} \\rightarrow \\mathrm{X^+(g)} + e^-"}, {"id": "4.2-e2", "m": "4.2", "c": 4, "k": "equation", "f": "Write the equation: Alkali metal with water", "tex": "2\\mathrm{Na} + 2\\mathrm{H_2O} \\rightarrow 2\\mathrm{NaOH} + \\mathrm{H_2}"}, {"id": "4.2-k1", "m": "4.2", "c": 4, "k": "key idea", "f": "Complete the key idea: Group = valence …", "b": "Group = valence electrons = similar chemistry"}, {"id": "4.2-k2", "m": "4.2", "c": 4, "k": "key idea", "f": "Complete the key idea: Period = …", "b": "Period = number of shells"}, {"id": "4.2-k3", "m": "4.2", "c": 4, "k": "key idea", "f": "Complete the key idea: Across a period: smaller …", "b": "Across a period: smaller atoms, higher ionisation energy and electronegativity"}, {"id": "4.2-k4", "m": "4.2", "c": 4, "k": "key idea", "f": "Complete the key idea: Down a group: larger …", "b": "Down a group: larger atoms, outer electrons easier to remove"}, {"id": "4.2-q1", "m": "4.2", "c": 4, "k": "quick check", "f": "Periods are", "b": "rows"}, {"id": "4.2-q2", "m": "4.2", "c": 4, "k": "quick check", "f": "Electronegativity increases", "b": "across a period"}, {"id": "4.2-q3", "m": "4.2", "c": 4, "k": "quick check", "f": "Mendeleev's table was confirmed when", "b": "predicted elements were found"}, {"id": "4.2-q4", "m": "4.2", "c": 4, "k": "quick check", "f": "Transition metals often", "b": "form coloured compounds"}, {"id": "4.2-p1", "m": "4.2", "c": 4, "k": "problem", "f": "Elements in the same group have the same number of", "b": "valence electrons. That is why they react similarly."}, {"id": "4.2-p2", "m": "4.2", "c": 4, "k": "problem", "f": "Which group contains the noble gases?", "b": "18. Group 18, full outer shells."}, {"id": "4.2-p3", "m": "4.2", "c": 4, "k": "problem", "f": "Which atom is larger?", "b": "sodium. Same period; Cl has more protons pulling the same shell in."}, {"id": "4.2-p4", "m": "4.2", "c": 4, "k": "problem", "f": "Which is the most reactive alkali metal of these?", "b": "potassium. Reactivity increases down group 1."}, {"id": "4.2-p5", "m": "4.2", "c": 4, "k": "problem", "f": "Which is the most reactive halogen of these?", "b": "fluorine. Reactivity decreases down group 17."}, {"id": "4.2-p6", "m": "4.2", "c": 4, "k": "problem", "f": "Calcium is in group 2. What charge does its ion usually carry? (enter as a number, e.g. 2 for 2+)", "b": "2. Two valence electrons, lost to give Ca²⁺."}, {"id": "4.2-p7", "m": "4.2", "c": 4, "k": "problem", "f": "Why does ionisation energy rise across period 3?", "b": "more protons pulling the same shell. Nuclear charge increases while shielding stays similar."}, {"id": "4.2-p8", "m": "4.2", "c": 4, "k": "problem", "f": "Using electron arrangements, explain why sodium and chlorine react so readily with each other.", "b": "Sodium (2,8,1) has one valence electron that is easy to remove, leaving a full shell. Chlorine (2,8,7) needs one electron to fill its outer shell. Transferring an electron gives Na⁺ and Cl⁻, both with full shells, and the oppositely charged ions attract strongly, releasing energy."}, {"id": "4.3-e1", "m": "4.3", "c": 4, "k": "equation", "f": "Write the equation: Ionic formation", "tex": "\\mathrm{Na} + \\mathrm{Cl} \\rightarrow \\mathrm{Na^+} + \\mathrm{Cl^-}"}, {"id": "4.3-e2", "m": "4.3", "c": 4, "k": "equation", "f": "Write the equation: Covalent sharing in water", "tex": "\\mathrm{H{-}O{-}H}"}, {"id": "4.3-k1", "m": "4.3", "c": 4, "k": "key idea", "f": "Complete the key idea: Ionic: transfer, lattices. …", "b": "Ionic: transfer, lattices. Covalent: sharing. Metallic: electron sea"}, {"id": "4.3-k2", "m": "4.3", "c": 4, "k": "key idea", "f": "Complete the key idea: VSEPR: electron pairs spread …", "b": "VSEPR: electron pairs spread out; lone pairs squeeze angles"}, {"id": "4.3-k3", "m": "4.3", "c": 4, "k": "key idea", "f": "Complete the key idea: Shape decides …", "b": "Shape decides whether polar bonds cancel"}, {"id": "4.3-k4", "m": "4.3", "c": 4, "k": "key idea", "f": "Complete the key idea: Hydrogen bonds …", "b": "Hydrogen bonds explain water's unusual properties"}, {"id": "4.3-q1", "m": "4.3", "c": 4, "k": "quick check", "f": "A covalent bond is", "b": "a shared pair of electrons"}, {"id": "4.3-q2", "m": "4.3", "c": 4, "k": "quick check", "f": "Water's shape is", "b": "bent"}, {"id": "4.3-q3", "m": "4.3", "c": 4, "k": "quick check", "f": "The strongest intermolecular force listed is", "b": "hydrogen bonding"}, {"id": "4.3-q4", "m": "4.3", "c": 4, "k": "quick check", "f": "Lone pairs make bond angles", "b": "smaller"}, {"id": "4.3-p1", "m": "4.3", "c": 4, "k": "problem", "f": "What type of bonding is in magnesium oxide, MgO?", "b": "ionic. Metal plus non-metal: electron transfer."}, {"id": "4.3-p2", "m": "4.3", "c": 4, "k": "problem", "f": "Why do metals conduct electricity?", "b": "they have a sea of free electrons. Delocalised electrons can move."}, {"id": "4.3-p3", "m": "4.3", "c": 4, "k": "problem", "f": "What is the shape of methane, CH₄?", "b": "tetrahedral. Four bonding pairs, no lone pairs."}, {"id": "4.3-p4", "m": "4.3", "c": 4, "k": "problem", "f": "CO₂ has polar bonds. Why is the molecule non-polar?", "b": "it is linear, so the dipoles cancel. Equal and opposite bond dipoles cancel."}, {"id": "4.3-p5", "m": "4.3", "c": 4, "k": "problem", "f": "How many electrons are shared in a double bond?", "b": "4. Each bond is a pair; two bonds = 4 electrons."}, {"id": "4.3-p6", "m": "4.3", "c": 4, "k": "problem", "f": "Which molecule can form hydrogen bonds with itself?", "b": "NH₃. H attached to N, with a lone pair on N."}, {"id": "4.3-p7", "m": "4.3", "c": 4, "k": "problem", "f": "Sodium chloride conducts electricity", "b": "when molten or dissolved. Ions must be free to move."}, {"id": "4.3-p8", "m": "4.3", "c": 4, "k": "problem", "f": "Explain why ice floats on water.", "b": "In ice, hydrogen bonds lock water molecules into an open hexagonal lattice with lots of space. In liquid water the hydrogen bonds keep breaking and reforming, so molecules pack closer together. Ice is therefore less dense than liquid water and floats."}, {"id": "4.4-e1", "m": "4.4", "c": 4, "k": "equation", "f": "Write the equation: Moles from mass", "tex": "n = \\frac{m}{M}"}, {"id": "4.4-e2", "m": "4.4", "c": 4, "k": "equation", "f": "Write the equation: Number of particles", "tex": "N = nN_A,\\quad N_A = 6.02 \\times 10^{23}\\ \\mathrm{mol^{-1}}"}, {"id": "4.4-e3", "m": "4.4", "c": 4, "k": "equation", "f": "Write the equation: Combustion of methane", "tex": "\\mathrm{CH_4} + 2\\mathrm{O_2} \\rightarrow \\mathrm{CO_2} + 2\\mathrm{H_2O}"}, {"id": "4.4-e4", "m": "4.4", "c": 4, "k": "equation", "f": "Write the equation: Percentage yield", "tex": "\\%\\ \\mathrm{yield} = \\frac{\\mathrm{actual}}{\\mathrm{theoretical}} \\times 100"}, {"id": "4.4-e5", "m": "4.4", "c": 4, "k": "equation", "f": "Write the equation: Concentration and dilution", "tex": "c = \\frac{n}{V},\\qquad c_1V_1 = c_2V_2"}, {"id": "4.4-k1", "m": "4.4", "c": 4, "k": "key idea", "f": "Complete the key idea: n = m/M; …", "b": "n = m/M; particles = n × Nₐ"}, {"id": "4.4-k2", "m": "4.4", "c": 4, "k": "key idea", "f": "Complete the key idea: Balance with …", "b": "Balance with coefficients, never subscripts"}, {"id": "4.4-k3", "m": "4.4", "c": 4, "k": "key idea", "f": "Complete the key idea: Coefficients are …", "b": "Coefficients are mole ratios"}, {"id": "4.4-k4", "m": "4.4", "c": 4, "k": "key idea", "f": "Complete the key idea: c = n/V; …", "b": "c = n/V; dilution keeps c₁V₁ = c₂V₂"}, {"id": "4.4-q1", "m": "4.4", "c": 4, "k": "quick check", "f": "One mole contains", "b": "6.02 × 10²³ particles"}, {"id": "4.4-q2", "m": "4.4", "c": 4, "k": "quick check", "f": "To balance an equation you change", "b": "coefficients"}, {"id": "4.4-q3", "m": "4.4", "c": 4, "k": "quick check", "f": "The limiting reagent", "b": "runs out first"}, {"id": "4.4-q4", "m": "4.4", "c": 4, "k": "quick check", "f": "Molarity is", "b": "moles per litre"}, {"id": "4.4-p1", "m": "4.4", "c": 4, "k": "problem", "f": "How many moles are in 44 g of carbon dioxide (M = 44 g/mol)?", "b": "1 mol. n = m/M = 44/44."}, {"id": "4.4-p2", "m": "4.4", "c": 4, "k": "problem", "f": "What is the molar mass of sulfuric acid, H₂SO₄? (H = 1, S = 32, O = 16)", "b": "98 g/mol. 2(1) + 32 + 4(16) = 98."}, {"id": "4.4-p3", "m": "4.4", "c": 4, "k": "problem", "f": "How many molecules are in 9.0 g of water (M = 18 g/mol)?", "b": "3.010e+23. N = 0.5 × 6.02 × 10²³ = 3.0 × 10²³."}, {"id": "4.4-p4", "m": "4.4", "c": 4, "k": "problem", "f": "Balance: __ H₂ + O₂ → __ H₂O. What coefficient goes in front of H₂?", "b": "2. 2H₂ + O₂ → 2H₂O balances 4 H and 2 O."}, {"id": "4.4-p5", "m": "4.4", "c": 4, "k": "problem", "f": "How many grams of oxygen are needed to burn 8.0 g of methane completely? (CH₄ = 16, O₂ = 32)", "b": "32 g. Needs 2 × 0.5 = 1.0 mol O₂ = 32 g."}, {"id": "4.4-p6", "m": "4.4", "c": 4, "k": "problem", "f": "What is the concentration of 0.25 mol of NaCl dissolved to make 500 mL of solution?", "b": "0.5 mol/L. c = n/V = 0.25/0.500."}, {"id": "4.4-p7", "m": "4.4", "c": 4, "k": "problem", "f": "You need 100 mL of 0.20 M solution from a 1.0 M stock. What volume of stock do you use?", "b": "20 mL. c₁V₁ = c₂V₂: 1.0 × V₁ = 0.20 × 100."}, {"id": "4.5-e1", "m": "4.5", "c": 4, "k": "equation", "f": "Write the equation: Boyle's law", "tex": "P_1V_1 = P_2V_2"}, {"id": "4.5-e2", "m": "4.5", "c": 4, "k": "equation", "f": "Write the equation: Charles' law", "tex": "\\frac{V_1}{T_1} = \\frac{V_2}{T_2}"}, {"id": "4.5-e3", "m": "4.5", "c": 4, "k": "equation", "f": "Write the equation: Ideal gas law", "tex": "PV = nRT,\\quad R = 8.314\\ \\mathrm{J\\,mol^{-1}K^{-1}}"}, {"id": "4.5-e4", "m": "4.5", "c": 4, "k": "equation", "f": "Write the equation: Mean kinetic energy", "tex": "\\overline{E_k} = \\frac{3}{2}k_BT"}, {"id": "4.5-k1", "m": "4.5", "c": 4, "k": "key idea", "f": "Complete the key idea: Particle spacing and …", "b": "Particle spacing and motion distinguish solid, liquid, gas"}, {"id": "4.5-k2", "m": "4.5", "c": 4, "k": "key idea", "f": "Complete the key idea: Boyle: PV constant. …", "b": "Boyle: PV constant. Charles: V/T constant (kelvin!)"}, {"id": "4.5-k3", "m": "4.5", "c": 4, "k": "key idea", "f": "Complete the key idea: Ideal gas …", "b": "Ideal gas law: PV = nRT"}, {"id": "4.5-k4", "m": "4.5", "c": 4, "k": "key idea", "f": "Complete the key idea: Temperature measures …", "b": "Temperature measures average particle kinetic energy"}, {"id": "4.5-q1", "m": "4.5", "c": 4, "k": "quick check", "f": "At constant temperature, halving the volume of a gas", "b": "doubles pressure"}, {"id": "4.5-q2", "m": "4.5", "c": 4, "k": "quick check", "f": "Gas laws require temperature in", "b": "K"}, {"id": "4.5-q3", "m": "4.5", "c": 4, "k": "quick check", "f": "In PV = nRT, n is", "b": "moles"}, {"id": "4.5-q4", "m": "4.5", "c": 4, "k": "quick check", "f": "Particles in a liquid", "b": "slide past each other"}, {"id": "4.5-p1", "m": "4.5", "c": 4, "k": "problem", "f": "A gas at 100 kPa occupies 6.0 L. It is compressed to 2.0 L at constant temperature. What is the new pressure?", "b": "300 kPa. 100 × 6 = P₂ × 2."}, {"id": "4.5-p2", "m": "4.5", "c": 4, "k": "problem", "f": "A balloon of 2.0 L at 300 K is heated to 450 K at constant pressure. What is its new volume?", "b": "3 L. V₂ = V₁ T₂/T₁ = 2 × 450/300."}, {"id": "4.5-p3", "m": "4.5", "c": 4, "k": "problem", "f": "What volume does 2.0 mol of gas occupy at 300 K and 100 000 Pa? Give your answer in litres.", "b": "49.88 L. = 0.0499 m³ ≈ 49.9 L."}, {"id": "4.5-p4", "m": "4.5", "c": 4, "k": "problem", "f": "How many moles are in a 10 L cylinder at 500 kPa and 290 K?", "b": "2.074 mol. ≈ 2.07 mol."}, {"id": "4.5-p5", "m": "4.5", "c": 4, "k": "problem", "f": "Why must temperatures be in kelvin for gas laws?", "b": "the laws are proportional relationships measured from absolute zero. Doubling kelvin doubles volume; doubling °C does not."}, {"id": "4.5-p6", "m": "4.5", "c": 4, "k": "problem", "f": "According to kinetic theory, heating a gas in a rigid container raises its pressure because", "b": "particles move faster and hit the walls harder and more often. Faster particles, more forceful and frequent collisions."}, {"id": "4.5-p7", "m": "4.5", "c": 4, "k": "problem", "f": "A tyre at 15 °C has a pressure of 240 kPa. After driving it is at 45 °C. Assuming fixed volume, what is the pressure?", "b": "265 kPa. 240 × 318/288 ≈ 265 kPa."}, {"id": "4.5-p8", "m": "4.5", "c": 4, "k": "problem", "f": "Why do real gases deviate from the ideal gas law at high pressure and low temperature?", "b": "The ideal law assumes particles have no volume and no attractions. At high pressure, particles are packed close enough that their own volume is a significant fraction of the space. At low temperature, they move slowly enough that attractions between them matter. Both effects make real gases depart from PV = nRT, and eventually they condense."}, {"id": "4.6-e1", "m": "4.6", "c": 4, "k": "equation", "f": "Write the equation: Enthalpy change", "tex": "\\Delta H = \\sum E_{\\mathrm{bonds\\ broken}} - \\sum E_{\\mathrm{bonds\\ made}}"}, {"id": "4.6-e2", "m": "4.6", "c": 4, "k": "equation", "f": "Write the equation: Equilibrium constant for aA + bB ⇌ cC + dD", "tex": "K = \\frac{[C]^c[D]^d}{[A]^a[B]^b}"}, {"id": "4.6-e3", "m": "4.6", "c": 4, "k": "equation", "f": "Write the equation: Haber process", "tex": "\\mathrm{N_2} + 3\\mathrm{H_2} \\rightleftharpoons 2\\mathrm{NH_3},\\quad \\Delta H < 0"}, {"id": "4.6-k1", "m": "4.6", "c": 4, "k": "key idea", "f": "Complete the key idea: Exothermic: ΔH negative, …", "b": "Exothermic: ΔH negative, heat released. Endothermic: ΔH positive"}, {"id": "4.6-k2", "m": "4.6", "c": 4, "k": "key idea", "f": "Complete the key idea: Rate rises with concentration, …", "b": "Rate rises with concentration, temperature, surface area and catalysts"}, {"id": "4.6-k3", "m": "4.6", "c": 4, "k": "key idea", "f": "Complete the key idea: Equilibrium is dynamic: …", "b": "Equilibrium is dynamic: equal forward and reverse rates"}, {"id": "4.6-k4", "m": "4.6", "c": 4, "k": "key idea", "f": "Complete the key idea: Le Chatelier: the system …", "b": "Le Chatelier: the system shifts to oppose a change"}, {"id": "4.6-q1", "m": "4.6", "c": 4, "k": "quick check", "f": "At equilibrium, forward and reverse rates are", "b": "equal"}, {"id": "4.6-q2", "m": "4.6", "c": 4, "k": "quick check", "f": "Raising temperature generally makes reactions", "b": "faster"}, {"id": "4.6-q3", "m": "4.6", "c": 4, "k": "quick check", "f": "A large K means", "b": "mostly products"}, {"id": "4.6-q4", "m": "4.6", "c": 4, "k": "quick check", "f": "Endothermic reactions have ΔH", "b": "positive"}, {"id": "4.6-p1", "m": "4.6", "c": 4, "k": "problem", "f": "An exothermic reaction", "b": "releases heat. Exo = out."}, {"id": "4.6-p2", "m": "4.6", "c": 4, "k": "problem", "f": "A catalyst works by", "b": "lowering the activation energy. It provides an easier pathway."}, {"id": "4.6-p3", "m": "4.6", "c": 4, "k": "problem", "f": "Breaking bonds in a reaction needs 1370 kJ; making the new bonds releases 1652 kJ. What is ΔH?", "b": "-282 kJ. ΔH = broken − made = 1370 − 1652."}, {"id": "4.6-p4", "m": "4.6", "c": 4, "k": "problem", "f": "Powdered marble reacts faster with acid than marble chips because", "b": "it has a larger surface area. More exposed particles, more collisions."}, {"id": "4.6-p5", "m": "4.6", "c": 4, "k": "problem", "f": "For N₂ + 3H₂ ⇌ 2NH₃ (exothermic), raising the temperature shifts the equilibrium", "b": "left, less ammonia. Shifts in the endothermic direction, which is the reverse."}, {"id": "4.6-p6", "m": "4.6", "c": 4, "k": "problem", "f": "For the same reaction, increasing pressure shifts it", "b": "right. 4 gas molecules on the left, 2 on the right."}, {"id": "4.6-p7", "m": "4.6", "c": 4, "k": "problem", "f": "For A ⇌ B, at equilibrium [A] = 0.20 M and [B] = 0.80 M. What is K?", "b": "4. K = [B]/[A] = 0.80/0.20."}, {"id": "4.6-p8", "m": "4.6", "c": 4, "k": "problem", "f": "Explain what 'dynamic' means in dynamic equilibrium.", "b": "At equilibrium the forward and reverse reactions are both still happening, at equal rates. Molecules are constantly converting in both directions, so on a molecular level the system is busy, but the overall concentrations stay constant."}, {"id": "4.7-e1", "m": "4.7", "c": 4, "k": "equation", "f": "Write the equation: pH", "tex": "\\mathrm{pH} = -\\log_{10}[\\mathrm{H^+}]"}, {"id": "4.7-e2", "m": "4.7", "c": 4, "k": "equation", "f": "Write the equation: Neutralisation", "tex": "\\mathrm{HCl} + \\mathrm{NaOH} \\rightarrow \\mathrm{NaCl} + \\mathrm{H_2O}"}, {"id": "4.7-e3", "m": "4.7", "c": 4, "k": "equation", "f": "Write the equation: A redox pair", "tex": "\\mathrm{Zn} + \\mathrm{Cu^{2+}} \\rightarrow \\mathrm{Zn^{2+}} + \\mathrm{Cu}"}, {"id": "4.7-e4", "m": "4.7", "c": 4, "k": "equation", "f": "Write the equation: Water's ion product", "tex": "[\\mathrm{H^+}][\\mathrm{OH^-}] = 10^{-14}\\ \\mathrm{at\\ 25\\,^\\circ C}"}, {"id": "4.7-k1", "m": "4.7", "c": 4, "k": "key idea", "f": "Complete the key idea: Acids donate …", "b": "Acids donate protons; bases accept them"}, {"id": "4.7-k2", "m": "4.7", "c": 4, "k": "key idea", "f": "Complete the key idea: pH = −log[H⁺]; …", "b": "pH = −log[H⁺]; each unit is ×10"}, {"id": "4.7-k3", "m": "4.7", "c": 4, "k": "key idea", "f": "Complete the key idea: Acid + base …", "b": "Acid + base → salt + water"}, {"id": "4.7-k4", "m": "4.7", "c": 4, "k": "key idea", "f": "Complete the key idea: OIL RIG: oxidation is …", "b": "OIL RIG: oxidation is loss, reduction is gain of electrons"}, {"id": "4.7-q1", "m": "4.7", "c": 4, "k": "quick check", "f": "An acid is a proton", "b": "donor"}, {"id": "4.7-q2", "m": "4.7", "c": 4, "k": "quick check", "f": "pH 2 compared with pH 4 is", "b": "100 times as acidic"}, {"id": "4.7-q3", "m": "4.7", "c": 4, "k": "quick check", "f": "Reduction is", "b": "gain of electrons"}, {"id": "4.7-q4", "m": "4.7", "c": 4, "k": "quick check", "f": "Neutral pH at 25 °C is", "b": "7"}, {"id": "4.7-p1", "m": "4.7", "c": 4, "k": "problem", "f": "What is the pH of a solution with [H⁺] = 10⁻⁴ M?", "b": "4. pH = −log(10⁻⁴) = 4."}, {"id": "4.7-p2", "m": "4.7", "c": 4, "k": "problem", "f": "What is [H⁺] in mol/L for a solution of pH 3? Give a decimal.", "b": "0.001 mol/L. [H⁺] = 10⁻³."}, {"id": "4.7-p3", "m": "4.7", "c": 4, "k": "problem", "f": "In Zn + Cu²⁺ → Zn²⁺ + Cu, which species is oxidised?", "b": "Zn. Zn loses two electrons."}, {"id": "4.7-p4", "m": "4.7", "c": 4, "k": "problem", "f": "25.0 mL of HCl is exactly neutralised by 20.0 mL of 0.100 M NaOH. What is the concentration of the HCl?", "b": "0.08 mol/L. 1:1 ratio; c = 0.00200/0.0250 = 0.080 M."}, {"id": "4.7-p5", "m": "4.7", "c": 4, "k": "problem", "f": "A weak acid differs from a strong acid in that it", "b": "ionises only partially. Strength is about extent of ionisation."}, {"id": "4.7-p6", "m": "4.7", "c": 4, "k": "problem", "f": "What is the pH of 0.01 M NaOH at 25 °C?", "b": "12. pH = 12."}, {"id": "4.7-p7", "m": "4.7", "c": 4, "k": "problem", "f": "What are the products of an acid reacting with a metal hydroxide?", "b": "salt and water. Neutralisation."}, {"id": "4.7-p8", "m": "4.7", "c": 4, "k": "problem", "f": "Explain why a battery 'goes flat'.", "b": "A battery is a redox reaction separated into two halves. As it runs, the reactants are used up: the substance being oxidised and the one being reduced are converted to products. Once they are depleted, the electron 'push' between the two halves drops and the current stops. Recharging drives the reaction backwards with an external supply."}, {"id": "4.8-e1", "m": "4.8", "c": 4, "k": "equation", "f": "Write the equation: Alkane formula", "tex": "\\mathrm{C_nH_{2n+2}}"}, {"id": "4.8-e2", "m": "4.8", "c": 4, "k": "equation", "f": "Write the equation: Esterification", "tex": "\\mathrm{acid} + \\mathrm{alcohol} \\rightleftharpoons \\mathrm{ester} + \\mathrm{water}"}, {"id": "4.8-e3", "m": "4.8", "c": 4, "k": "equation", "f": "Write the equation: Addition polymerisation", "tex": "n\\,\\mathrm{CH_2{=}CH_2} \\rightarrow (\\mathrm{CH_2{-}CH_2})_n"}, {"id": "4.8-k1", "m": "4.8", "c": 4, "k": "key idea", "f": "Complete the key idea: Carbon forms four …", "b": "Carbon forms four bonds and long chains"}, {"id": "4.8-k2", "m": "4.8", "c": 4, "k": "key idea", "f": "Complete the key idea: Alkanes CₙH₂ₙ₊₂; meth, …", "b": "Alkanes CₙH₂ₙ₊₂; meth, eth, prop, but count carbons"}, {"id": "4.8-k3", "m": "4.8", "c": 4, "k": "key idea", "f": "Complete the key idea: Functional groups …", "b": "Functional groups decide reactions"}, {"id": "4.8-k4", "m": "4.8", "c": 4, "k": "key idea", "f": "Complete the key idea: Polymers are repeating units; …", "b": "Polymers are repeating units; proteins, starch and DNA are polymers"}, {"id": "4.8-q1", "m": "4.8", "c": 4, "k": "quick check", "f": "Carbon forms how many bonds?", "b": "4"}, {"id": "4.8-q2", "m": "4.8", "c": 4, "k": "quick check", "f": "An ester forms from", "b": "acid + alcohol"}, {"id": "4.8-q3", "m": "4.8", "c": 4, "k": "quick check", "f": "'But-' means how many carbons?", "b": "4"}, {"id": "4.8-q4", "m": "4.8", "c": 4, "k": "quick check", "f": "Polyethylene is made from", "b": "ethene"}, {"id": "4.8-p1", "m": "4.8", "c": 4, "k": "problem", "f": "What is the formula of propane (3 carbons)?", "b": "C₃H₈. CₙH₂ₙ₊₂ with n = 3."}, {"id": "4.8-p2", "m": "4.8", "c": 4, "k": "problem", "f": "Octane is an alkane with 8 carbon atoms. How many hydrogen atoms does it have?", "b": "18. 2(8) + 2 = 18."}, {"id": "4.8-p3", "m": "4.8", "c": 4, "k": "problem", "f": "Which functional group identifies an alcohol?", "b": "–OH. Hydroxyl group."}, {"id": "4.8-p4", "m": "4.8", "c": 4, "k": "problem", "f": "Vinegar's ethanoic acid belongs to which family?", "b": "carboxylic acids. –COOH group."}, {"id": "4.8-p5", "m": "4.8", "c": 4, "k": "problem", "f": "Butane and methylpropane are", "b": "isomers. Same formula, C₄H₁₀; different structures."}, {"id": "4.8-p6", "m": "4.8", "c": 4, "k": "problem", "f": "Proteins are polymers of", "b": "amino acids. Amino acids joined by peptide bonds."}, {"id": "4.8-p7", "m": "4.8", "c": 4, "k": "problem", "f": "What is the molar mass of ethanol, C₂H₅OH? (C = 12, H = 1, O = 16)", "b": "46 g/mol. 2(12) + 6(1) + 16 = 46."}, {"id": "4.8-p8", "m": "4.8", "c": 4, "k": "problem", "f": "Why can carbon form far more compounds than any other element?", "b": "Carbon forms four strong covalent bonds, so each atom can connect in several directions. Carbon–carbon bonds are strong enough to build stable long chains, branches and rings. It also bonds well with H, O, N and other elements, and can form single, double and triple bonds. Together these allow an almost limitless variety of structures."}, {"id": "5.1-e1", "m": "5.1", "c": 5, "k": "equation", "f": "Write the equation: Earth's axial tilt", "tex": "\\varepsilon \\approx 23.4^\\circ"}, {"id": "5.1-e2", "m": "5.1", "c": 5, "k": "equation", "f": "Write the equation: Noon Sun altitude at the solstices", "tex": "h = 90^\\circ - |\\mathrm{latitude}| \\pm 23.4^\\circ"}, {"id": "5.1-e3", "m": "5.1", "c": 5, "k": "equation", "f": "Write the equation: Synodic month", "tex": "P_{\\mathrm{phases}} \\approx 29.5\\ \\mathrm{days}"}, {"id": "5.1-k1", "m": "5.1", "c": 5, "k": "key idea", "f": "Complete the key idea: Seasons come from …", "b": "Seasons come from axial tilt, not distance"}, {"id": "5.1-k2", "m": "5.1", "c": 5, "k": "key idea", "f": "Complete the key idea: Phases: how much of …", "b": "Phases: how much of the Moon's lit half we see"}, {"id": "5.1-k3", "m": "5.1", "c": 5, "k": "key idea", "f": "Complete the key idea: Southern sky: Southern …", "b": "Southern sky: Southern Cross, Magellanic Clouds, galactic centre"}, {"id": "5.1-k4", "m": "5.1", "c": 5, "k": "key idea", "f": "Complete the key idea: Copernicus, Tycho, Kepler and …", "b": "Copernicus, Tycho, Kepler and Galileo moved the Sun to the centre"}, {"id": "5.1-q1", "m": "5.1", "c": 5, "k": "quick check", "f": "Earth's axial tilt is about", "b": "23.4°"}, {"id": "5.1-q2", "m": "5.1", "c": 5, "k": "quick check", "f": "The Magellanic Clouds are", "b": "nearby galaxies"}, {"id": "5.1-q3", "m": "5.1", "c": 5, "k": "quick check", "f": "Copernicus put at the centre", "b": "the Sun"}, {"id": "5.1-q4", "m": "5.1", "c": 5, "k": "quick check", "f": "The Moon's phase cycle is about", "b": "29.5 days"}, {"id": "5.1-p1", "m": "5.1", "c": 5, "k": "problem", "f": "What causes Earth's seasons?", "b": "the tilt of Earth's axis. Tilt changes how directly sunlight strikes each hemisphere."}, {"id": "5.1-p2", "m": "5.1", "c": 5, "k": "problem", "f": "Why does the Moon show phases?", "b": "we see different amounts of its sunlit half. Half is always lit; our viewing angle changes."}, {"id": "5.1-p3", "m": "5.1", "c": 5, "k": "problem", "f": "Brisbane is at latitude 27.5° S. What is the Sun's noon altitude at the December (summer) solstice, in degrees?", "b": "85.9 °. ≈ 85.9°, almost overhead."}, {"id": "5.1-p4", "m": "5.1", "c": 5, "k": "problem", "f": "And at the June (winter) solstice?", "b": "39.1 °. h = 90 − 27.5 − 23.4 ≈ 39.1°."}, {"id": "5.1-p5", "m": "5.1", "c": 5, "k": "problem", "f": "In which month is Earth closest to the Sun?", "b": "January. Perihelion is around 3–4 January."}, {"id": "5.1-p6", "m": "5.1", "c": 5, "k": "problem", "f": "Who first showed planetary orbits are ellipses?", "b": "Kepler. Kepler, using Tycho's data, 1609."}, {"id": "5.1-p7", "m": "5.1", "c": 5, "k": "problem", "f": "Galileo's observation that Venus shows a full set of phases supported", "b": "the Sun-centred model. Full phases require Venus to orbit the Sun."}, {"id": "5.1-p8", "m": "5.1", "c": 5, "k": "problem", "f": "Why can't people in Europe see the Southern Cross?", "b": "The Southern Cross lies close to the south celestial pole. From northern latitudes, that part of the celestial sphere stays permanently below the horizon as Earth rotates, so it never rises. You need to be roughly south of about 25° N to see it."}, {"id": "5.2-e1", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Kepler's third law (Solar System units)", "tex": "T^2 = a^3\\quad (T\\ \\mathrm{in\\ years},\\ a\\ \\mathrm{in\\ AU})"}, {"id": "5.2-e2", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Universal gravitation", "tex": "F = \\frac{GMm}{r^2},\\quad G = 6.67 \\times 10^{-11}\\ \\mathrm{N\\,m^2\\,kg^{-2}}"}, {"id": "5.2-e3", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Surface gravity", "tex": "g = \\frac{GM}{R^2}"}, {"id": "5.2-e4", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Circular orbital speed", "tex": "v = \\sqrt{\\frac{GM}{r}}"}, {"id": "5.2-e5", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Kepler's third law (Newton's form)", "tex": "T^2 = \\frac{4\\pi^2}{GM}\\,r^3"}, {"id": "5.2-e6", "m": "5.2", "c": 5, "k": "equation", "f": "Write the equation: Escape velocity", "tex": "v_{\\mathrm{esc}} = \\sqrt{\\frac{2GM}{R}}"}, {"id": "5.2-k1", "m": "5.2", "c": 5, "k": "key idea", "f": "Complete the key idea: Kepler: ellipses, equal …", "b": "Kepler: ellipses, equal areas, T² ∝ a³"}, {"id": "5.2-k2", "m": "5.2", "c": 5, "k": "key idea", "f": "Complete the key idea: Newton: F = …", "b": "Newton: F = GMm/r², an inverse-square law"}, {"id": "5.2-k3", "m": "5.2", "c": 5, "k": "key idea", "f": "Complete the key idea: Orbital speed v = …", "b": "Orbital speed v = √(GM/r), independent of the orbiting mass"}, {"id": "5.2-k4", "m": "5.2", "c": 5, "k": "key idea", "f": "Complete the key idea: Measuring an orbit …", "b": "Measuring an orbit weighs the central body"}, {"id": "5.2-q1", "m": "5.2", "c": 5, "k": "quick check", "f": "Gravitational force between two masses varies as", "b": "1/r²"}, {"id": "5.2-q2", "m": "5.2", "c": 5, "k": "quick check", "f": "Kepler's first law says orbits are", "b": "ellipses"}, {"id": "5.2-q3", "m": "5.2", "c": 5, "k": "quick check", "f": "Orbital speed depends on", "b": "the central mass and distance"}, {"id": "5.2-q4", "m": "5.2", "c": 5, "k": "quick check", "f": "Cavendish's experiment measured", "b": "G"}, {"id": "5.2-p1", "m": "5.2", "c": 5, "k": "problem", "f": "A planet orbits at 4 AU from the Sun. What is its period in years?", "b": "8 years. T² = 4³ = 64."}, {"id": "5.2-p2", "m": "5.2", "c": 5, "k": "problem", "f": "If the distance between two masses triples, by what factor does the gravitational force change? Give a decimal.", "b": "0.1111. Inverse square: 1/3² = 1/9 ≈ 0.111."}, {"id": "5.2-p3", "m": "5.2", "c": 5, "k": "problem", "f": "Mars has mass 6.42 × 10²³ kg and radius 3.39 × 10⁶ m. What is its surface gravity?", "b": "3.726 m/s². ≈ 3.7 m/s²."}, {"id": "5.2-p4", "m": "5.2", "c": 5, "k": "problem", "f": "The ISS orbits at r = 6.78 × 10⁶ m from Earth's centre. Earth's GM = 3.99 × 10¹⁴ m³/s². What is its orbital speed?", "b": "7671 m/s. ≈ 7670 m/s."}, {"id": "5.2-p6", "m": "5.2", "c": 5, "k": "problem", "f": "Astronauts in the ISS float because", "b": "they are in free fall with the station. Gravity there is about 90% of surface strength."}, {"id": "5.2-p7", "m": "5.2", "c": 5, "k": "problem", "f": "What is the escape velocity from the Moon? (GM = 4.9 × 10¹² m³/s², R = 1.74 × 10⁶ m)", "b": "2373 m/s. ≈ 2370 m/s."}, {"id": "5.2-p8", "m": "5.2", "c": 5, "k": "problem", "f": "By Kepler's second law, a comet moves fastest", "b": "closest to the Sun. Equal areas in equal times."}, {"id": "5.3-e1", "m": "5.3", "c": 5, "k": "equation", "f": "Write the equation: Inverse-square law", "tex": "b = \\frac{L}{4\\pi d^2}"}, {"id": "5.3-e2", "m": "5.3", "c": 5, "k": "equation", "f": "Write the equation: Parallax distance", "tex": "d\\,(\\mathrm{pc}) = \\frac{1}{p\\,(\\mathrm{arcsec})},\\quad 1\\ \\mathrm{pc} \\approx 3.26\\ \\mathrm{ly}"}, {"id": "5.3-e3", "m": "5.3", "c": 5, "k": "equation", "f": "Write the equation: Wien's law", "tex": "\\lambda_{\\max} = \\frac{2.90 \\times 10^{-3}\\ \\mathrm{m\\,K}}{T}"}, {"id": "5.3-e4", "m": "5.3", "c": 5, "k": "equation", "f": "Write the equation: Doppler shift (v much less than c)", "tex": "\\frac{\\Delta\\lambda}{\\lambda} = \\frac{v}{c}"}, {"id": "5.3-k1", "m": "5.3", "c": 5, "k": "key idea", "f": "Complete the key idea: Telescopes go to space …", "b": "Telescopes go to space for wavelengths the atmosphere blocks"}, {"id": "5.3-k2", "m": "5.3", "c": 5, "k": "key idea", "f": "Complete the key idea: Brightness ∝ 1/distance²; parallax …", "b": "Brightness ∝ 1/distance²; parallax gives distances to nearby stars"}, {"id": "5.3-k3", "m": "5.3", "c": 5, "k": "key idea", "f": "Complete the key idea: Hotter means …", "b": "Hotter means bluer: λ_max ∝ 1/T"}, {"id": "5.3-k4", "m": "5.3", "c": 5, "k": "key idea", "f": "Complete the key idea: Spectral lines reveal …", "b": "Spectral lines reveal composition; their shift reveals motion"}, {"id": "5.3-q1", "m": "5.3", "c": 5, "k": "quick check", "f": "A redshift means the source is", "b": "receding"}, {"id": "5.3-q2", "m": "5.3", "c": 5, "k": "quick check", "f": "Hotter stars appear", "b": "bluer"}, {"id": "5.3-q3", "m": "5.3", "c": 5, "k": "quick check", "f": "1 parsec is about", "b": "3.26 light-years"}, {"id": "5.3-q4", "m": "5.3", "c": 5, "k": "quick check", "f": "Absorption lines tell us a star's", "b": "composition"}, {"id": "5.3-p1", "m": "5.3", "c": 5, "k": "problem", "f": "A star is moved to three times its distance. By what factor does its apparent brightness change? Give a decimal.", "b": "0.1111. Inverse square: 1/9."}, {"id": "5.3-p2", "m": "5.3", "c": 5, "k": "problem", "f": "A star has a parallax of 0.25 arcseconds. How far away is it, in parsecs?", "b": "4 pc. d = 1/p = 1/0.25."}, {"id": "5.3-p3", "m": "5.3", "c": 5, "k": "problem", "f": "Convert 4 parsecs to light-years.", "b": "13.04 ly. 4 × 3.26 ≈ 13 ly."}, {"id": "5.3-p4", "m": "5.3", "c": 5, "k": "problem", "f": "The Sun's surface is about 5800 K. What is its peak wavelength in nanometres?", "b": "500 nm. = 500 nm, green-blue."}, {"id": "5.3-p5", "m": "5.3", "c": 5, "k": "problem", "f": "A star's peak wavelength is 290 nm. What is its surface temperature?", "b": "1e+04 K. T = 2.90 × 10⁻³ / 2.90 × 10⁻⁷ = 10 000 K."}, {"id": "5.3-p6", "m": "5.3", "c": 5, "k": "problem", "f": "A hydrogen line normally at 656.3 nm is observed at 656.9 nm. How fast is the star receding, in km/s? (c = 3.0 × 10⁵ km/s)", "b": "274.3 km/s. v = 9.14 × 10⁻⁴ × 3 × 10⁵ ≈ 274 km/s."}, {"id": "5.3-p7", "m": "5.3", "c": 5, "k": "problem", "f": "Why are X-ray telescopes placed in space?", "b": "Earth's atmosphere absorbs X-rays. The atmosphere is opaque to X-rays."}, {"id": "5.3-p8", "m": "5.3", "c": 5, "k": "problem", "f": "How did astronomers know helium existed before it was found on Earth?", "b": "In 1868, during a solar eclipse, a bright spectral line was seen in the Sun's light at a wavelength that matched no known element. Since every element has a unique set of lines, it had to be a new element, named after the Greek Helios. It was isolated on Earth in 1895."}, {"id": "5.4-e1", "m": "5.4", "c": 5, "k": "equation", "f": "Write the equation: Solar power from mass loss", "tex": "P = \\frac{\\Delta m}{\\Delta t}c^2 \\approx 3.8 \\times 10^{26}\\ \\mathrm{W}"}, {"id": "5.4-e2", "m": "5.4", "c": 5, "k": "equation", "f": "Write the equation: Astronomical unit", "tex": "1\\ \\mathrm{AU} \\approx 1.50 \\times 10^{11}\\ \\mathrm{m}"}, {"id": "5.4-e3", "m": "5.4", "c": 5, "k": "equation", "f": "Write the equation: Transit depth", "tex": "\\frac{\\Delta F}{F} \\approx \\left(\\frac{R_{\\mathrm{planet}}}{R_{\\mathrm{star}}}\\right)^2"}, {"id": "5.4-k1", "m": "5.4", "c": 5, "k": "key idea", "f": "Complete the key idea: The Sun is a fusion-powered …", "b": "The Sun is a fusion-powered ball of plasma with 99% of the mass"}, {"id": "5.4-k2", "m": "5.4", "c": 5, "k": "key idea", "f": "Complete the key idea: Inner planets rocky, outer …", "b": "Inner planets rocky, outer planets giants: the frost line explains it"}, {"id": "5.4-k3", "m": "5.4", "c": 5, "k": "key idea", "f": "Complete the key idea: The Solar System formed from …", "b": "The Solar System formed from a spinning disc 4.6 billion years ago"}, {"id": "5.4-k4", "m": "5.4", "c": 5, "k": "key idea", "f": "Complete the key idea: Exoplanets: transits …", "b": "Exoplanets: transits and Doppler wobbles"}, {"id": "5.4-q1", "m": "5.4", "c": 5, "k": "quick check", "f": "The Sun contains about what share of the Solar System's mass?", "b": "over 99%"}, {"id": "5.4-q2", "m": "5.4", "c": 5, "k": "quick check", "f": "The Solar System is about how old?", "b": "4.6 billion years"}, {"id": "5.4-q3", "m": "5.4", "c": 5, "k": "quick check", "f": "The transit method detects planets by", "b": "starlight dimming"}, {"id": "5.4-q4", "m": "5.4", "c": 5, "k": "quick check", "f": "Uranus and Neptune are", "b": "ice giants"}, {"id": "5.4-p1", "m": "5.4", "c": 5, "k": "problem", "f": "What powers the Sun?", "b": "nuclear fusion. Hydrogen fuses into helium in the core."}, {"id": "5.4-p2", "m": "5.4", "c": 5, "k": "problem", "f": "Jupiter is 5.2 AU from the Sun. How many kilometres is that? (1 AU = 1.5 × 10⁸ km)", "b": "7.800e+08 km. 5.2 × 1.5 × 10⁸ = 7.8 × 10⁸ km."}, {"id": "5.4-p3", "m": "5.4", "c": 5, "k": "problem", "f": "How long does sunlight take to reach Neptune, 30 AU away, in hours? (Earth: 500 s)", "b": "4.167 h. ÷ 3600 ≈ 4.2 h."}, {"id": "5.4-p4", "m": "5.4", "c": 5, "k": "problem", "f": "Why are the inner planets rocky and the outer ones gas giants?", "b": "near the Sun it was too hot for ices to condense. The frost line."}, {"id": "5.4-p5", "m": "5.4", "c": 5, "k": "problem", "f": "Why do the planets orbit in nearly the same plane?", "b": "they formed from a flattened spinning disc. Conservation of angular momentum flattened the cloud."}, {"id": "5.4-p6", "m": "5.4", "c": 5, "k": "problem", "f": "A Jupiter-sized planet (radius 0.1 × the star's) transits its star. By what fraction does the starlight dim? Give a decimal.", "b": "0.01. (0.1)² = 0.01, a 1% dip."}, {"id": "5.4-p8", "m": "5.4", "c": 5, "k": "problem", "f": "Why is Venus hotter than Mercury even though it is further from the Sun?", "b": "Venus has a very thick carbon dioxide atmosphere. Sunlight warms the surface, which radiates infrared; the CO₂ traps that infrared (a runaway greenhouse effect), raising the surface to about 465 °C. Mercury has almost no atmosphere, so its heat escapes and its night side gets very cold."}, {"id": "5.5-e1", "m": "5.5", "c": 5, "k": "equation", "f": "Write the equation: Stefan–Boltzmann law", "tex": "L = 4\\pi R^2\\sigma T^4,\\quad \\sigma = 5.67 \\times 10^{-8}\\ \\mathrm{W\\,m^{-2}K^{-4}}"}, {"id": "5.5-e2", "m": "5.5", "c": 5, "k": "equation", "f": "Write the equation: Main-sequence lifetime", "tex": "t \\approx 10^{10}\\left(\\frac{M}{M_\\odot}\\right)^{-2.5}\\ \\mathrm{years}"}, {"id": "5.5-e3", "m": "5.5", "c": 5, "k": "equation", "f": "Write the equation: Hydrogen fusion (net)", "tex": "4\\,{}^{1}\\mathrm{H} \\rightarrow {}^{4}\\mathrm{He} + \\mathrm{energy}"}, {"id": "5.5-k1", "m": "5.5", "c": 5, "k": "key idea", "f": "Complete the key idea: Stars balance gravity …", "b": "Stars balance gravity against pressure from fusion energy"}, {"id": "5.5-k2", "m": "5.5", "c": 5, "k": "key idea", "f": "Complete the key idea: L = 4πR²σT⁴: luminosity …", "b": "L = 4πR²σT⁴: luminosity depends on size and temperature⁴"}, {"id": "5.5-k3", "m": "5.5", "c": 5, "k": "key idea", "f": "Complete the key idea: HR diagram: main …", "b": "HR diagram: main sequence, giants, white dwarfs"}, {"id": "5.5-k4", "m": "5.5", "c": 5, "k": "key idea", "f": "Complete the key idea: More massive stars are …", "b": "More massive stars are brighter and live much shorter lives"}, {"id": "5.5-q1", "m": "5.5", "c": 5, "k": "quick check", "f": "Stars are powered by", "b": "fusion"}, {"id": "5.5-q2", "m": "5.5", "c": 5, "k": "quick check", "f": "On an HR diagram, hot stars are traditionally on the", "b": "left"}, {"id": "5.5-q3", "m": "5.5", "c": 5, "k": "quick check", "f": "Luminosity depends on temperature to the power", "b": "4"}, {"id": "5.5-q4", "m": "5.5", "c": 5, "k": "quick check", "f": "The most massive stars have", "b": "the shortest lives"}, {"id": "5.5-p1", "m": "5.5", "c": 5, "k": "problem", "f": "Two stars are the same size, but one is twice as hot. How many times more luminous is it?", "b": "16 ×. 2⁴ = 16."}, {"id": "5.5-p2", "m": "5.5", "c": 5, "k": "problem", "f": "A star has the same temperature as the Sun but 10 times its radius. How many times more luminous is it?", "b": "100 ×. 10² = 100."}, {"id": "5.5-p3", "m": "5.5", "c": 5, "k": "problem", "f": "On the HR diagram, a hot but very faint star is most likely a", "b": "white dwarf. Hot and faint means small."}, {"id": "5.5-p4", "m": "5.5", "c": 5, "k": "problem", "f": "Using t ≈ 10¹⁰ × M^(−2.5) years, estimate the lifetime of a star of 4 solar masses.", "b": "3.125e+08 years. 10¹⁰ ÷ 32 ≈ 3.1 × 10⁸ years."}, {"id": "5.5-p5", "m": "5.5", "c": 5, "k": "problem", "f": "What keeps a stable star from collapsing?", "b": "pressure from hot gas and radiation. Pressure balances gravity."}, {"id": "5.5-p6", "m": "5.5", "c": 5, "k": "problem", "f": "In hydrogen fusion about 0.7% of mass becomes energy. How much energy comes from fusing 1 kg of hydrogen? (c = 3 × 10⁸ m/s)", "b": "6.300e+14 J. E = 0.007 × 9 × 10¹⁶ = 6.3 × 10¹⁴ J."}, {"id": "5.5-p7", "m": "5.5", "c": 5, "k": "problem", "f": "Where do stars spend most of their lives?", "b": "on the main sequence. Fusing hydrogen in the core."}, {"id": "5.5-p8", "m": "5.5", "c": 5, "k": "problem", "f": "Massive stars have much more fuel than the Sun. Why do they live much shorter lives?", "b": "Luminosity rises far faster than mass, roughly as M^3.5. A star ten times the Sun's mass has ten times the fuel but burns it thousands of times faster, so it runs out in a fraction of the time: lifetime goes roughly as M/L ∝ M^−2.5."}, {"id": "5.6-e1", "m": "5.6", "c": 5, "k": "equation", "f": "Write the equation: Schwarzschild radius", "tex": "R_s = \\frac{2GM}{c^2}"}, {"id": "5.6-e2", "m": "5.6", "c": 5, "k": "equation", "f": "Write the equation: Density", "tex": "\\rho = \\frac{M}{\\frac{4}{3}\\pi R^3}"}, {"id": "5.6-e3", "m": "5.6", "c": 5, "k": "equation", "f": "Write the equation: Chandrasekhar limit (white dwarf maximum)", "tex": "M_{\\max} \\approx 1.4\\,M_\\odot"}, {"id": "5.6-k1", "m": "5.6", "c": 5, "k": "key idea", "f": "Complete the key idea: Sun-like stars: red …", "b": "Sun-like stars: red giant, planetary nebula, white dwarf"}, {"id": "5.6-k2", "m": "5.6", "c": 5, "k": "key idea", "f": "Complete the key idea: Massive stars: …", "b": "Massive stars: iron core collapse, supernova"}, {"id": "5.6-k3", "m": "5.6", "c": 5, "k": "key idea", "f": "Complete the key idea: Heavy elements are …", "b": "Heavy elements are made in stars and supernovae"}, {"id": "5.6-k4", "m": "5.6", "c": 5, "k": "key idea", "f": "Complete the key idea: Remnants: white dwarf, neutron …", "b": "Remnants: white dwarf, neutron star or black hole, by mass"}, {"id": "5.6-q1", "m": "5.6", "c": 5, "k": "quick check", "f": "A planetary nebula is", "b": "the ejected outer layers of a dying star"}, {"id": "5.6-q2", "m": "5.6", "c": 5, "k": "quick check", "f": "Neutron stars are about the size of", "b": "a city"}, {"id": "5.6-q3", "m": "5.6", "c": 5, "k": "quick check", "f": "A black hole's boundary is the", "b": "event horizon"}, {"id": "5.6-q4", "m": "5.6", "c": 5, "k": "quick check", "f": "Supernovae occur for stars above about", "b": "8. About eight solar masses."}, {"id": "5.6-p1", "m": "5.6", "c": 5, "k": "problem", "f": "What will the Sun become at the end of its life?", "b": "a white dwarf. It is too low in mass for a supernova."}, {"id": "5.6-p2", "m": "5.6", "c": 5, "k": "problem", "f": "Where were most of the heavy elements in your body made?", "b": "inside stars and supernovae. Stellar nucleosynthesis."}, {"id": "5.6-p3", "m": "5.6", "c": 5, "k": "problem", "f": "What is the Schwarzschild radius of a 10 solar-mass black hole, in km? (M☉ = 2.0 × 10³⁰ kg, G = 6.67 × 10⁻¹¹, c = 3.0 × 10⁸)", "b": "29.64 km. ≈ 29 600 m ≈ 30 km."}, {"id": "5.6-p4", "m": "5.6", "c": 5, "k": "problem", "f": "A white dwarf has mass 1.2 × 10³⁰ kg and radius 6.0 × 10⁶ m. What is its density, in kg/m³?", "b": "1.326e+09 kg/m³. ρ ≈ 1.3 × 10⁹ kg/m³."}, {"id": "5.6-p5", "m": "5.6", "c": 5, "k": "problem", "f": "Why does fusion stop at iron in massive stars?", "b": "fusing iron absorbs rather than releases energy. Iron has the most tightly bound nucleus."}, {"id": "5.6-p6", "m": "5.6", "c": 5, "k": "problem", "f": "Pulsars are", "b": "rotating neutron stars. Discovered by Jocelyn Bell Burnell, 1967."}, {"id": "5.6-p7", "m": "5.6", "c": 5, "k": "problem", "f": "What is the maximum mass of a white dwarf?", "b": "about 1.4 solar masses. The Chandrasekhar limit."}, {"id": "5.6-p8", "m": "5.6", "c": 5, "k": "problem", "f": "If the Sun were replaced by a black hole of the same mass, what would happen to Earth's orbit, and why?", "b": "Nothing would change in the orbit. Gravity outside a spherical mass depends only on the mass and distance (F = GMm/r²), not on how compact the object is. Earth would keep orbiting at the same distance and speed, though it would be dark and cold."}, {"id": "5.7-e1", "m": "5.7", "c": 5, "k": "equation", "f": "Write the equation: Orbital period around the galaxy", "tex": "T = \\frac{2\\pi r}{v}"}, {"id": "5.7-e2", "m": "5.7", "c": 5, "k": "equation", "f": "Write the equation: Mass inside an orbit", "tex": "M = \\frac{v^2 r}{G}"}, {"id": "5.7-e3", "m": "5.7", "c": 5, "k": "equation", "f": "Write the equation: Light-year", "tex": "1\\ \\mathrm{ly} \\approx 9.46 \\times 10^{15}\\ \\mathrm{m}"}, {"id": "5.7-k1", "m": "5.7", "c": 5, "k": "key idea", "f": "Complete the key idea: The Milky Way is a barred …", "b": "The Milky Way is a barred spiral; the Sun is 26 000 ly from the centre"}, {"id": "5.7-k2", "m": "5.7", "c": 5, "k": "key idea", "f": "Complete the key idea: Galaxy types: …", "b": "Galaxy types: spiral, elliptical, irregular"}, {"id": "5.7-k3", "m": "5.7", "c": 5, "k": "key idea", "f": "Complete the key idea: Supermassive black holes …", "b": "Supermassive black holes sit at galactic centres"}, {"id": "5.7-k4", "m": "5.7", "c": 5, "k": "key idea", "f": "Complete the key idea: Flat rotation …", "b": "Flat rotation curves reveal dark matter"}, {"id": "5.7-q1", "m": "5.7", "c": 5, "k": "quick check", "f": "The Milky Way contains roughly how many stars?", "b": "hundreds of billions"}, {"id": "5.7-q2", "m": "5.7", "c": 5, "k": "quick check", "f": "Vera Rubin's work provided evidence for", "b": "dark matter"}, {"id": "5.7-q3", "m": "5.7", "c": 5, "k": "quick check", "f": "Andromeda is", "b": "a separate galaxy"}, {"id": "5.7-q4", "m": "5.7", "c": 5, "k": "quick check", "f": "Our galaxy's central black hole has a mass of about", "b": "4 million solar masses"}, {"id": "5.7-p1", "m": "5.7", "c": 5, "k": "problem", "f": "What type of galaxy is the Milky Way?", "b": "barred spiral. A barred spiral."}, {"id": "5.7-p3", "m": "5.7", "c": 5, "k": "problem", "f": "Using M = v²r/G with the numbers above, estimate the mass inside the Sun's orbit, in kg.", "b": "1.983e+41 kg. ≈ 2.0 × 10⁴¹ kg, about 10¹¹ solar masses."}, {"id": "5.7-p4", "m": "5.7", "c": 5, "k": "problem", "f": "Flat galaxy rotation curves are evidence for", "b": "dark matter. Extra unseen mass in the halo."}, {"id": "5.7-p5", "m": "5.7", "c": 5, "k": "problem", "f": "Andromeda is 2.5 million light-years away. When we look at it, how long ago did that light leave, in years?", "b": "2.500e+06 years. One light-year per year of travel."}, {"id": "5.7-p6", "m": "5.7", "c": 5, "k": "problem", "f": "Elliptical galaxies typically contain", "b": "mostly old stars and little gas. They are red and dead, mostly."}, {"id": "5.7-p7", "m": "5.7", "c": 5, "k": "problem", "f": "How was the mass of the black hole at the Milky Way's centre measured?", "b": "from the orbits of nearby stars. Kepler's third law applied to stars orbiting it."}, {"id": "5.7-p8", "m": "5.7", "c": 5, "k": "problem", "f": "Why did astronomers expect stars far from a galaxy's centre to orbit more slowly, and what did they find?", "b": "If most of the mass were concentrated in the bright centre, orbital speed far out would fall as v = √(GM/r), like the outer planets. Instead, speeds stay roughly constant at large radius, which means the enclosed mass keeps growing with distance even where little light is seen. This implies a large halo of dark matter."}, {"id": "5.8-e1", "m": "5.8", "c": 5, "k": "equation", "f": "Write the equation: Hubble's law", "tex": "v = H_0 d,\\quad H_0 \\approx 70\\ \\mathrm{km\\,s^{-1}\\,Mpc^{-1}}"}, {"id": "5.8-e2", "m": "5.8", "c": 5, "k": "equation", "f": "Write the equation: Hubble time", "tex": "t \\approx \\frac{1}{H_0}"}, {"id": "5.8-e3", "m": "5.8", "c": 5, "k": "equation", "f": "Write the equation: Composition today", "tex": "\\Omega_b \\approx 0.05,\\quad \\Omega_{dm} \\approx 0.27,\\quad \\Omega_\\Lambda \\approx 0.68"}, {"id": "5.8-e4", "m": "5.8", "c": 5, "k": "equation", "f": "Write the equation: Cosmological redshift", "tex": "z = \\frac{\\lambda_{\\mathrm{obs}} - \\lambda_{\\mathrm{emit}}}{\\lambda_{\\mathrm{emit}}}"}, {"id": "5.8-k1", "m": "5.8", "c": 5, "k": "key idea", "f": "Complete the key idea: Hubble's law: v = …", "b": "Hubble's law: v = H₀d; space itself is expanding"}, {"id": "5.8-k2", "m": "5.8", "c": 5, "k": "key idea", "f": "Complete the key idea: Age ≈ 1/H₀ …", "b": "Age ≈ 1/H₀ ≈ 13.8 billion years"}, {"id": "5.8-k3", "m": "5.8", "c": 5, "k": "key idea", "f": "Complete the key idea: Big Bang evidence: …", "b": "Big Bang evidence: expansion, microwave background, light-element abundances"}, {"id": "5.8-k4", "m": "5.8", "c": 5, "k": "key idea", "f": "Complete the key idea: Universe: 5% ordinary matter, …", "b": "Universe: 5% ordinary matter, 27% dark matter, 68% dark energy"}, {"id": "5.8-q1", "m": "5.8", "c": 5, "k": "quick check", "f": "Hubble's law says recession speed is proportional to", "b": "distance"}, {"id": "5.8-q2", "m": "5.8", "c": 5, "k": "quick check", "f": "The universe is about how old?", "b": "13.8 billion years"}, {"id": "5.8-q3", "m": "5.8", "c": 5, "k": "quick check", "f": "The expansion of the universe is", "b": "accelerating"}, {"id": "5.8-q4", "m": "5.8", "c": 5, "k": "quick check", "f": "The CMB has a temperature of about", "b": "2.7 K"}, {"id": "5.8-p1", "m": "5.8", "c": 5, "k": "problem", "f": "A galaxy is 100 Mpc away. Using H₀ = 70 km/s/Mpc, how fast is it receding?", "b": "7000 km/s. v = H₀d = 70 × 100."}, {"id": "5.8-p2", "m": "5.8", "c": 5, "k": "problem", "f": "A galaxy recedes at 14 000 km/s. How far away is it?", "b": "200 Mpc. d = v/H₀ = 14 000/70."}, {"id": "5.8-p3", "m": "5.8", "c": 5, "k": "problem", "f": "Estimate the age of the universe as 1/H₀. H₀ = 70 km/s/Mpc, 1 Mpc = 3.09 × 10¹⁹ km, 1 year = 3.15 × 10⁷ s. Give billions of years.", "b": "14.01 billion years. ÷ 3.15 × 10⁷ ≈ 1.4 × 10¹⁰ years."}, {"id": "5.8-p4", "m": "5.8", "c": 5, "k": "problem", "f": "A line emitted at 500 nm is observed at 600 nm. What is the redshift z?", "b": "0.2. z = (600 − 500)/500."}, {"id": "5.8-p5", "m": "5.8", "c": 5, "k": "problem", "f": "The cosmic microwave background is", "b": "light released when atoms first formed, now stretched to microwaves. About 380 000 years after the Big Bang."}, {"id": "5.8-p6", "m": "5.8", "c": 5, "k": "problem", "f": "Which is NOT one of the main pillars of evidence for the Big Bang?", "b": "the existence of black holes. Black holes are not evidence for the Big Bang."}, {"id": "5.8-p7", "m": "5.8", "c": 5, "k": "problem", "f": "Roughly what fraction of the universe is ordinary matter?", "b": "5%. The rest is dark matter and dark energy."}, {"id": "5.8-p8", "m": "5.8", "c": 5, "k": "problem", "f": "If all galaxies are moving away from us, does that mean we are at the centre of the universe? Explain.", "b": "No. In a uniformly expanding universe, every observer sees every other galaxy receding, with speed proportional to distance. Like dots on an inflating balloon, no dot is special. The expansion is of space itself, with no centre and no edge."}, {"id": "6.1-e1", "m": "6.1", "c": 6, "k": "equation", "f": "Write the equation: Condensation (making a polymer)", "tex": "\\mathrm{monomer} + \\mathrm{monomer} \\rightarrow \\mathrm{dimer} + \\mathrm{H_2O}"}, {"id": "6.1-e2", "m": "6.1", "c": 6, "k": "equation", "f": "Write the equation: Enzyme kinetics (Michaelis–Menten)", "tex": "v = \\frac{V_{\\max}[S]}{K_m + [S]}"}, {"id": "6.1-e3", "m": "6.1", "c": 6, "k": "equation", "f": "Write the equation: Enzyme reaction scheme", "tex": "E + S \\rightleftharpoons ES \\rightarrow E + P"}, {"id": "6.1-k1", "m": "6.1", "c": 6, "k": "key idea", "f": "Complete the key idea: Water's polarity and hydrogen …", "b": "Water's polarity and hydrogen bonding make it the medium of life"}, {"id": "6.1-k2", "m": "6.1", "c": 6, "k": "key idea", "f": "Complete the key idea: Carbohydrates, lipids, …", "b": "Carbohydrates, lipids, proteins, nucleic acids"}, {"id": "6.1-k3", "m": "6.1", "c": 6, "k": "key idea", "f": "Complete the key idea: Polymers form by …", "b": "Polymers form by condensation and break by hydrolysis"}, {"id": "6.1-k4", "m": "6.1", "c": 6, "k": "key idea", "f": "Complete the key idea: Enzymes lower activation energy; …", "b": "Enzymes lower activation energy; they denature outside their optimum"}, {"id": "6.1-q1", "m": "6.1", "c": 6, "k": "quick check", "f": "Enzymes are mostly", "b": "proteins"}, {"id": "6.1-q2", "m": "6.1", "c": 6, "k": "quick check", "f": "Water dissolves many substances because it is", "b": "polar"}, {"id": "6.1-q3", "m": "6.1", "c": 6, "k": "quick check", "f": "DNA and RNA are", "b": "nucleic acids"}, {"id": "6.1-q4", "m": "6.1", "c": 6, "k": "quick check", "f": "Human enzyme optimum temperature is about", "b": "37 °C"}, {"id": "6.1-p1", "m": "6.1", "c": 6, "k": "problem", "f": "Proteins are polymers of", "b": "amino acids. Twenty kinds of amino acid."}, {"id": "6.1-p2", "m": "6.1", "c": 6, "k": "problem", "f": "Which molecule forms cell membranes?", "b": "phospholipid. Lipids with a water-loving head and water-avoiding tails."}, {"id": "6.1-p3", "m": "6.1", "c": 6, "k": "problem", "f": "Why does an enzyme stop working at high temperature?", "b": "its shape changes and the active site no longer fits. Denaturation."}, {"id": "6.1-p4", "m": "6.1", "c": 6, "k": "problem", "f": "Why does a lake freeze from the top down, protecting fish?", "b": "ice is less dense than water and floats. Hydrogen bonding gives ice an open structure."}, {"id": "6.1-p5", "m": "6.1", "c": 6, "k": "problem", "f": "Using v = Vmax[S]/(Km + [S]), find v when [S] = Km and Vmax = 10 units.", "b": "5 units. v = 10 × Km/(2Km) = 5: half the maximum."}, {"id": "6.1-p6", "m": "6.1", "c": 6, "k": "problem", "f": "Breaking starch into glucose during digestion is", "b": "hydrolysis. Water is used to split the bonds."}, {"id": "6.1-p7", "m": "6.1", "c": 6, "k": "problem", "f": "At very high substrate concentration, enzyme rate levels off because", "b": "all active sites are occupied. Saturation."}, {"id": "6.1-p8", "m": "6.1", "c": 6, "k": "problem", "f": "Explain how an enzyme's specificity follows from its structure.", "b": "An enzyme is a protein chain folded into a precise three-dimensional shape. The active site is a pocket whose shape and pattern of charges match particular substrate molecules. Only substrates that fit and interact correctly can bind and react, so each enzyme catalyses one reaction or a small family of reactions."}, {"id": "6.2-e1", "m": "6.2", "c": 6, "k": "equation", "f": "Write the equation: Surface-to-volume ratio of a cube of side L", "tex": "\\frac{SA}{V} = \\frac{6L^2}{L^3} = \\frac{6}{L}"}, {"id": "6.2-e2", "m": "6.2", "c": 6, "k": "equation", "f": "Write the equation: Magnification", "tex": "M = \\frac{\\mathrm{image\\ size}}{\\mathrm{actual\\ size}}"}, {"id": "6.2-e3", "m": "6.2", "c": 6, "k": "equation", "f": "Write the equation: Fick's law (diffusion rate)", "tex": "\\mathrm{rate} \\propto \\frac{A\\,\\Delta c}{d}"}, {"id": "6.2-k1", "m": "6.2", "c": 6, "k": "key idea", "f": "Complete the key idea: All living things are …", "b": "All living things are made of cells; cells come from cells"}, {"id": "6.2-k2", "m": "6.2", "c": 6, "k": "key idea", "f": "Complete the key idea: Prokaryotes: no nucleus. …", "b": "Prokaryotes: no nucleus. Eukaryotes: nucleus and organelles"}, {"id": "6.2-k3", "m": "6.2", "c": 6, "k": "key idea", "f": "Complete the key idea: Diffusion and osmosis are …", "b": "Diffusion and osmosis are passive; active transport uses energy"}, {"id": "6.2-k4", "m": "6.2", "c": 6, "k": "key idea", "f": "Complete the key idea: Surface-to-volume ratio …", "b": "Surface-to-volume ratio limits cell size"}, {"id": "6.2-q1", "m": "6.2", "c": 6, "k": "quick check", "f": "Cell theory says cells come from", "b": "other cells"}, {"id": "6.2-q2", "m": "6.2", "c": 6, "k": "quick check", "f": "Plant cells have, but animal cells lack,", "b": "a cell wall"}, {"id": "6.2-q3", "m": "6.2", "c": 6, "k": "quick check", "f": "Osmosis is the movement of", "b": "water"}, {"id": "6.2-q4", "m": "6.2", "c": 6, "k": "quick check", "f": "As a cell grows, its SA:V ratio", "b": "decreases"}, {"id": "6.2-p1", "m": "6.2", "c": 6, "k": "problem", "f": "Which cells lack a nucleus?", "b": "bacteria. Prokaryotes have no nucleus."}, {"id": "6.2-p2", "m": "6.2", "c": 6, "k": "problem", "f": "Where in the cell is aerobic respiration carried out?", "b": "mitochondrion. The powerhouse."}, {"id": "6.2-p3", "m": "6.2", "c": 6, "k": "problem", "f": "A cell 20 μm across appears 8 mm across in a micrograph. What is the magnification?", "b": "400 ×. 8000 ÷ 20 = 400."}, {"id": "6.2-p4", "m": "6.2", "c": 6, "k": "problem", "f": "What is the surface-area-to-volume ratio of a cube-shaped cell with sides 2 μm? (μm⁻¹)", "b": "3. 6/L = 6/2 = 3 μm⁻¹."}, {"id": "6.2-p5", "m": "6.2", "c": 6, "k": "problem", "f": "And for sides of 10 μm?", "b": "0.6. 6/10 = 0.6 μm⁻¹: five times smaller."}, {"id": "6.2-p6", "m": "6.2", "c": 6, "k": "problem", "f": "A red blood cell is placed in pure water. What happens?", "b": "water enters by osmosis and it swells, possibly bursting. Water moves towards the higher solute concentration inside the cell."}, {"id": "6.2-p7", "m": "6.2", "c": 6, "k": "problem", "f": "Which process needs energy from the cell?", "b": "active transport. Moving substances against a gradient."}, {"id": "6.2-p8", "m": "6.2", "c": 6, "k": "problem", "f": "What evidence suggests mitochondria were once free-living bacteria?", "b": "Mitochondria have their own circular DNA, like bacteria; they have their own bacteria-like ribosomes; they divide by splitting, as bacteria do; and they are surrounded by a double membrane, consistent with being engulfed. Gene sequences show their closest relatives are a group of bacteria."}, {"id": "6.3-e1", "m": "6.3", "c": 6, "k": "equation", "f": "Write the equation: ATP hydrolysis", "tex": "\\mathrm{ATP} + \\mathrm{H_2O} \\rightarrow \\mathrm{ADP} + \\mathrm{P_i} + \\mathrm{energy}"}, {"id": "6.3-e2", "m": "6.3", "c": 6, "k": "equation", "f": "Write the equation: Photosynthesis", "tex": "6\\mathrm{CO_2} + 6\\mathrm{H_2O} \\rightarrow \\mathrm{C_6H_{12}O_6} + 6\\mathrm{O_2}"}, {"id": "6.3-e3", "m": "6.3", "c": 6, "k": "equation", "f": "Write the equation: Aerobic respiration", "tex": "\\mathrm{C_6H_{12}O_6} + 6\\mathrm{O_2} \\rightarrow 6\\mathrm{CO_2} + 6\\mathrm{H_2O}\\ (\\approx 30\\ \\mathrm{ATP})"}, {"id": "6.3-e4", "m": "6.3", "c": 6, "k": "equation", "f": "Write the equation: Fermentation in yeast", "tex": "\\mathrm{C_6H_{12}O_6} \\rightarrow 2\\mathrm{C_2H_5OH} + 2\\mathrm{CO_2}"}, {"id": "6.3-k1", "m": "6.3", "c": 6, "k": "key idea", "f": "Complete the key idea: ATP is the energy currency: …", "b": "ATP is the energy currency: ATP → ADP + P releases energy"}, {"id": "6.3-k2", "m": "6.3", "c": 6, "k": "key idea", "f": "Complete the key idea: Photosynthesis: CO₂ + H₂O …", "b": "Photosynthesis: CO₂ + H₂O + light → glucose + O₂"}, {"id": "6.3-k3", "m": "6.3", "c": 6, "k": "key idea", "f": "Complete the key idea: Respiration: glucose + O₂ → …", "b": "Respiration: glucose + O₂ → CO₂ + H₂O + about 30 ATP"}, {"id": "6.3-k4", "m": "6.3", "c": 6, "k": "key idea", "f": "Complete the key idea: Anaerobic: only 2 ATP; …", "b": "Anaerobic: only 2 ATP; lactate in muscle, ethanol in yeast"}, {"id": "6.3-q1", "m": "6.3", "c": 6, "k": "quick check", "f": "Photosynthesis takes place in", "b": "chloroplasts"}, {"id": "6.3-q2", "m": "6.3", "c": 6, "k": "quick check", "f": "Respiration releases", "b": "carbon dioxide"}, {"id": "6.3-q3", "m": "6.3", "c": 6, "k": "quick check", "f": "Yeast fermentation produces", "b": "ethanol and CO₂"}, {"id": "6.3-q4", "m": "6.3", "c": 6, "k": "quick check", "f": "ATP → ADP releases", "b": "energy"}, {"id": "6.3-p1", "m": "6.3", "c": 6, "k": "problem", "f": "Which gas is released by photosynthesis?", "b": "oxygen. Water is split, releasing O₂."}, {"id": "6.3-p2", "m": "6.3", "c": 6, "k": "problem", "f": "What is the cell's main energy currency?", "b": "ATP. Adenosine triphosphate."}, {"id": "6.3-p3", "m": "6.3", "c": 6, "k": "problem", "f": "How many molecules of O₂ are needed to respire one molecule of glucose?", "b": "6. From the balanced equation."}, {"id": "6.3-p4", "m": "6.3", "c": 6, "k": "problem", "f": "Glucose has M = 180 g/mol. How many moles of CO₂ are produced when 90 g of glucose is fully respired?", "b": "3 mol. × 6 = 3 mol CO₂."}, {"id": "6.3-p5", "m": "6.3", "c": 6, "k": "problem", "f": "Aerobic respiration gives about 30 ATP per glucose; anaerobic gives 2. How many times more ATP does aerobic give?", "b": "15 ×. 30 ÷ 2."}, {"id": "6.3-p6", "m": "6.3", "c": 6, "k": "problem", "f": "During a sprint, muscle cells short of oxygen produce", "b": "lactate. Anaerobic respiration in animals."}, {"id": "6.3-p7", "m": "6.3", "c": 6, "k": "problem", "f": "Why do leaves look green?", "b": "chlorophyll reflects green light while absorbing red and blue. Green is the colour least absorbed."}, {"id": "6.3-p8", "m": "6.3", "c": 6, "k": "problem", "f": "Explain why oxygen is essential for producing most of a cell's ATP.", "b": "In aerobic respiration, electrons from glucose pass along the electron transport chain in the mitochondria, releasing energy used to make most of the ATP. Oxygen is the final electron acceptor at the end of the chain, combining with electrons and hydrogen to form water. Without oxygen the chain backs up and stops, leaving only the 2 ATP from glycolysis."}, {"id": "6.4-e1", "m": "6.4", "c": 6, "k": "equation", "f": "Write the equation: Chargaff's rule (from base pairing)", "tex": "[A] = [T],\\qquad [G] = [C]"}, {"id": "6.4-e2", "m": "6.4", "c": 6, "k": "equation", "f": "Write the equation: Central dogma", "tex": "\\mathrm{DNA} \\rightarrow \\mathrm{RNA} \\rightarrow \\mathrm{protein}"}, {"id": "6.4-e3", "m": "6.4", "c": 6, "k": "equation", "f": "Write the equation: Number of codons", "tex": "4^3 = 64"}, {"id": "6.4-k1", "m": "6.4", "c": 6, "k": "key idea", "f": "Complete the key idea: DNA: double helix, …", "b": "DNA: double helix, A–T and G–C pairing"}, {"id": "6.4-k2", "m": "6.4", "c": 6, "k": "key idea", "f": "Complete the key idea: Replication is …", "b": "Replication is semi-conservative"}, {"id": "6.4-k3", "m": "6.4", "c": 6, "k": "key idea", "f": "Complete the key idea: DNA → mRNA …", "b": "DNA → mRNA (transcription) → protein (translation)"}, {"id": "6.4-k4", "m": "6.4", "c": 6, "k": "key idea", "f": "Complete the key idea: Codons are triplets; the …", "b": "Codons are triplets; the code is universal and redundant"}, {"id": "6.4-q1", "m": "6.4", "c": 6, "k": "quick check", "f": "A codon is", "b": "three bases"}, {"id": "6.4-q2", "m": "6.4", "c": 6, "k": "quick check", "f": "Translation happens at", "b": "ribosomes"}, {"id": "6.4-q3", "m": "6.4", "c": 6, "k": "quick check", "f": "RNA uses which base instead of thymine?", "b": "uracil"}, {"id": "6.4-q4", "m": "6.4", "c": 6, "k": "quick check", "f": "Whose X-ray images were crucial to the DNA structure?", "b": "Rosalind Franklin"}, {"id": "6.4-p1", "m": "6.4", "c": 6, "k": "problem", "f": "Which base pairs with guanine in DNA?", "b": "cytosine. G–C."}, {"id": "6.4-p2", "m": "6.4", "c": 6, "k": "problem", "f": "Write the complementary strand to 5′-ATGCCT-3′ (reading the partner 3′ to 5′).", "b": "TACGGA. A→T, T→A, G→C, C→G."}, {"id": "6.4-p3", "m": "6.4", "c": 6, "k": "problem", "f": "A DNA sample is 30% adenine. What percentage is guanine?", "b": "20 %. G + C = 40%, G = 20%."}, {"id": "6.4-p4", "m": "6.4", "c": 6, "k": "problem", "f": "How many amino acids are coded by an mRNA sequence of 300 bases (ignoring stop codons)?", "b": "100. 3 bases per codon: 300 ÷ 3."}, {"id": "6.4-p5", "m": "6.4", "c": 6, "k": "problem", "f": "In transcription, thymine in DNA is matched in RNA by", "b": "adenine. The RNA base opposite a DNA T is A. (RNA uses U in place of T, opposite DNA's A.)"}, {"id": "6.4-p6", "m": "6.4", "c": 6, "k": "problem", "f": "Why can a mutation have no effect on the protein?", "b": "the new codon may code for the same amino acid. The code is redundant."}, {"id": "6.4-p7", "m": "6.4", "c": 6, "k": "problem", "f": "Semi-conservative replication means each new DNA molecule has", "b": "one old and one new strand. Confirmed by Meselson and Stahl in 1958."}, {"id": "6.4-p8", "m": "6.4", "c": 6, "k": "problem", "f": "Why is the near-universal genetic code evidence for common ancestry?", "b": "The assignment of codons to amino acids is largely arbitrary chemically; many other codes would work. Yet bacteria, plants, fungi and animals almost all use the same one. The simplest explanation is that all life inherited it from a common ancestor, just as shared quirks in languages point to a common origin."}, {"id": "6.5-e1", "m": "6.5", "c": 6, "k": "equation", "f": "Write the equation: Monohybrid cross ratios", "tex": "Aa \\times Aa:\\ \\ 1\\,AA : 2\\,Aa : 1\\,aa"}, {"id": "6.5-e2", "m": "6.5", "c": 6, "k": "equation", "f": "Write the equation: Chromosome combinations from independent assortment", "tex": "2^{23} \\approx 8.4 \\times 10^6"}, {"id": "6.5-e3", "m": "6.5", "c": 6, "k": "equation", "f": "Write the equation: Hardy–Weinberg (allele frequencies p, q)", "tex": "p^2 + 2pq + q^2 = 1"}, {"id": "6.5-k1", "m": "6.5", "c": 6, "k": "key idea", "f": "Complete the key idea: Genotype: alleles you …", "b": "Genotype: alleles you carry. Phenotype: the trait shown"}, {"id": "6.5-k2", "m": "6.5", "c": 6, "k": "key idea", "f": "Complete the key idea: Aa × Aa …", "b": "Aa × Aa gives 3:1 dominant:recessive phenotypes"}, {"id": "6.5-k3", "m": "6.5", "c": 6, "k": "key idea", "f": "Complete the key idea: X-linked recessive traits …", "b": "X-linked recessive traits are more common in males"}, {"id": "6.5-k4", "m": "6.5", "c": 6, "k": "key idea", "f": "Complete the key idea: Meiosis halves chromosome …", "b": "Meiosis halves chromosome number and creates variation"}, {"id": "6.5-q1", "m": "6.5", "c": 6, "k": "quick check", "f": "An organism with two different alleles is", "b": "heterozygous"}, {"id": "6.5-q2", "m": "6.5", "c": 6, "k": "quick check", "f": "Aa × Aa gives a phenotype ratio of", "b": "3:1"}, {"id": "6.5-q3", "m": "6.5", "c": 6, "k": "quick check", "f": "Meiosis produces cells with", "b": "half the chromosomes"}, {"id": "6.5-q4", "m": "6.5", "c": 6, "k": "quick check", "f": "X-linked recessive traits are commoner in", "b": "males"}, {"id": "6.5-p1", "m": "6.5", "c": 6, "k": "problem", "f": "Two Aa parents. What fraction of offspring are expected to be aa? Give a decimal.", "b": "0.25. One square in four."}, {"id": "6.5-p2", "m": "6.5", "c": 6, "k": "problem", "f": "AA × aa. What fraction of offspring are heterozygous? Give a decimal.", "b": "1. Every offspring gets A from one parent and a from the other."}, {"id": "6.5-p3", "m": "6.5", "c": 6, "k": "problem", "f": "Aa × aa. What fraction show the dominant phenotype? Give a decimal.", "b": "0.5. Offspring: Aa, Aa, aa, aa."}, {"id": "6.5-p4", "m": "6.5", "c": 6, "k": "problem", "f": "Two carriers of cystic fibrosis (recessive) have three children. What is the probability none are affected? Give a decimal.", "b": "0.4219. (3/4)³ ≈ 0.42."}, {"id": "6.5-p5", "m": "6.5", "c": 6, "k": "problem", "f": "A woman who is a carrier of colour blindness (XᴮXᵇ) has children with a man with normal vision. What fraction of their sons are expected to be colour blind?", "b": "1/2. Sons get Y from father and one X from mother: half get Xᵇ."}, {"id": "6.5-p6", "m": "6.5", "c": 6, "k": "problem", "f": "A recessive allele has frequency q = 0.1. Using Hardy–Weinberg, what fraction of the population is homozygous recessive? Give a decimal.", "b": "0.01. q² = 0.01."}, {"id": "6.5-p8", "m": "6.5", "c": 6, "k": "problem", "f": "Why do siblings with the same parents look different?", "b": "Each parent's sex cells are made by meiosis. Independent assortment of 23 chromosome pairs gives over 8 million combinations, and crossing over shuffles alleles within chromosomes. Each child comes from a different egg and sperm, so siblings (except identical twins) inherit different combinations of their parents' alleles."}, {"id": "6.6-e1", "m": "6.6", "c": 6, "k": "equation", "f": "Write the equation: Allele frequency change under selection", "tex": "p' = \\frac{p(1 + s)}{p(1 + s) + (1 - p)}"}, {"id": "6.6-e2", "m": "6.6", "c": 6, "k": "equation", "f": "Write the equation: Relative fitness", "tex": "w = \\frac{\\mathrm{offspring\\ of\\ a\\ type}}{\\mathrm{offspring\\ of\\ the\\ best\\ type}}"}, {"id": "6.6-k1", "m": "6.6", "c": 6, "k": "key idea", "f": "Complete the key idea: Natural selection needs …", "b": "Natural selection needs variation, inheritance and differential reproduction"}, {"id": "6.6-k2", "m": "6.6", "c": 6, "k": "key idea", "f": "Complete the key idea: Evolution = change in …", "b": "Evolution = change in allele frequencies in a population"}, {"id": "6.6-k3", "m": "6.6", "c": 6, "k": "key idea", "f": "Complete the key idea: Evidence: fossils, …", "b": "Evidence: fossils, anatomy, DNA, observed change"}, {"id": "6.6-k4", "m": "6.6", "c": 6, "k": "key idea", "f": "Complete the key idea: Drift is …", "b": "Drift is chance; speciation follows separation"}, {"id": "6.6-q1", "m": "6.6", "c": 6, "k": "quick check", "f": "Evolution happens to", "b": "populations"}, {"id": "6.6-q2", "m": "6.6", "c": 6, "k": "quick check", "f": "Darwin and Wallace published in", "b": "1858"}, {"id": "6.6-q3", "m": "6.6", "c": 6, "k": "quick check", "f": "Fitness in biology means", "b": "reproductive success"}, {"id": "6.6-q4", "m": "6.6", "c": 6, "k": "quick check", "f": "A scientific 'theory' is", "b": "a well-tested explanation"}, {"id": "6.6-p1", "m": "6.6", "c": 6, "k": "problem", "f": "Which three things are needed for natural selection?", "b": "variation, inheritance, differential reproduction. Darwin's core logic."}, {"id": "6.6-p2", "m": "6.6", "c": 6, "k": "problem", "f": "Antibiotic resistance in bacteria is an example of", "b": "natural selection. Resistant variants survive and reproduce."}, {"id": "6.6-p3", "m": "6.6", "c": 6, "k": "problem", "f": "An allele has frequency 0.5 and a 10% advantage (s = 0.1). Using p′ = p(1+s)/[p(1+s) + (1 − p)], what is its frequency next generation?", "b": "0.5238. 0.55 ÷ (0.55 + 0.5) ≈ 0.524."}, {"id": "6.6-p4", "m": "6.6", "c": 6, "k": "problem", "f": "A human arm, a bat's wing and a whale's flipper share the same bone pattern. These are", "b": "homologous structures. Same structure from a common ancestor."}, {"id": "6.6-p5", "m": "6.6", "c": 6, "k": "problem", "f": "Genetic drift has the biggest effect in", "b": "small populations. Chance fluctuations matter more when numbers are small."}, {"id": "6.6-p6", "m": "6.6", "c": 6, "k": "problem", "f": "A giraffe stretching its neck to reach leaves will", "b": "not change its offspring's neck length. Acquired characteristics are not inherited."}, {"id": "6.6-p7", "m": "6.6", "c": 6, "k": "problem", "f": "What usually starts the formation of a new species?", "b": "separation of populations so they diverge. Isolation then divergence."}, {"id": "6.6-p8", "m": "6.6", "c": 6, "k": "problem", "f": "Explain why finishing a course of antibiotics matters, using natural selection.", "b": "A bacterial population varies in susceptibility. Antibiotics kill the most susceptible first. Stopping early leaves the hardiest survivors, which multiply and pass on their resistance genes, so the next infection is harder to treat. A full course aims to kill the whole population before resistant variants take over."}, {"id": "6.7-e1", "m": "6.7", "c": 6, "k": "equation", "f": "Write the equation: Cardiac output", "tex": "\\mathrm{CO} = \\mathrm{HR} \\times \\mathrm{SV}"}, {"id": "6.7-e2", "m": "6.7", "c": 6, "k": "equation", "f": "Write the equation: Body mass index (a population screening tool)", "tex": "\\mathrm{BMI} = \\frac{m\\,(\\mathrm{kg})}{h^2\\,(\\mathrm{m^2})}"}, {"id": "6.7-k1", "m": "6.7", "c": 6, "k": "key idea", "f": "Complete the key idea: Cells → tissues …", "b": "Cells → tissues → organs → systems"}, {"id": "6.7-k2", "m": "6.7", "c": 6, "k": "key idea", "f": "Complete the key idea: Heart: double pump. Lungs: …", "b": "Heart: double pump. Lungs: alveoli give huge surface area"}, {"id": "6.7-k3", "m": "6.7", "c": 6, "k": "key idea", "f": "Complete the key idea: Nerves: fast, electrical. …", "b": "Nerves: fast, electrical. Hormones: slower, in the blood"}, {"id": "6.7-k4", "m": "6.7", "c": 6, "k": "key idea", "f": "Complete the key idea: Homeostasis by negative …", "b": "Homeostasis by negative feedback, e.g. insulin and glucagon"}, {"id": "6.7-q1", "m": "6.7", "c": 6, "k": "quick check", "f": "The organ that releases insulin is the", "b": "pancreas"}, {"id": "6.7-q2", "m": "6.7", "c": 6, "k": "quick check", "f": "Homeostasis mostly uses", "b": "negative feedback"}, {"id": "6.7-q3", "m": "6.7", "c": 6, "k": "quick check", "f": "Alveoli are adapted by having", "b": "a large surface area"}, {"id": "6.7-q4", "m": "6.7", "c": 6, "k": "quick check", "f": "The heart is best described as", "b": "a double pump"}, {"id": "6.7-p1", "m": "6.7", "c": 6, "k": "problem", "f": "A resting heart beats 70 times a minute with a stroke volume of 70 mL. What is the cardiac output in litres per minute?", "b": "4.9 L/min. 70 × 70 = 4900 mL/min."}, {"id": "6.7-p2", "m": "6.7", "c": 6, "k": "problem", "f": "Where in the lungs does gas exchange occur?", "b": "alveoli. Thin-walled air sacs."}, {"id": "6.7-p3", "m": "6.7", "c": 6, "k": "problem", "f": "Which hormone lowers blood glucose?", "b": "insulin. Insulin, from the pancreas."}, {"id": "6.7-p4", "m": "6.7", "c": 6, "k": "problem", "f": "Sweating when hot is an example of", "b": "negative feedback. The response counters the change."}, {"id": "6.7-p5", "m": "6.7", "c": 6, "k": "problem", "f": "During exercise, heart rate rises to 150 beats/min and stroke volume to 110 mL. What is cardiac output, in L/min?", "b": "16.5 L/min. 150 × 110 = 16 500 mL/min."}, {"id": "6.7-p6", "m": "6.7", "c": 6, "k": "problem", "f": "A nerve impulse travels at 80 m/s. How long does it take to travel 1.6 m from toe to brain, in milliseconds?", "b": "20 ms. t = 1.6/80 = 0.02 s."}, {"id": "6.7-p7", "m": "6.7", "c": 6, "k": "problem", "f": "Compared with nervous signals, hormonal signals are generally", "b": "slower and longer-lasting. They travel in the blood."}, {"id": "6.7-p8", "m": "6.7", "c": 6, "k": "problem", "f": "Explain how the body corrects a fall in core temperature.", "b": "Temperature receptors detect the drop and the hypothalamus triggers responses: blood vessels in the skin narrow (vasoconstriction) so less heat is lost; muscles shiver, releasing heat from respiration; hair erects slightly. As temperature returns to normal, the responses switch off: negative feedback."}, {"id": "6.8-e1", "m": "6.8", "c": 6, "k": "equation", "f": "Write the equation: Bacterial growth", "tex": "N = N_0 \\times 2^{t/t_d}"}, {"id": "6.8-e2", "m": "6.8", "c": 6, "k": "equation", "f": "Write the equation: Herd immunity threshold", "tex": "H = 1 - \\frac{1}{R_0}"}, {"id": "6.8-e3", "m": "6.8", "c": 6, "k": "equation", "f": "Write the equation: Effective reproduction number", "tex": "R_{\\mathrm{eff}} = R_0 \\times (\\mathrm{fraction\\ susceptible})"}, {"id": "6.8-k1", "m": "6.8", "c": 6, "k": "key idea", "f": "Complete the key idea: Bacteria are cells; …", "b": "Bacteria are cells; viruses need host cells"}, {"id": "6.8-k2", "m": "6.8", "c": 6, "k": "key idea", "f": "Complete the key idea: Innate immunity: fast, general. …", "b": "Innate immunity: fast, general. Adaptive: slow, specific, with memory"}, {"id": "6.8-k3", "m": "6.8", "c": 6, "k": "key idea", "f": "Complete the key idea: Vaccines train immune …", "b": "Vaccines train immune memory without the disease"}, {"id": "6.8-k4", "m": "6.8", "c": 6, "k": "key idea", "f": "Complete the key idea: Herd immunity threshold = 1 …", "b": "Herd immunity threshold = 1 − 1/R₀; antibiotics don't work on viruses"}, {"id": "6.8-q1", "m": "6.8", "c": 6, "k": "quick check", "f": "Viruses reproduce", "b": "only inside host cells"}, {"id": "6.8-q2", "m": "6.8", "c": 6, "k": "quick check", "f": "Immune memory means the second response is", "b": "faster and stronger"}, {"id": "6.8-q3", "m": "6.8", "c": 6, "k": "quick check", "f": "If R_eff < 1, an epidemic", "b": "declines"}, {"id": "6.8-q4", "m": "6.8", "c": 6, "k": "quick check", "f": "Germ theory was established by", "b": "Pasteur and Koch"}, {"id": "6.8-p1", "m": "6.8", "c": 6, "k": "problem", "f": "A bacterium divides every 20 minutes. Starting from one cell, how many are there after 2 hours?", "b": "64. 2⁶ = 64."}, {"id": "6.8-p2", "m": "6.8", "c": 6, "k": "problem", "f": "Antibiotics are effective against", "b": "bacteria. They target bacterial structures."}, {"id": "6.8-p3", "m": "6.8", "c": 6, "k": "problem", "f": "Measles has R₀ ≈ 15. What is the herd immunity threshold, as a percentage?", "b": "93.33 %. About 93%."}, {"id": "6.8-p4", "m": "6.8", "c": 6, "k": "problem", "f": "A disease has R₀ = 3. What percentage must be immune for herd immunity?", "b": "66.67 %. 1 − 1/3 ≈ 67%."}, {"id": "6.8-p5", "m": "6.8", "c": 6, "k": "problem", "f": "With R₀ = 4 and 60% of people immune, what is R_eff?", "b": "1.6. 4 × 0.4 = 1.6: still spreading."}, {"id": "6.8-p6", "m": "6.8", "c": 6, "k": "problem", "f": "Vaccines work by", "b": "creating immune memory without causing the disease. They train the adaptive immune system."}, {"id": "6.8-p7", "m": "6.8", "c": 6, "k": "problem", "f": "Antibodies are made by", "b": "B cells. B lymphocytes."}, {"id": "6.8-p8", "m": "6.8", "c": 6, "k": "problem", "f": "Why can a person who is not vaccinated still be protected by others' vaccination?", "b": "If enough of the population is immune, each infected person meets too few susceptible people to pass the infection on to more than one other on average (R_eff below 1). Chains of transmission die out before reaching the unvaccinated, who are shielded indirectly. This is herd immunity."}, {"id": "6.9-e1", "m": "6.9", "c": 6, "k": "equation", "f": "Write the equation: Ecological efficiency", "tex": "E_{n+1} \\approx 0.1\\,E_n"}, {"id": "6.9-e2", "m": "6.9", "c": 6, "k": "equation", "f": "Write the equation: Logistic growth", "tex": "\\frac{dN}{dt} = rN\\left(1 - \\frac{N}{K}\\right)"}, {"id": "6.9-e3", "m": "6.9", "c": 6, "k": "equation", "f": "Write the equation: Exponential growth", "tex": "N = N_0 e^{rt}"}, {"id": "6.9-k1", "m": "6.9", "c": 6, "k": "key idea", "f": "Complete the key idea: About 10% of energy …", "b": "About 10% of energy passes up each trophic level"}, {"id": "6.9-k2", "m": "6.9", "c": 6, "k": "key idea", "f": "Complete the key idea: Energy flows; …", "b": "Energy flows; matter cycles"}, {"id": "6.9-k3", "m": "6.9", "c": 6, "k": "key idea", "f": "Complete the key idea: Logistic growth levels …", "b": "Logistic growth levels off at carrying capacity K"}, {"id": "6.9-k4", "m": "6.9", "c": 6, "k": "key idea", "f": "Complete the key idea: Human activity is reshaping …", "b": "Human activity is reshaping the carbon cycle and biodiversity"}, {"id": "6.9-q1", "m": "6.9", "c": 6, "k": "quick check", "f": "Energy in ecosystems", "b": "flows one way"}, {"id": "6.9-q2", "m": "6.9", "c": 6, "k": "quick check", "f": "Carrying capacity is", "b": "the maximum sustainable population"}, {"id": "6.9-q3", "m": "6.9", "c": 6, "k": "quick check", "f": "Decomposers", "b": "break down dead matter"}, {"id": "6.9-q4", "m": "6.9", "c": 6, "k": "quick check", "f": "Pre-industrial CO₂ was about", "b": "280 ppm"}, {"id": "6.9-p1", "m": "6.9", "c": 6, "k": "problem", "f": "Producers in an ecosystem capture 20 000 kJ. About how much energy reaches the carnivores that eat herbivores?", "b": "200 kJ. Two steps at 10%: 20 000 → 2000 → 200."}, {"id": "6.9-p2", "m": "6.9", "c": 6, "k": "problem", "f": "Which process removes CO₂ from the atmosphere?", "b": "photosynthesis. Plants fix carbon."}, {"id": "6.9-p3", "m": "6.9", "c": 6, "k": "problem", "f": "Why are there fewer top predators than herbivores?", "b": "energy is lost at each trophic level. Only about 10% passes up each level."}, {"id": "6.9-p4", "m": "6.9", "c": 6, "k": "problem", "f": "In the logistic model, what is dN/dt when N = K/2, r = 0.4 per year and K = 1000?", "b": "100 per year. = 100 per year (the fastest growth)."}, {"id": "6.9-p5", "m": "6.9", "c": 6, "k": "problem", "f": "And what is dN/dt when N = K?", "b": "0 per year. 1 − N/K = 0, so growth stops."}, {"id": "6.9-p6", "m": "6.9", "c": 6, "k": "problem", "f": "Atmospheric CO₂ rose from 280 ppm to 420 ppm. What percentage increase is that?", "b": "50 %. (420 − 280)/280 = 0.5."}, {"id": "6.9-p7", "m": "6.9", "c": 6, "k": "problem", "f": "In predator–prey cycles, predator population peaks typically", "b": "follow prey peaks. Predators respond to food supply with a lag."}, {"id": "6.9-p8", "m": "6.9", "c": 6, "k": "problem", "f": "Explain why eating lower on the food chain can feed more people from the same land.", "b": "Only about 10% of the energy in plants ends up in the animals that eat them. Feeding crops directly to people uses that energy at the first step, while feeding them to livestock loses about 90% before it reaches people as meat. So the same crop area supports roughly ten times as many people eating plants as eating meat from those plants."}, {"id": "P-A1", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make a the subject (Kinematics: final velocity):", "ft": "v = u + at", "tex": "a = \\frac{v-u}{t}"}, {"id": "P-A2", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make x the subject (Straight line):", "ft": "y = mx + c", "tex": "x = \\frac{y-c}{m}"}, {"id": "P-A3", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make w the subject (Perimeter of a rectangle):", "ft": "P = 2l + 2w", "tex": "w = \\frac{P-2l}{2}"}, {"id": "P-A4", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make C the subject (Temperature conversion):", "ft": "F = \\frac{9}{5}C + 32", "tex": "C = \\frac{5(F-32)}{9}"}, {"id": "P-A5", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make u the subject (Distance under uniform acceleration):", "ft": "s = \\frac{(u+v)t}{2}", "tex": "u = \\frac{2s}{t} - v"}, {"id": "P-A6", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make T the subject (Ideal gas law):", "ft": "PV = nRT", "tex": "T = \\frac{PV}{nR}"}, {"id": "P-B1", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make v the subject (Kinetic energy):", "ft": "E = \\frac{1}{2}mv^2", "tex": "v = \\sqrt{\\frac{2E}{m}}"}, {"id": "P-B2", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make g the subject (Simple pendulum):", "ft": "T = 2\\pi\\sqrt{\\frac{L}{g}}", "tex": "g = \\frac{4\\pi^2 L}{T^2}"}, {"id": "P-B3", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make r the subject (Newtonian gravity):", "ft": "F = \\frac{G m_1 m_2}{r^2}", "tex": "r = \\sqrt{\\frac{G m_1 m_2}{F}}"}, {"id": "P-B4", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make r the subject (Area of a circle):", "ft": "A = \\pi r^2", "tex": "r = \\sqrt{\\frac{A}{\\pi}}"}, {"id": "P-B5", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make v the subject (Thin lens equation):", "ft": "\\frac{1}{f} = \\frac{1}{u} + \\frac{1}{v}", "tex": "v = \\frac{uf}{u-f}"}, {"id": "P-B6", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make r the subject (Volume of a sphere):", "ft": "V = \\frac{4}{3}\\pi r^3", "tex": "r = \\sqrt[3]{\\frac{3V}{4\\pi}}"}, {"id": "P-B7", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make M the subject (Kepler's third law (Newton's form)):", "ft": "T^2 = \\frac{4\\pi^2}{GM}a^3", "tex": "M = \\frac{4\\pi^2 a^3}{G T^2}"}, {"id": "P-C1", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make x the subject (Unknown on both sides):", "ft": "ax + b = cx + d", "tex": "x = \\frac{d-b}{a-c}"}, {"id": "P-C2", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make x the subject (Inverting a rational function):", "ft": "y = \\frac{x+2}{x-3}", "tex": "x = \\frac{3y+2}{y-1}"}, {"id": "P-C3", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make R2 the subject (Two resistors in parallel):", "ft": "R = \\frac{R_1 R_2}{R_1 + R_2}", "tex": "R_2 = \\frac{R R_1}{R_1 - R}"}, {"id": "P-C4", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make vs the subject (Doppler effect, moving source):", "ft": "f' = \\frac{f v}{v - v_s}", "tex": "v_s = \\frac{v(f'-f)}{f'}"}, {"id": "P-C5", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make x the subject (Bracketed unknown):", "ft": "a(x - b) = cx", "tex": "x = \\frac{ab}{a-c}"}, {"id": "P-D1", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make t the subject (Radioactive decay):", "ft": "N = N_0 e^{-kt}", "tex": "t = \\frac{\\ln(N_0/N)}{k}"}, {"id": "P-D2", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make H the subject (Acidity):", "ft": "\\mathrm{pH} = -\\log_{10}[\\mathrm{H^+}]", "tex": "[\\mathrm{H^+}] = 10^{-\\mathrm{pH}}"}, {"id": "P-D3", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make t the subject (Compound growth):", "ft": "A = P(1+r)^t", "tex": "t = \\frac{\\ln(A/P)}{\\ln(1+r)}"}, {"id": "P-D4", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make x the subject (General exponential):", "ft": "y = a b^x", "tex": "x = \\frac{\\ln(y/a)}{\\ln b}"}, {"id": "P-D5", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make I the subject (Sound level in decibels):", "ft": "L = 10\\log_{10}\\left(\\frac{I}{I_0}\\right)", "tex": "I = I_0 \\cdot 10^{L/10}"}, {"id": "P-D6", "m": "2.3P", "c": 23, "k": "rearrange", "f": "Make t the subject (Newton's law of cooling):", "ft": "T = T_s + (T_0 - T_s)e^{-kt}", "tex": "t = \\frac{1}{k}\\ln\\left(\\frac{T_0 - T_s}{T - T_s}\\right)"}, {"id": "P-F1", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "You time a pendulum at several lengths L. Which graph gives a straight line through the origin, and what is its gradient?", "b": "T² against L; gradient 4π²/g. Compare with y = m x: y is T squared, x is L, and m is 4 pi squared over g."}, {"id": "P-F2", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "Counts N from a radioactive source are recorded over time t. What should you plot to get a straight line?", "b": "ln N against t; gradient −k, intercept ln N₀. Compare with y = mx + c."}, {"id": "P-F5", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "You suspect y = a xⁿ but do not know n. What plot reveals n?", "b": "log y against log x; gradient n. This is a straight line with y-variable log y, x-variable log x and gradient n. Social scientists will know this as the log–log (elasticity) model."}, {"id": "P-G1", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "A student solves E = ½mv² for v and writes v = √(2E) ÷ m. What went wrong?", "b": "The m should be inside the square root. Dividing by m happens before the root is taken, so m ends up inside the root."}, {"id": "P-G2", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "From 1/f = 1/u + 1/v, a student 'flips everything' and writes f = u + v. Why is this wrong?", "b": "The reciprocal of a sum is not the sum of the reciprocals. You may take the reciprocal of a whole side, never of each term separately. Test with numbers: 1/2 + 1/2 = 1, but 2 + 2 is not 1."}, {"id": "P-G3", "m": "2.3P", "c": 23, "k": "spot the idea", "f": "Solving x² = 9, a student writes x = 3. What is missing?", "b": "The solution x = −3. Squaring destroys sign information, so the square root brings back two candidates. Context decides which to keep: a length must be positive, a displacement need not be."}, {"id": "P-q1", "m": "2.3P", "c": 23, "k": "quiz", "f": "In T = 2π√(L/g), which operation do you undo first when solving for g?", "b": "The multiplication by 2π. 2π was applied last when building T from g, so it is the outermost layer and comes off first."}, {"id": "P-q2", "m": "2.3P", "c": 23, "k": "quiz", "f": "From 1/f = 1/u + 1/v, which is the correct expression for v?", "b": "v = uf/(u − f). 1/v = 1/f − 1/u = (u − f)/uf; only then flip both sides."}, {"id": "P-q3", "m": "2.3P", "c": 23, "k": "quiz", "f": "Make x the subject of ax + b = cx + d.", "b": "x = (d − b)/(a − c). Collect: ax − cx = d − b. Factor: x(a − c) = d − b. Divide."}, {"id": "P-q4", "m": "2.3P", "c": 23, "k": "quiz", "f": "Solve N = N₀e^(−kt) for t.", "b": "t = ln(N₀/N)/k. Divide by N₀, take ln, divide by −k and flip the fraction inside the log."}, {"id": "P-q5", "m": "2.3P", "c": 23, "k": "quiz", "f": "Gravitational force goes as 1/r². If r is halved, the force is multiplied by", "b": "4. (½)⁻² = 4."}, {"id": "P-q6", "m": "2.3P", "c": 23, "k": "quiz", "f": "You measure decay counts N over time t. Which plot gives a straight line?", "b": "ln N against t. ln N = ln N₀ − kt: gradient −k, intercept ln N₀."}, {"id": "P-q7", "m": "2.3P", "c": 23, "k": "quiz", "f": "A student rearranges E = ½mv² to get v = √(2E)/m. Which check exposes the error fastest?", "b": "Units: the right side isn't a speed. √(2E)/m does not have units of m/s; at E = 0 both forms give 0, so that check misses it."}, {"id": "P-q8", "m": "2.3P", "c": 23, "k": "quiz", "f": "Solving x² = 16 for a displacement that could be either direction, the full answer is", "b": "x = ±4. Squaring hides the sign, so both roots are candidates."}];
window.SP_QUIZ = {"1.1": [{"t": "mc", "q": "What is 10⁻³ as a fraction?", "o": ["1/30", "1/1000", "−1000", "1/300"], "c": 1, "w": ""}, {"t": "mc", "q": "(2 × 10³) × (3 × 10⁴) equals", "o": ["6 × 10⁷", "6 × 10¹²", "5 × 10⁷", "6 × 10¹"], "c": 0, "w": ""}, {"t": "mc", "q": "A price falls 50% then rises 50%. It ends at", "o": ["its original value", "125% of the original", "75% of the original", "50% of the original"], "c": 2, "w": "The rise is 50% of a smaller base."}, {"t": "mc", "q": "The prefix 'micro' means", "o": ["10⁻³", "10⁻⁶", "10⁻⁹", "10⁶"], "c": 1, "w": ""}, {"t": "mc", "q": "Support for a policy rises from 40% to 50%. Which statement is correct?", "o": ["It rose by 10%", "It rose by 10 percentage points, or 25%", "It rose by 25 percentage points", "It rose by 50%"], "c": 1, "w": "The difference is 10 percentage points. Relative to the starting 40, that is 10 ÷ 40 = 25%."}, {"t": "mc", "q": "A calculator gives 3.14159265 for a result whose inputs were measured to 3 significant figures. How should you report it?", "o": ["3.14159265", "3.142", "3.14", "3"], "c": 2, "w": "Match the least precise input: 3 significant figures. 3.14."}, {"t": "num", "q": "A jacket priced at $180 is reduced by 35%. What is the sale price?", "a": 117, "unit": "dollars", "tol": 0.02, "w": "35% of 180 is 0.35 × 180 = 63. 180 − 63 = 117. Or directly: 0.65 × 180 = 117."}, {"t": "num", "q": "A town's population grows from 24 000 to 27 600. What is the percentage increase?", "a": 15, "unit": "%", "tol": 0.02, "w": "Change = 3600. 3600 ÷ 24 000 = 0.15, which is 15%."}], "1.2": [{"t": "mc", "q": "The SI base unit of mass is the", "o": ["gram", "kilogram", "newton", "pound"], "c": 1, "w": ""}, {"t": "mc", "q": "1 m³ equals how many cm³?", "o": ["100", "10 000", "1 000 000", "1000"], "c": 2, "w": ""}, {"t": "mc", "q": "Averaging many readings reduces", "o": ["systematic error", "random error", "both equally", "neither"], "c": 1, "w": ""}, {"t": "mc", "q": "Which quantity could be added to a speed?", "o": ["an acceleration", "another speed", "a distance", "a time"], "c": 1, "w": ""}, {"t": "mc", "q": "Which of these equations is dimensionally impossible? (v speed, t time, a acceleration, s distance)", "o": ["s = vt", "v = at", "s = v + at", "v² = 2as"], "c": 2, "w": "Check each term. v has units m/s; at has units m/s; s has units m. s = v + at adds metres to metres-per-second: impossible."}, {"t": "mc", "q": "What are the SI base units of a joule?", "o": ["kg m s⁻¹", "kg m² s⁻²", "kg m s⁻²", "N s"], "c": 1, "w": "Joule = newton × metre. N = kg m s⁻², so J = kg m² s⁻²."}, {"t": "num", "q": "Convert 90 km/h into metres per second.", "a": 25, "unit": "m/s", "tol": 0.02, "w": "Multiply by 1000 m/km and divide by 3600 s/h. 90 000 ÷ 3600 = 25 m/s."}, {"t": "num", "q": "A room is 4.0 m by 3.5 m. What is its floor area in square centimetres?", "a": 140000, "unit": "cm²", "tol": 0.02, "w": "Area = 14 m². 1 m² = 10⁴ cm², so 14 × 10⁴ = 1.4 × 10⁵ cm²."}], "1.3": [{"t": "mc", "q": "A right triangle has legs 6 and 8. The hypotenuse is", "o": ["10", "14", "48", "√28"], "c": 0, "w": ""}, {"t": "mc", "q": "Scale lengths by 3. Volume scales by", "o": ["3", "6", "9", "27"], "c": 3, "w": ""}, {"t": "mc", "q": "The surface area of a sphere is", "o": ["πr²", "2πr", "4πr²", "(4/3)πr³"], "c": 2, "w": ""}, {"t": "mc", "q": "Angles in a triangle add to", "o": ["90°", "180°", "270°", "360°"], "c": 1, "w": ""}, {"t": "mc", "q": "A cube's side length triples. Its surface-area-to-volume ratio", "o": ["triples", "stays the same", "falls to one third", "falls to one ninth"], "c": 2, "w": "Area scales by 9, volume by 27. Ratio scales by 9/27 = 1/3."}, {"t": "num", "q": "A ladder 5.0 m long leans against a wall with its foot 1.4 m from the wall. How high up the wall does it reach?", "a": 4.8, "unit": "m", "tol": 0.02, "w": "The ladder is the hypotenuse: h² + 1.4² = 5.0². h² = 25 − 1.96 = 23.04, so h = 4.8 m."}, {"t": "num", "q": "What is the area of a circle of diameter 10 cm?", "a": 78.53981633974483, "unit": "cm²", "tol": 0.02, "w": "Radius = 5 cm. A = π × 5² ≈ 78.5 cm²."}], "1.4": [{"t": "mc", "q": "tan θ equals", "o": ["opp/hyp", "adj/hyp", "opp/adj", "hyp/opp"], "c": 2, "w": ""}, {"t": "mc", "q": "180° in radians is", "o": ["π/2", "π", "2π", "1"], "c": 1, "w": ""}, {"t": "mc", "q": "A 10 N force at 60° to the horizontal has a horizontal component of", "o": ["5 N", "8.7 N", "10 N", "6 N"], "c": 0, "w": "10 cos 60° = 5 N."}, {"t": "mc", "q": "The period of y = sin(ωt) is", "o": ["ω", "2π/ω", "ω/2π", "πω"], "c": 1, "w": ""}, {"t": "mc", "q": "The wave y = 3 sin(2t) has amplitude and period", "o": ["3 and 2", "3 and π", "2 and 3", "6 and π"], "c": 1, "w": "Amplitude is the coefficient: 3. Period = 2π/ω = 2π/2 = π."}, {"t": "num", "q": "A ramp rises at 12° and is 4.0 m long along its surface. How high does it rise?", "a": 0.8316467632710374, "unit": "m", "tol": 0.02, "w": "Height is opposite the angle; ramp is the hypotenuse. h = 4.0 × sin 12° ≈ 0.83 m."}, {"t": "num", "q": "Convert 45° to radians, as a decimal.", "a": 0.7853981633974483, "unit": "rad", "tol": 0.02, "w": "Multiply by π/180. 45π/180 = π/4 ≈ 0.785 rad."}], "1.5": [{"t": "mc", "q": "For independent events A and B, P(A and B) is", "o": ["P(A) + P(B)", "P(A) × P(B)", "P(A) − P(B)", "P(A)/P(B)"], "c": 1, "w": ""}, {"t": "mc", "q": "About what percentage of a normal distribution lies within 1 SD of the mean?", "o": ["50%", "68%", "95%", "99.7%"], "c": 1, "w": ""}, {"t": "mc", "q": "Taking 100 readings instead of 25 changes the standard error by a factor of", "o": ["1/4", "1/2", "2", "4"], "c": 1, "w": ""}, {"t": "mc", "q": "Physicists' '5-sigma' standard is", "o": ["looser than p = 0.05", "about the same as p = 0.05", "far stricter than p = 0.05", "unrelated to probability"], "c": 2, "w": ""}, {"t": "mc", "q": "Heights are normally distributed with mean 170 cm and SD 10 cm. Roughly what fraction are between 150 cm and 190 cm?", "o": ["68%", "95%", "99.7%", "50%"], "c": 1, "w": "150 and 190 are two SDs either side of the mean. About 95%."}, {"t": "num", "q": "A fair coin is tossed three times. What is the probability of three heads? Give a decimal.", "a": 0.125, "unit": "", "tol": 0.02, "w": "Independent: multiply. ½ × ½ × ½ = 1/8 = 0.125."}, {"t": "num", "q": "Two dice are rolled. What is the probability that the total is 7? Give a decimal.", "a": 0.16666666666666666, "unit": "", "tol": 0.02, "w": "Favourable outcomes: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) = 6. 6 ÷ 36 = 1/6 ≈ 0.167."}], "1.6": [{"t": "mc", "q": "Displacement differs from distance because it", "o": ["is always larger", "includes direction", "is a scalar", "has no units"], "c": 1, "w": ""}, {"t": "mc", "q": "(1, 2) + (3, −1) =", "o": ["(4, 1)", "(3, −2)", "(4, 3)", "(2, 1)"], "c": 0, "w": ""}, {"t": "mc", "q": "The dot product of perpendicular vectors is", "o": ["1", "zero", "maximum", "negative"], "c": 1, "w": ""}, {"t": "mc", "q": "A dot product is a", "o": ["vector", "scalar", "matrix", "angle"], "c": 1, "w": ""}, {"t": "mc", "q": "Which of these is a vector?", "o": ["temperature", "mass", "velocity", "energy"], "c": 2, "w": "Only velocity needs a direction."}, {"t": "num", "q": "Find the magnitude of the vector (6, 8).", "a": 10, "unit": "", "tol": 0.02, "w": "√(6² + 8²) = √100. = 10."}, {"t": "num", "q": "A walker goes 3 km east then 4 km north. What is the size of her displacement?", "a": 5, "unit": "km", "tol": 0.02, "w": "Components (3, 4). √(9 + 16) = 5 km."}], "1.7": [{"t": "mc", "q": "One example that agrees with a general claim", "o": ["proves it", "disproves it", "proves nothing in general", "makes it a theorem"], "c": 2, "w": ""}, {"t": "mc", "q": "√2 is", "o": ["rational", "irrational", "an integer", "a fraction in lowest terms"], "c": 1, "w": ""}, {"t": "mc", "q": "Checking what a formula predicts when a quantity goes to zero is a", "o": ["limiting case", "proof", "axiom", "counter-example"], "c": 0, "w": ""}, {"t": "mc", "q": "Every model", "o": ["is exactly true", "leaves something out", "is a theorem", "avoids assumptions"], "c": 1, "w": ""}, {"t": "mc", "q": "Someone claims 'all prime numbers are odd'. What settles it?", "o": ["Checking primes up to 100", "The counter-example 2", "A survey of mathematicians", "It cannot be settled"], "c": 1, "w": "One counter-example disproves a general claim. 2 is prime and even."}, {"t": "mc", "q": "A model of a falling stone ignores air resistance. For which object does this assumption fail most badly?", "o": ["a steel ball dropped 2 m", "a feather", "a brick dropped 1 m", "a marble"], "c": 1, "w": "Air resistance matters when it is large compared with weight. A feather is light with a large surface."}, {"t": "num", "q": "Use the formula n(n+1)/2 to find 1 + 2 + … + 100.", "a": 5050, "unit": "", "tol": 0.02, "w": "n = 100. 100 × 101 ÷ 2 = 5050."}], "2.1": [{"t": "mc", "q": "3x and 3x² are", "o": ["like terms", "unlike terms", "equal", "factors"], "c": 1, "w": ""}, {"t": "mc", "q": "x⁻² equals", "o": ["−x²", "1/x²", "−2x", "√x"], "c": 1, "w": ""}, {"t": "mc", "q": "x² + 5x + 6 factorises as", "o": ["(x + 1)(x + 6)", "(x + 2)(x + 3)", "(x − 2)(x − 3)", "(x + 5)(x + 1)"], "c": 1, "w": ""}, {"t": "mc", "q": "x^(1/2) means", "o": ["x/2", "√x", "1/x²", "2x"], "c": 1, "w": ""}, {"t": "mc", "q": "Simplify 4x + 3y − x + 2y.", "o": ["3x + 5y", "5x + 5y", "8xy", "3x + y"], "c": 0, "w": "Collect x terms: 4x − x = 3x. Collect y terms: 3y + 2y = 5y."}, {"t": "mc", "q": "Expand 5(2x − 3).", "o": ["10x − 3", "10x − 15", "7x − 8", "10x + 15"], "c": 1, "w": "Multiply each term by 5."}, {"t": "num", "q": "Evaluate 8^(2/3).", "a": 4, "unit": "", "tol": 0.02, "w": "Cube root of 8 is 2. 2² = 4."}, {"t": "num", "q": "If x = 3 and y = −2, evaluate 2x² − 3xy + y².", "a": 40, "unit": "", "tol": 0.02, "w": "2(9) − 3(3)(−2) + (−2)². 18 + 18 + 4 = 40."}], "2.2": [{"t": "mc", "q": "Solve 2x = 18 − x.", "o": ["x = 6", "x = 9", "x = 18", "x = 3"], "c": 0, "w": ""}, {"t": "mc", "q": "Dividing an inequality by −3", "o": ["keeps its direction", "reverses its direction", "is not allowed", "makes it an equation"], "c": 1, "w": ""}, {"t": "mc", "q": "In y = 3x − 5, the intercept is", "o": ["3", "−5", "5", "x"], "c": 1, "w": ""}, {"t": "mc", "q": "A line with gradient 0 is", "o": ["vertical", "horizontal", "diagonal", "undefined"], "c": 1, "w": ""}, {"t": "mc", "q": "Solve 5 − 2x > 11.", "o": ["x > −3", "x < −3", "x > 3", "x < 3"], "c": 1, "w": "−2x > 6. Divide by −2 and flip: x < −3."}, {"t": "mc", "q": "On a graph of distance (m) against time (s), the gradient represents", "o": ["acceleration", "speed", "distance", "time"], "c": 1, "w": "Gradient = change in distance ÷ change in time = speed."}, {"t": "num", "q": "Solve 4x + 7 = 31.", "a": 6, "unit": "", "tol": 0.02, "w": "Subtract 7: 4x = 24. Divide by 4: x = 6."}, {"t": "num", "q": "Solve 3(x − 2) = 15.", "a": 7, "unit": "", "tol": 0.02, "w": "Expand: 3x − 6 = 15. 3x = 21, x = 7."}], "2.3": [{"t": "mc", "q": "To solve T = 2π√(L/g) for g, the first step is", "o": ["square both sides", "divide by 2π", "multiply by g", "subtract 2π"], "c": 1, "w": ""}, {"t": "mc", "q": "If the target appears twice, you should", "o": ["give up", "collect and factor", "square both sides", "flip each term"], "c": 1, "w": ""}, {"t": "mc", "q": "v = √(2E/m). If E is quadrupled, v", "o": ["doubles", "quadruples", "halves", "is unchanged"], "c": 0, "w": ""}, {"t": "mc", "q": "Taking the reciprocal is allowed", "o": ["term by term", "of a whole side only", "never", "only for integers"], "c": 1, "w": ""}, {"t": "mc", "q": "From 1/f = 1/u + 1/v, a student writes f = u + v. The mistake is", "o": ["a sign error", "flipping individual terms", "forgetting to square", "nothing"], "c": 1, "w": "The reciprocal of a sum is not the sum of reciprocals: 1/2 + 1/2 = 1, but 2 + 2 ≠ 1."}, {"t": "num", "q": "A pendulum clock must have a period of 2.00 s where g = 9.81 m/s². How long is the pendulum?", "a": 0.9939608115313336, "unit": "m", "tol": 0.02, "w": "L = gT²/(4π²). = 9.81 × 4 ÷ 39.48 ≈ 0.994 m."}], "2.4": [{"t": "mc", "q": "A function can map one input to", "o": ["several outputs", "exactly one output", "no outputs", "any number"], "c": 1, "w": ""}, {"t": "mc", "q": "y = f(x) + 3 is shifted", "o": ["up 3", "right 3", "left 3", "down 3"], "c": 0, "w": ""}, {"t": "mc", "q": "y = −f(x) is", "o": ["reflected in the y-axis", "reflected in the x-axis", "shifted down", "unchanged"], "c": 1, "w": ""}, {"t": "mc", "q": "The domain of 1/x excludes", "o": ["x = 1", "x = 0", "negative x", "nothing"], "c": 1, "w": ""}, {"t": "mc", "q": "What is the domain of f(x) = √(x − 5)?", "o": ["all real x", "x ≥ 5", "x ≥ 0", "x > 5 only"], "c": 1, "w": "The quantity under the root must be ≥ 0: x − 5 ≥ 0."}, {"t": "mc", "q": "The graph of y = (x + 3)² is the graph of y = x² shifted", "o": ["3 right", "3 left", "3 up", "3 down"], "c": 1, "w": "x − h with h = −3: shift left by 3."}, {"t": "num", "q": "If f(x) = 3x² − 2, find f(4).", "a": 46, "unit": "", "tol": 0.02, "w": "3 × 16 − 2. = 46."}, {"t": "num", "q": "If f(x) = 2x + 1 and g(x) = x², find f(g(3)).", "a": 19, "unit": "", "tol": 0.02, "w": "g(3) = 9. f(9) = 19."}], "2.5": [{"t": "mc", "q": "Elimination works by", "o": ["squaring", "cancelling one variable", "graphing only", "guessing"], "c": 1, "w": ""}, {"t": "mc", "q": "Parallel lines give", "o": ["one solution", "no solution", "two solutions", "infinitely many"], "c": 1, "w": ""}, {"t": "mc", "q": "Three unknowns generally need", "o": ["one equation", "two equations", "three equations", "four equations"], "c": 2, "w": ""}, {"t": "mc", "q": "Solve x = 2y and x + y = 9: y =", "o": ["3", "6", "4.5", "2"], "c": 0, "w": ""}, {"t": "mc", "q": "Solve x + y = 10 and x − y = 4.", "o": ["x = 7, y = 3", "x = 6, y = 4", "x = 3, y = 7", "x = 5, y = 5"], "c": 0, "w": "Add: 2x = 14, x = 7. y = 3."}, {"t": "mc", "q": "The system y = 2x + 1 and y = 2x − 3 has", "o": ["one solution", "no solution", "infinitely many", "two solutions"], "c": 1, "w": "Same gradient, different intercepts: parallel lines."}, {"t": "num", "q": "Solve 3x + 2y = 16 and x − y = 2. What is x?", "a": 4, "unit": "", "tol": 0.02, "w": "From the second, x = y + 2. 3(y + 2) + 2y = 16 → 5y = 10 → y = 2, x = 4."}, {"t": "num", "q": "Solve 2x + 5y = 19 and 3x − 2y = 0. What is y?", "a": 3, "unit": "", "tol": 0.02, "w": "Multiply first by 3, second by 2: 6x + 15y = 57, 6x − 4y = 0. Subtract: 19y = 57, y = 3."}], "2.6": [{"t": "mc", "q": "If b² − 4ac < 0, the quadratic has", "o": ["two real roots", "one root", "no real roots", "infinitely many"], "c": 2, "w": ""}, {"t": "mc", "q": "A cubic has at most how many real roots?", "o": ["1", "2", "3", "4"], "c": 2, "w": ""}, {"t": "mc", "q": "The vertex of y = ax² + bx + c is at x =", "o": ["b/2a", "−b/2a", "−c/a", "b²/4a"], "c": 1, "w": ""}, {"t": "mc", "q": "x² − 4 = 0 has roots", "o": ["2 only", "±2", "4", "±4"], "c": 1, "w": ""}, {"t": "mc", "q": "Solve x² − 9x + 20 = 0.", "o": ["4 and 5", "−4 and −5", "2 and 10", "1 and 20"], "c": 0, "w": "Factorise: (x − 4)(x − 5) = 0."}, {"t": "mc", "q": "p(x) = x³ − 6x² + 11x − 6 and p(1) = 0. Which is a factor?", "o": ["x + 1", "x − 1", "x − 6", "x + 6"], "c": 1, "w": "Factor theorem: p(1) = 0 means (x − 1) is a factor."}, {"t": "num", "q": "Use the quadratic formula to find the larger root of 2x² − 3x − 5 = 0.", "a": 2.5, "unit": "", "tol": 0.02, "w": "Δ = 9 + 40 = 49. x = (3 ± 7)/4: 2.5 or −1."}, {"t": "num", "q": "Find the discriminant of 3x² + 4x + 2.", "a": -8, "unit": "", "tol": 0.02, "w": "b² − 4ac = 16 − 24. = −8, so no real roots."}], "2.7": [{"t": "mc", "q": "log(ab) equals", "o": ["log a × log b", "log a + log b", "a log b", "log a − log b"], "c": 1, "w": ""}, {"t": "mc", "q": "After 2 half-lives, the fraction remaining is", "o": ["½", "¼", "⅛", "0"], "c": 1, "w": ""}, {"t": "mc", "q": "ln is the logarithm to base", "o": ["10", "2", "e", "1"], "c": 2, "w": ""}, {"t": "mc", "q": "On a log scale, an increase of 2 means", "o": ["×2", "×20", "×100", "+2"], "c": 2, "w": ""}, {"t": "mc", "q": "Simplify ln(e⁵) + log₁₀(100).", "o": ["7", "5", "10", "500"], "c": 0, "w": "ln e⁵ = 5; log 100 = 2. 5 + 2 = 7."}, {"t": "num", "q": "Evaluate log₁₀ 10 000.", "a": 4, "unit": "", "tol": 0.02, "w": "10⁴ = 10 000."}, {"t": "num", "q": "A sample has a half-life of 6 hours. What fraction remains after 18 hours? Give a decimal.", "a": 0.125, "unit": "", "tol": 0.02, "w": "18 h = 3 half-lives. (½)³ = 0.125."}], "2.8": [{"t": "mc", "q": "The derivative of a constant is", "o": ["the constant", "1", "0", "undefined"], "c": 2, "w": ""}, {"t": "mc", "q": "Velocity is the derivative of", "o": ["acceleration", "position", "mass", "force"], "c": 1, "w": ""}, {"t": "mc", "q": "The area under a speed-time graph gives", "o": ["acceleration", "distance", "speed", "force"], "c": 1, "w": ""}, {"t": "mc", "q": "d/dx(eˣ) =", "o": ["xeˣ⁻¹", "eˣ", "ln x", "1"], "c": 1, "w": ""}, {"t": "mc", "q": "Differentiate y = x⁴.", "o": ["4x³", "x³", "4x⁴", "x⁵/5"], "c": 0, "w": "Bring down 4, reduce power to 3."}, {"t": "mc", "q": "Differentiate y = 3x² + 5x − 7.", "o": ["6x + 5", "3x + 5", "6x − 7", "6x² + 5"], "c": 0, "w": "3 × 2x + 5 + 0."}, {"t": "num", "q": "For y = x³ − 2x, find the gradient at x = 2.", "a": 10, "unit": "", "tol": 0.02, "w": "dy/dx = 3x² − 2. At x = 2: 12 − 2 = 10."}, {"t": "num", "q": "A ball's height is h = 30t − 5t². What is its velocity, dh/dt, at t = 1 s?", "a": 20, "unit": "m/s", "tol": 0.02, "w": "dh/dt = 30 − 10t. At t = 1: 20 m/s."}], "3.1": [{"t": "mc", "q": "The area under a velocity–time graph gives", "o": ["acceleration", "displacement", "speed", "force"], "c": 1, "w": ""}, {"t": "mc", "q": "A car at constant speed around a bend is", "o": ["not accelerating", "accelerating", "decelerating", "in equilibrium"], "c": 1, "w": ""}, {"t": "mc", "q": "Ignoring air, a projectile's horizontal velocity", "o": ["increases", "decreases", "stays constant", "is zero"], "c": 2, "w": ""}, {"t": "mc", "q": "Range on level ground is greatest at", "o": ["30°", "45°", "60°", "90°"], "c": 1, "w": ""}, {"t": "mc", "q": "At the top of a ball's flight, its acceleration is", "o": ["zero", "9.8 m/s² downwards", "9.8 m/s² upwards", "changing direction"], "c": 1, "w": "Gravity still acts. Velocity is momentarily zero, not acceleration."}, {"t": "num", "q": "A cyclist accelerates from 2 m/s to 8 m/s in 4 s. What is her acceleration?", "a": 1.5, "unit": "m/s²", "tol": 0.02, "w": "a = (v − u)/t. (8 − 2) ÷ 4 = 1.5 m/s²."}, {"t": "num", "q": "A stone is dropped from rest. How fast is it falling after 3 s? (g = 9.8 m/s²)", "a": 29.4, "unit": "m/s", "tol": 0.02, "w": "v = u + at = 0 + 9.8 × 3."}], "3.2": [{"t": "mc", "q": "A body moving at constant velocity has net force", "o": ["in its direction", "zero", "opposite to motion", "equal to its weight"], "c": 1, "w": ""}, {"t": "mc", "q": "Doubling mass with the same force", "o": ["doubles acceleration", "halves acceleration", "has no effect", "quadruples it"], "c": 1, "w": ""}, {"t": "mc", "q": "Centripetal force points", "o": ["outwards", "along the motion", "towards the centre", "upwards"], "c": 2, "w": ""}, {"t": "mc", "q": "Third-law force pairs act on", "o": ["the same object", "different objects", "only moving objects", "only in contact"], "c": 1, "w": ""}, {"t": "mc", "q": "A book rests on a table. The reaction partner (Newton's third law) of the book's weight is", "o": ["the table's push on the book", "the book's gravitational pull on Earth", "friction", "the table's weight"], "c": 1, "w": "The weight is Earth pulling the book. Its partner is the book pulling Earth."}, {"t": "num", "q": "What net force gives a 1200 kg car an acceleration of 2.5 m/s²?", "a": 3000, "unit": "N", "tol": 0.02, "w": "F = ma = 1200 × 2.5."}, {"t": "num", "q": "What is the weight of a 65 kg person on Earth (g = 9.8 m/s²)?", "a": 637, "unit": "N", "tol": 0.02, "w": "W = mg = 65 × 9.8."}], "3.3": [{"t": "mc", "q": "The unit of energy is the", "o": ["watt", "newton", "joule", "pascal"], "c": 2, "w": ""}, {"t": "mc", "q": "Doubling speed multiplies kinetic energy by", "o": ["2", "4", "√2", "8"], "c": 1, "w": ""}, {"t": "mc", "q": "A kilowatt-hour measures", "o": ["power", "energy", "force", "current"], "c": 1, "w": ""}, {"t": "mc", "q": "Holding a weight still does how much work on it?", "o": ["mgh", "zero", "mg", "infinite"], "c": 1, "w": ""}, {"t": "num", "q": "How much work is done lifting a 20 kg box 1.5 m? (g = 9.8)", "a": 294.0, "unit": "J", "tol": 0.02, "w": "W = mgh. 20 × 9.8 × 1.5 = 294 J."}, {"t": "num", "q": "What is the kinetic energy of a 1000 kg car at 20 m/s?", "a": 200000, "unit": "J", "tol": 0.02, "w": "½ × 1000 × 400 = 200 000 J."}], "3.4": [{"t": "mc", "q": "Momentum is", "o": ["a scalar", "a vector", "energy", "force"], "c": 1, "w": ""}, {"t": "mc", "q": "In all collisions without external forces, what is conserved?", "o": ["kinetic energy", "momentum", "speed", "both KE and momentum"], "c": 1, "w": ""}, {"t": "mc", "q": "Torque depends on force and", "o": ["mass", "perpendicular distance from pivot", "speed", "time"], "c": 1, "w": ""}, {"t": "mc", "q": "Impulse equals", "o": ["force × distance", "change in momentum", "mass × acceleration", "energy ÷ time"], "c": 1, "w": ""}, {"t": "mc", "q": "Airbags reduce injury mainly because they", "o": ["reduce momentum change", "increase collision time", "absorb momentum permanently", "increase mass"], "c": 1, "w": "Same Δp over a longer time means smaller force."}, {"t": "mc", "q": "A spinning skater pulls in her arms, halving her moment of inertia. Her rotation rate", "o": ["halves", "doubles", "is unchanged", "quadruples"], "c": 1, "w": "L = Iω is conserved. Halve I, double ω."}, {"t": "num", "q": "What is the momentum of a 0.16 kg cricket ball moving at 30 m/s?", "a": 4.8, "unit": "kg m/s", "tol": 0.02, "w": "p = mv = 0.16 × 30."}, {"t": "num", "q": "A 1500 kg car at 20 m/s hits a stationary 1000 kg car and they lock together. What is their speed just after?", "a": 12.0, "unit": "m/s", "tol": 0.02, "w": "Momentum before = 30 000 kg m/s. v = 30 000 ÷ 2500 = 12 m/s."}], "3.5": [{"t": "mc", "q": "v = fλ: doubling frequency in the same medium", "o": ["doubles speed", "halves wavelength", "doubles wavelength", "halves speed"], "c": 1, "w": ""}, {"t": "mc", "q": "Destructive interference occurs when", "o": ["peak meets peak", "peak meets trough", "waves stop", "frequencies double"], "c": 1, "w": ""}, {"t": "mc", "q": "Points on a standing wave that never move are", "o": ["antinodes", "nodes", "peaks", "compressions"], "c": 1, "w": ""}, {"t": "mc", "q": "A receding source sounds", "o": ["higher", "lower", "louder", "the same"], "c": 1, "w": ""}, {"t": "mc", "q": "Sound passes from air into water, where it travels faster. Its frequency", "o": ["increases", "decreases", "stays the same", "becomes zero"], "c": 2, "w": "Frequency is set by the source; wavelength changes instead."}, {"t": "mc", "q": "Sound waves are", "o": ["transverse", "longitudinal", "electromagnetic", "standing only"], "c": 1, "w": "Air molecules oscillate along the direction of travel."}, {"t": "num", "q": "A wave has frequency 50 Hz and wavelength 4 m. What is its speed?", "a": 200, "unit": "m/s", "tol": 0.02, "w": "v = fλ = 50 × 4."}, {"t": "num", "q": "What is the period of a 250 Hz sound?", "a": 0.004, "unit": "s", "tol": 0.02, "w": "T = 1/f = 1/250."}], "3.6": [{"t": "mc", "q": "One ampere is one", "o": ["coulomb per second", "joule per second", "ohm per volt", "volt per coulomb"], "c": 0, "w": ""}, {"t": "mc", "q": "Adding a resistor in parallel makes the total resistance", "o": ["larger", "smaller", "unchanged", "zero"], "c": 1, "w": ""}, {"t": "mc", "q": "Components in series share the same", "o": ["voltage", "current", "power", "resistance"], "c": 1, "w": ""}, {"t": "mc", "q": "A kilowatt-hour is a unit of", "o": ["power", "energy", "charge", "current"], "c": 1, "w": ""}, {"t": "mc", "q": "Power is transmitted at higher voltage mainly to", "o": ["increase current", "reduce current and so I²R heating losses", "make it safer at home", "increase resistance"], "c": 1, "w": "Same P = VI with higher V means lower I. Loss I²R falls with the square of current."}, {"t": "num", "q": "A current of 2 A flows for 30 s. How much charge passes?", "a": 60, "unit": "C", "tol": 0.02, "w": "Q = It = 2 × 30."}, {"t": "num", "q": "A 12 V supply drives current through a 4 Ω resistor. What is the current?", "a": 3, "unit": "A", "tol": 0.02, "w": "I = V/R = 12 ÷ 4."}], "3.7": [{"t": "mc", "q": "A current-carrying wire produces", "o": ["no field", "a magnetic field", "only heat", "light"], "c": 1, "w": ""}, {"t": "mc", "q": "A step-down transformer has", "o": ["more secondary turns", "fewer secondary turns", "equal turns", "no secondary"], "c": 1, "w": ""}, {"t": "mc", "q": "Induced voltage depends on", "o": ["the size of the flux", "the rate of change of flux", "the colour of the wire", "resistance only"], "c": 1, "w": ""}, {"t": "mc", "q": "Maxwell showed light is", "o": ["a particle only", "an electromagnetic wave", "a sound wave", "a magnetic pole"], "c": 1, "w": ""}, {"t": "mc", "q": "A magnet is held still inside a coil. The induced current is", "o": ["large", "zero", "alternating", "growing"], "c": 1, "w": "Induction needs a changing flux."}, {"t": "mc", "q": "Who first showed that an electric current produces a magnetic field?", "o": ["Faraday", "Ørsted", "Maxwell", "Newton"], "c": 1, "w": "Ørsted, 1820."}, {"t": "num", "q": "A 0.5 m wire carrying 4 A lies at right angles to a 0.2 T field. What force acts on it?", "a": 0.4, "unit": "N", "tol": 0.02, "w": "F = BIL = 0.2 × 4 × 0.5."}, {"t": "num", "q": "A transformer has 500 primary turns and 25 secondary turns. With 240 V in, what is the output voltage?", "a": 12, "unit": "V", "tol": 0.02, "w": "Vs = Vp × Ns/Np = 240 × 25/500."}], "3.8": [{"t": "mc", "q": "Absolute zero is", "o": ["0 °C", "0 K", "−100 °C", "273 K"], "c": 1, "w": ""}, {"t": "mc", "q": "Heat flows spontaneously from", "o": ["cold to hot", "hot to cold", "either way", "neither"], "c": 1, "w": ""}, {"t": "mc", "q": "During boiling, temperature", "o": ["rises fast", "stays constant", "falls", "oscillates"], "c": 1, "w": ""}, {"t": "mc", "q": "The first law of thermodynamics is about", "o": ["entropy", "conservation of energy", "absolute zero", "momentum"], "c": 1, "w": ""}, {"t": "mc", "q": "A refrigerator moves heat from cold to hot. Does this break the second law?", "o": ["Yes", "No, because work is supplied and more entropy is produced outside", "No, because fridges are cold", "Only in summer"], "c": 1, "w": "The second law forbids this happening spontaneously, not with work input."}, {"t": "num", "q": "Convert 25 °C to kelvin.", "a": 298, "unit": "K", "tol": 0.02, "w": "25 + 273."}, {"t": "num", "q": "How much energy raises 2.0 kg of water by 10 K? (c = 4200 J/kg K)", "a": 84000, "unit": "J", "tol": 0.02, "w": "Q = mcΔT = 2 × 4200 × 10."}], "3.9": [{"t": "mc", "q": "E = mc² says", "o": ["mass and energy are equivalent", "energy is always lost", "light has mass", "speed adds"], "c": 0, "w": ""}, {"t": "mc", "q": "Photon energy is proportional to", "o": ["wavelength", "frequency", "brightness", "amplitude"], "c": 1, "w": ""}, {"t": "mc", "q": "After 3 half-lives, the fraction remaining is", "o": ["1/3", "1/6", "1/8", "1/9"], "c": 2, "w": ""}, {"t": "mc", "q": "Moving clocks", "o": ["run fast", "run slow", "stop", "are unaffected"], "c": 1, "w": ""}, {"t": "mc", "q": "In the photoelectric effect, increasing the brightness of light below the threshold frequency", "o": ["ejects more electrons", "ejects faster electrons", "ejects no electrons", "lowers the threshold"], "c": 2, "w": "Each photon must individually have enough energy; more low-energy photons don't help."}, {"t": "mc", "q": "The Sun produces energy mainly by", "o": ["fission of uranium", "fusion of hydrogen into helium", "chemical burning", "radioactive decay"], "c": 1, "w": "Hydrogen fusion in the core."}, {"t": "num", "q": "How much energy is equivalent to 1 g of mass? (c = 3 × 10⁸ m/s)", "a": 90000000000000.0, "unit": "J", "tol": 0.02, "w": "E = mc² = 0.001 × 9 × 10¹⁶. = 9 × 10¹³ J."}, {"t": "num", "q": "What is the energy of a photon of green light, frequency 5.6 × 10¹⁴ Hz? (h = 6.63 × 10⁻³⁴ J s)", "a": 3.7128e-19, "unit": "J", "tol": 0.02, "w": "E = hf = 6.63 × 10⁻³⁴ × 5.6 × 10¹⁴ ≈ 3.7 × 10⁻¹⁹ J."}], "4.1": [{"t": "mc", "q": "The nucleus contains", "o": ["protons and electrons", "protons and neutrons", "only neutrons", "electrons and neutrons"], "c": 1, "w": ""}, {"t": "mc", "q": "An atom with 8 protons and 10 electrons is", "o": ["neutral", "a 2− ion", "a 2+ ion", "an isotope"], "c": 1, "w": ""}, {"t": "mc", "q": "Mass number is", "o": ["protons", "protons + neutrons", "electrons", "neutrons"], "c": 1, "w": ""}, {"t": "mc", "q": "Maximum electrons in the first shell:", "o": ["2", "8", "18", "1"], "c": 0, "w": ""}, {"t": "mc", "q": "What defines which element an atom is?", "o": ["number of neutrons", "number of protons", "mass number", "number of shells"], "c": 1, "w": "The atomic number, Z, the proton count."}, {"t": "mc", "q": "Give the shell arrangement of chlorine (Z = 17).", "o": ["2, 8, 7", "2, 7, 8", "8, 8, 1", "2, 8, 8"], "c": 0, "w": "Fill 2, then 8, then the remaining 7."}, {"t": "num", "q": "How many neutrons are in an atom of iron-56 (Z = 26)?", "a": 30, "unit": "", "tol": 0.02, "w": "N = A − Z = 56 − 26."}, {"t": "num", "q": "How many electrons does a Mg²⁺ ion have? (Mg: Z = 12)", "a": 10, "unit": "", "tol": 0.02, "w": "Neutral Mg has 12 electrons. 2+ means two lost: 10."}], "4.2": [{"t": "mc", "q": "Periods are", "o": ["columns", "rows", "blocks", "groups"], "c": 1, "w": ""}, {"t": "mc", "q": "Electronegativity increases", "o": ["down a group", "across a period", "with more neutrons", "never"], "c": 1, "w": ""}, {"t": "mc", "q": "Mendeleev's table was confirmed when", "o": ["electrons were discovered", "predicted elements were found", "isotopes were found", "noble gases reacted"], "c": 1, "w": ""}, {"t": "mc", "q": "Transition metals often", "o": ["are gases", "form coloured compounds", "have no electrons", "are unreactive"], "c": 1, "w": ""}, {"t": "mc", "q": "Elements in the same group have the same number of", "o": ["shells", "valence electrons", "neutrons", "protons"], "c": 1, "w": "That is why they react similarly."}, {"t": "mc", "q": "Which group contains the noble gases?", "o": ["1", "2", "17", "18"], "c": 3, "w": "Group 18, full outer shells."}, {"t": "num", "q": "Calcium is in group 2. What charge does its ion usually carry? (enter as a number, e.g. 2 for 2+)", "a": 2, "unit": "", "tol": 0.02, "w": "Two valence electrons, lost to give Ca²⁺."}], "4.3": [{"t": "mc", "q": "A covalent bond is", "o": ["a transferred electron", "a shared pair of electrons", "an ion lattice", "a sea of electrons"], "c": 1, "w": ""}, {"t": "mc", "q": "Water's shape is", "o": ["linear", "bent", "tetrahedral", "planar"], "c": 1, "w": ""}, {"t": "mc", "q": "The strongest intermolecular force listed is", "o": ["dispersion", "hydrogen bonding", "polar–polar", "they are equal"], "c": 1, "w": ""}, {"t": "mc", "q": "Lone pairs make bond angles", "o": ["larger", "smaller", "unchanged", "180°"], "c": 1, "w": ""}, {"t": "mc", "q": "What type of bonding is in magnesium oxide, MgO?", "o": ["covalent", "ionic", "metallic", "hydrogen"], "c": 1, "w": "Metal plus non-metal: electron transfer."}, {"t": "mc", "q": "Why do metals conduct electricity?", "o": ["they contain ions only", "they have a sea of free electrons", "they are polar", "they have hydrogen bonds"], "c": 1, "w": "Delocalised electrons can move."}, {"t": "num", "q": "How many electrons are shared in a double bond?", "a": 4, "unit": "", "tol": 0.02, "w": "Each bond is a pair; two bonds = 4 electrons."}], "4.4": [{"t": "mc", "q": "One mole contains", "o": ["6.02 × 10²³ particles", "1000 particles", "22.4 particles", "one gram"], "c": 0, "w": ""}, {"t": "mc", "q": "To balance an equation you change", "o": ["subscripts", "coefficients", "both", "neither"], "c": 1, "w": ""}, {"t": "mc", "q": "The limiting reagent", "o": ["is in excess", "runs out first", "is a catalyst", "is the product"], "c": 1, "w": ""}, {"t": "mc", "q": "Molarity is", "o": ["grams per litre", "moles per litre", "moles per gram", "litres per mole"], "c": 1, "w": ""}, {"t": "num", "q": "How many moles are in 44 g of carbon dioxide (M = 44 g/mol)?", "a": 1, "unit": "mol", "tol": 0.02, "w": "n = m/M = 44/44."}, {"t": "num", "q": "What is the molar mass of sulfuric acid, H₂SO₄? (H = 1, S = 32, O = 16)", "a": 98, "unit": "g/mol", "tol": 0.02, "w": "2(1) + 32 + 4(16) = 98."}], "4.5": [{"t": "mc", "q": "At constant temperature, halving the volume of a gas", "o": ["halves pressure", "doubles pressure", "keeps pressure", "quadruples it"], "c": 1, "w": ""}, {"t": "mc", "q": "Gas laws require temperature in", "o": ["°C", "°F", "K", "any unit"], "c": 2, "w": ""}, {"t": "mc", "q": "In PV = nRT, n is", "o": ["number of molecules", "moles", "density", "Avogadro's number"], "c": 1, "w": ""}, {"t": "mc", "q": "Particles in a liquid", "o": ["are fixed", "slide past each other", "are far apart", "do not move"], "c": 1, "w": ""}, {"t": "mc", "q": "Why must temperatures be in kelvin for gas laws?", "o": ["Celsius is less precise", "the laws are proportional relationships measured from absolute zero", "kelvin is larger", "by convention only"], "c": 1, "w": "Doubling kelvin doubles volume; doubling °C does not."}, {"t": "mc", "q": "According to kinetic theory, heating a gas in a rigid container raises its pressure because", "o": ["particles get larger", "particles move faster and hit the walls harder and more often", "more particles form", "the container shrinks"], "c": 1, "w": "Faster particles, more forceful and frequent collisions."}, {"t": "num", "q": "A gas at 100 kPa occupies 6.0 L. It is compressed to 2.0 L at constant temperature. What is the new pressure?", "a": 300, "unit": "kPa", "tol": 0.02, "w": "P₁V₁ = P₂V₂. 100 × 6 = P₂ × 2."}, {"t": "num", "q": "A balloon of 2.0 L at 300 K is heated to 450 K at constant pressure. What is its new volume?", "a": 3, "unit": "L", "tol": 0.02, "w": "V₂ = V₁ T₂/T₁ = 2 × 450/300."}], "4.6": [{"t": "mc", "q": "At equilibrium, forward and reverse rates are", "o": ["zero", "equal", "increasing", "unequal"], "c": 1, "w": ""}, {"t": "mc", "q": "Raising temperature generally makes reactions", "o": ["slower", "faster", "unchanged", "stop"], "c": 1, "w": ""}, {"t": "mc", "q": "A large K means", "o": ["mostly reactants", "mostly products", "no reaction", "a slow reaction"], "c": 1, "w": ""}, {"t": "mc", "q": "Endothermic reactions have ΔH", "o": ["negative", "positive", "zero", "undefined"], "c": 1, "w": ""}, {"t": "mc", "q": "An exothermic reaction", "o": ["absorbs heat", "releases heat", "has ΔH > 0", "needs a catalyst"], "c": 1, "w": "Exo = out."}, {"t": "mc", "q": "A catalyst works by", "o": ["raising the temperature", "lowering the activation energy", "being used up", "changing ΔH"], "c": 1, "w": "It provides an easier pathway."}, {"t": "num", "q": "Breaking bonds in a reaction needs 1370 kJ; making the new bonds releases 1652 kJ. What is ΔH?", "a": -282, "unit": "kJ", "tol": 0.02, "w": "ΔH = broken − made = 1370 − 1652."}, {"t": "num", "q": "For A ⇌ B, at equilibrium [A] = 0.20 M and [B] = 0.80 M. What is K?", "a": 4, "unit": "", "tol": 0.02, "w": "K = [B]/[A] = 0.80/0.20."}], "4.7": [{"t": "mc", "q": "An acid is a proton", "o": ["acceptor", "donor", "neutraliser", "catalyst"], "c": 1, "w": ""}, {"t": "mc", "q": "pH 2 compared with pH 4 is", "o": ["twice as acidic", "100 times as acidic", "less acidic", "the same"], "c": 1, "w": ""}, {"t": "mc", "q": "Reduction is", "o": ["loss of electrons", "gain of electrons", "loss of protons", "gain of oxygen"], "c": 1, "w": ""}, {"t": "mc", "q": "Neutral pH at 25 °C is", "o": ["0", "1", "7", "14"], "c": 2, "w": ""}, {"t": "mc", "q": "In Zn + Cu²⁺ → Zn²⁺ + Cu, which species is oxidised?", "o": ["Zn", "Cu²⁺", "Zn²⁺", "Cu"], "c": 0, "w": "Zn loses two electrons."}, {"t": "mc", "q": "A weak acid differs from a strong acid in that it", "o": ["is always dilute", "ionises only partially", "has no protons", "is a base"], "c": 1, "w": "Strength is about extent of ionisation."}, {"t": "num", "q": "What is the pH of a solution with [H⁺] = 10⁻⁴ M?", "a": 4, "unit": "", "tol": 0.02, "w": "pH = −log(10⁻⁴) = 4."}, {"t": "num", "q": "What is [H⁺] in mol/L for a solution of pH 3? Give a decimal.", "a": 0.001, "unit": "mol/L", "tol": 0.02, "w": "[H⁺] = 10⁻³."}], "4.8": [{"t": "mc", "q": "Carbon forms how many bonds?", "o": ["2", "3", "4", "6"], "c": 2, "w": ""}, {"t": "mc", "q": "An ester forms from", "o": ["acid + alcohol", "two alkanes", "base + water", "two acids"], "c": 0, "w": ""}, {"t": "mc", "q": "'But-' means how many carbons?", "o": ["2", "3", "4", "5"], "c": 2, "w": ""}, {"t": "mc", "q": "Polyethylene is made from", "o": ["ethane", "ethene", "ethanol", "methane"], "c": 1, "w": ""}, {"t": "mc", "q": "What is the formula of propane (3 carbons)?", "o": ["C₃H₆", "C₃H₈", "C₃H₁₀", "C₂H₆"], "c": 1, "w": "CₙH₂ₙ₊₂ with n = 3."}, {"t": "mc", "q": "Which functional group identifies an alcohol?", "o": ["–COOH", "–OH", "–NH₂", "C=C"], "c": 1, "w": "Hydroxyl group."}, {"t": "num", "q": "Octane is an alkane with 8 carbon atoms. How many hydrogen atoms does it have?", "a": 18, "unit": "", "tol": 0.02, "w": "2(8) + 2 = 18."}, {"t": "num", "q": "What is the molar mass of ethanol, C₂H₅OH? (C = 12, H = 1, O = 16)", "a": 46, "unit": "g/mol", "tol": 0.02, "w": "2(12) + 6(1) + 16 = 46."}], "5.1": [{"t": "mc", "q": "Earth's axial tilt is about", "o": ["5°", "23.4°", "45°", "90°"], "c": 1, "w": ""}, {"t": "mc", "q": "The Magellanic Clouds are", "o": ["storm clouds", "nearby galaxies", "nebulae in our Solar System", "comets"], "c": 1, "w": ""}, {"t": "mc", "q": "Copernicus put at the centre", "o": ["Earth", "the Moon", "the Sun", "Jupiter"], "c": 2, "w": ""}, {"t": "mc", "q": "The Moon's phase cycle is about", "o": ["7 days", "14 days", "29.5 days", "365 days"], "c": 2, "w": ""}, {"t": "mc", "q": "What causes Earth's seasons?", "o": ["changing distance from the Sun", "the tilt of Earth's axis", "the Moon", "changes in the Sun's output"], "c": 1, "w": "Tilt changes how directly sunlight strikes each hemisphere."}, {"t": "mc", "q": "Why does the Moon show phases?", "o": ["Earth's shadow", "we see different amounts of its sunlit half", "it changes shape", "clouds"], "c": 1, "w": "Half is always lit; our viewing angle changes."}, {"t": "num", "q": "Brisbane is at latitude 27.5° S. What is the Sun's noon altitude at the December (summer) solstice, in degrees?", "a": 85.9, "unit": "°", "tol": 0.02, "w": "h = 90 − 27.5 + 23.4. ≈ 85.9°, almost overhead."}, {"t": "num", "q": "And at the June (winter) solstice?", "a": 39.1, "unit": "°", "tol": 0.02, "w": "h = 90 − 27.5 − 23.4 ≈ 39.1°."}], "5.2": [{"t": "mc", "q": "Gravitational force between two masses varies as", "o": ["1/r", "1/r²", "r²", "r"], "c": 1, "w": ""}, {"t": "mc", "q": "Kepler's first law says orbits are", "o": ["circles", "ellipses", "spirals", "straight lines"], "c": 1, "w": ""}, {"t": "mc", "q": "Orbital speed depends on", "o": ["the satellite's mass", "the central mass and distance", "the satellite's shape", "nothing"], "c": 1, "w": ""}, {"t": "mc", "q": "Cavendish's experiment measured", "o": ["c", "G", "g", "h"], "c": 1, "w": ""}, {"t": "mc", "q": "Astronauts in the ISS float because", "o": ["there is no gravity there", "they are in free fall with the station", "the station blocks gravity", "they are too far from Earth"], "c": 1, "w": "Gravity there is about 90% of surface strength."}, {"t": "mc", "q": "By Kepler's second law, a comet moves fastest", "o": ["far from the Sun", "closest to the Sun", "at a constant speed", "when crossing Earth's orbit only"], "c": 1, "w": "Equal areas in equal times."}, {"t": "num", "q": "A planet orbits at 4 AU from the Sun. What is its period in years?", "a": 8, "unit": "years", "tol": 0.02, "w": "T² = 4³ = 64."}, {"t": "num", "q": "If the distance between two masses triples, by what factor does the gravitational force change? Give a decimal.", "a": 0.1111111111111111, "unit": "", "tol": 0.02, "w": "Inverse square: 1/3² = 1/9 ≈ 0.111."}], "5.3": [{"t": "mc", "q": "A redshift means the source is", "o": ["approaching", "receding", "hotter", "closer"], "c": 1, "w": ""}, {"t": "mc", "q": "Hotter stars appear", "o": ["redder", "bluer", "dimmer", "larger"], "c": 1, "w": ""}, {"t": "mc", "q": "1 parsec is about", "o": ["1 light-year", "3.26 light-years", "1 AU", "1000 km"], "c": 1, "w": ""}, {"t": "mc", "q": "Absorption lines tell us a star's", "o": ["age only", "composition", "distance only", "mass only"], "c": 1, "w": ""}, {"t": "mc", "q": "Why are X-ray telescopes placed in space?", "o": ["to be closer to stars", "Earth's atmosphere absorbs X-rays", "to avoid light pollution only", "X-rays need vacuum to exist"], "c": 1, "w": "The atmosphere is opaque to X-rays."}, {"t": "num", "q": "A star is moved to three times its distance. By what factor does its apparent brightness change? Give a decimal.", "a": 0.1111111111111111, "unit": "", "tol": 0.02, "w": "Inverse square: 1/9."}, {"t": "num", "q": "A star has a parallax of 0.25 arcseconds. How far away is it, in parsecs?", "a": 4, "unit": "pc", "tol": 0.02, "w": "d = 1/p = 1/0.25."}], "5.4": [{"t": "mc", "q": "The Sun contains about what share of the Solar System's mass?", "o": ["50%", "75%", "over 99%", "10%"], "c": 2, "w": ""}, {"t": "mc", "q": "The Solar System is about how old?", "o": ["6000 years", "4.6 million years", "4.6 billion years", "13.8 billion years"], "c": 2, "w": ""}, {"t": "mc", "q": "The transit method detects planets by", "o": ["their light", "starlight dimming", "radio signals", "their moons"], "c": 1, "w": ""}, {"t": "mc", "q": "Uranus and Neptune are", "o": ["rocky", "ice giants", "dwarf planets", "comets"], "c": 1, "w": ""}, {"t": "mc", "q": "What powers the Sun?", "o": ["burning gas", "nuclear fission", "nuclear fusion", "gravity only"], "c": 2, "w": "Hydrogen fuses into helium in the core."}, {"t": "mc", "q": "Why are the inner planets rocky and the outer ones gas giants?", "o": ["the inner ones are older", "near the Sun it was too hot for ices to condense", "the Sun ate their gas later", "chance"], "c": 1, "w": "The frost line."}, {"t": "num", "q": "Jupiter is 5.2 AU from the Sun. How many kilometres is that? (1 AU = 1.5 × 10⁸ km)", "a": 780000000.0, "unit": "km", "tol": 0.02, "w": "5.2 × 1.5 × 10⁸ = 7.8 × 10⁸ km."}, {"t": "num", "q": "How long does sunlight take to reach Neptune, 30 AU away, in hours? (Earth: 500 s)", "a": 4.166666666666667, "unit": "h", "tol": 0.02, "w": "30 × 500 s = 15 000 s. ÷ 3600 ≈ 4.2 h."}], "5.5": [{"t": "mc", "q": "Stars are powered by", "o": ["fission", "fusion", "chemical burning", "gravity alone"], "c": 1, "w": ""}, {"t": "mc", "q": "On an HR diagram, hot stars are traditionally on the", "o": ["left", "right", "top", "bottom"], "c": 0, "w": ""}, {"t": "mc", "q": "Luminosity depends on temperature to the power", "o": ["1", "2", "3", "4"], "c": 3, "w": ""}, {"t": "mc", "q": "The most massive stars have", "o": ["the longest lives", "the shortest lives", "no fusion", "red colours"], "c": 1, "w": ""}, {"t": "mc", "q": "On the HR diagram, a hot but very faint star is most likely a", "o": ["red giant", "main-sequence star", "white dwarf", "supergiant"], "c": 2, "w": "Hot and faint means small."}, {"t": "mc", "q": "What keeps a stable star from collapsing?", "o": ["rotation", "pressure from hot gas and radiation", "magnetism", "nothing; they are collapsing slowly"], "c": 1, "w": "Pressure balances gravity."}, {"t": "num", "q": "Two stars are the same size, but one is twice as hot. How many times more luminous is it?", "a": 16, "unit": "×", "tol": 0.02, "w": "L ∝ T⁴. 2⁴ = 16."}, {"t": "num", "q": "A star has the same temperature as the Sun but 10 times its radius. How many times more luminous is it?", "a": 100, "unit": "×", "tol": 0.02, "w": "L ∝ R² at fixed T. 10² = 100."}], "5.6": [{"t": "mc", "q": "A planetary nebula is", "o": ["a forming planet", "the ejected outer layers of a dying star", "a galaxy", "a supernova"], "c": 1, "w": ""}, {"t": "mc", "q": "Neutron stars are about the size of", "o": ["Earth", "a city", "the Sun", "a planet"], "c": 1, "w": ""}, {"t": "mc", "q": "A black hole's boundary is the", "o": ["corona", "event horizon", "photosphere", "nebula"], "c": 1, "w": ""}, {"t": "mc", "q": "Supernovae occur for stars above about", "o": ["0.5", "1", "8", "100"], "c": 2, "w": "About eight solar masses."}, {"t": "mc", "q": "What will the Sun become at the end of its life?", "o": ["a black hole", "a neutron star", "a white dwarf", "a supernova"], "c": 2, "w": "It is too low in mass for a supernova."}, {"t": "mc", "q": "Where were most of the heavy elements in your body made?", "o": ["the Big Bang", "inside stars and supernovae", "on Earth", "in the Sun"], "c": 1, "w": "Stellar nucleosynthesis."}, {"t": "num", "q": "What is the Schwarzschild radius of a 10 solar-mass black hole, in km? (M☉ = 2.0 × 10³⁰ kg, G = 6.67 × 10⁻¹¹, c = 3.0 × 10⁸)", "a": 29.644444444444446, "unit": "km", "tol": 0.02, "w": "R = 2GM/c² = 2 × 6.67 × 10⁻¹¹ × 2 × 10³¹ ÷ 9 × 10¹⁶. ≈ 29 600 m ≈ 30 km."}, {"t": "num", "q": "A white dwarf has mass 1.2 × 10³⁰ kg and radius 6.0 × 10⁶ m. What is its density, in kg/m³?", "a": 1326291192.4324613, "unit": "kg/m³", "tol": 0.02, "w": "V = (4/3)π(6 × 10⁶)³ ≈ 9.05 × 10²⁰ m³. ρ ≈ 1.3 × 10⁹ kg/m³."}], "5.7": [{"t": "mc", "q": "The Milky Way contains roughly how many stars?", "o": ["millions", "hundreds of billions", "trillions of trillions", "thousands"], "c": 1, "w": ""}, {"t": "mc", "q": "Vera Rubin's work provided evidence for", "o": ["the Big Bang", "dark matter", "pulsars", "exoplanets"], "c": 1, "w": ""}, {"t": "mc", "q": "Andromeda is", "o": ["a star", "a separate galaxy", "a nebula in our galaxy", "a planet"], "c": 1, "w": ""}, {"t": "mc", "q": "Our galaxy's central black hole has a mass of about", "o": ["4 solar masses", "4 million solar masses", "4 billion solar masses", "4 Earth masses"], "c": 1, "w": ""}, {"t": "mc", "q": "What type of galaxy is the Milky Way?", "o": ["elliptical", "irregular", "barred spiral", "lenticular only"], "c": 2, "w": "A barred spiral."}, {"t": "mc", "q": "Flat galaxy rotation curves are evidence for", "o": ["black holes", "dark matter", "dark energy", "spiral arms"], "c": 1, "w": "Extra unseen mass in the halo."}, {"t": "num", "q": "The Sun orbits the galactic centre at 230 km/s at a radius of 2.5 × 10²⁰ m. How long is one orbit, in millions of years? (1 year = 3.15 × 10⁷ s)", "a": 216.81108720426454, "unit": "million years", "tol": 0.03, "w": "T = 2πr/v = 2π × 2.5 × 10²⁰ ÷ 2.3 × 10⁵ ≈ 6.8 × 10¹⁵ s. ÷ 3.15 × 10⁷ ≈ 2.2 × 10⁸ years ≈ 220 million."}, {"t": "num", "q": "Using M = v²r/G with the numbers above, estimate the mass inside the Sun's orbit, in kg.", "a": 1.9827586206896552e+41, "unit": "kg", "tol": 0.03, "w": "(2.3 × 10⁵)² × 2.5 × 10²⁰ ÷ 6.67 × 10⁻¹¹. ≈ 2.0 × 10⁴¹ kg, about 10¹¹ solar masses."}], "5.8": [{"t": "mc", "q": "Hubble's law says recession speed is proportional to", "o": ["mass", "distance", "brightness", "age"], "c": 1, "w": ""}, {"t": "mc", "q": "The universe is about how old?", "o": ["4.6 billion years", "13.8 billion years", "100 billion years", "6000 years"], "c": 1, "w": ""}, {"t": "mc", "q": "The expansion of the universe is", "o": ["slowing", "accelerating", "stopped", "reversing"], "c": 1, "w": ""}, {"t": "mc", "q": "The CMB has a temperature of about", "o": ["0 K", "2.7 K", "273 K", "5800 K"], "c": 1, "w": ""}, {"t": "mc", "q": "The cosmic microwave background is", "o": ["light from the first stars", "light released when atoms first formed, now stretched to microwaves", "radio noise from Earth", "light from black holes"], "c": 1, "w": "About 380 000 years after the Big Bang."}, {"t": "mc", "q": "Which is NOT one of the main pillars of evidence for the Big Bang?", "o": ["expansion of the universe", "cosmic microwave background", "light-element abundances", "the existence of black holes"], "c": 3, "w": "Black holes are not evidence for the Big Bang."}, {"t": "num", "q": "A galaxy is 100 Mpc away. Using H₀ = 70 km/s/Mpc, how fast is it receding?", "a": 7000, "unit": "km/s", "tol": 0.02, "w": "v = H₀d = 70 × 100."}, {"t": "num", "q": "A galaxy recedes at 14 000 km/s. How far away is it?", "a": 200, "unit": "Mpc", "tol": 0.02, "w": "d = v/H₀ = 14 000/70."}], "6.1": [{"t": "mc", "q": "Enzymes are mostly", "o": ["lipids", "proteins", "sugars", "minerals"], "c": 1, "w": ""}, {"t": "mc", "q": "Water dissolves many substances because it is", "o": ["non-polar", "polar", "acidic", "large"], "c": 1, "w": ""}, {"t": "mc", "q": "DNA and RNA are", "o": ["proteins", "nucleic acids", "lipids", "carbohydrates"], "c": 1, "w": ""}, {"t": "mc", "q": "Human enzyme optimum temperature is about", "o": ["0 °C", "20 °C", "37 °C", "80 °C"], "c": 2, "w": ""}, {"t": "mc", "q": "Proteins are polymers of", "o": ["sugars", "amino acids", "fatty acids", "nucleotides"], "c": 1, "w": "Twenty kinds of amino acid."}, {"t": "mc", "q": "Which molecule forms cell membranes?", "o": ["starch", "phospholipid", "DNA", "glucose"], "c": 1, "w": "Lipids with a water-loving head and water-avoiding tails."}, {"t": "num", "q": "Using v = Vmax[S]/(Km + [S]), find v when [S] = Km and Vmax = 10 units.", "a": 5, "unit": "units", "tol": 0.02, "w": "v = 10 × Km/(2Km) = 5: half the maximum."}], "6.2": [{"t": "mc", "q": "Cell theory says cells come from", "o": ["non-living matter", "other cells", "the nucleus", "proteins"], "c": 1, "w": ""}, {"t": "mc", "q": "Plant cells have, but animal cells lack,", "o": ["mitochondria", "a cell wall", "a nucleus", "ribosomes"], "c": 1, "w": ""}, {"t": "mc", "q": "Osmosis is the movement of", "o": ["any molecule", "water", "proteins", "ions only"], "c": 1, "w": ""}, {"t": "mc", "q": "As a cell grows, its SA:V ratio", "o": ["increases", "decreases", "stays the same", "doubles"], "c": 1, "w": ""}, {"t": "mc", "q": "Which cells lack a nucleus?", "o": ["plant cells", "animal cells", "bacteria", "fungal cells"], "c": 2, "w": "Prokaryotes have no nucleus."}, {"t": "mc", "q": "Where in the cell is aerobic respiration carried out?", "o": ["nucleus", "mitochondrion", "ribosome", "cell wall"], "c": 1, "w": "The powerhouse."}, {"t": "num", "q": "A cell 20 μm across appears 8 mm across in a micrograph. What is the magnification?", "a": 400, "unit": "×", "tol": 0.02, "w": "8 mm = 8000 μm. 8000 ÷ 20 = 400."}, {"t": "num", "q": "What is the surface-area-to-volume ratio of a cube-shaped cell with sides 2 μm? (μm⁻¹)", "a": 3, "unit": "", "tol": 0.02, "w": "6/L = 6/2 = 3 μm⁻¹."}], "6.3": [{"t": "mc", "q": "Photosynthesis takes place in", "o": ["mitochondria", "chloroplasts", "ribosomes", "the nucleus"], "c": 1, "w": ""}, {"t": "mc", "q": "Respiration releases", "o": ["oxygen", "carbon dioxide", "glucose", "chlorophyll"], "c": 1, "w": ""}, {"t": "mc", "q": "Yeast fermentation produces", "o": ["lactate", "ethanol and CO₂", "oxygen", "starch"], "c": 1, "w": ""}, {"t": "mc", "q": "ATP → ADP releases", "o": ["energy", "oxygen", "glucose", "DNA"], "c": 0, "w": ""}, {"t": "mc", "q": "Which gas is released by photosynthesis?", "o": ["carbon dioxide", "oxygen", "nitrogen", "methane"], "c": 1, "w": "Water is split, releasing O₂."}, {"t": "mc", "q": "What is the cell's main energy currency?", "o": ["glucose", "ATP", "DNA", "starch"], "c": 1, "w": "Adenosine triphosphate."}, {"t": "num", "q": "How many molecules of O₂ are needed to respire one molecule of glucose?", "a": 6, "unit": "", "tol": 0.02, "w": "From the balanced equation."}, {"t": "num", "q": "Glucose has M = 180 g/mol. How many moles of CO₂ are produced when 90 g of glucose is fully respired?", "a": 3, "unit": "mol", "tol": 0.02, "w": "90 g = 0.5 mol glucose. × 6 = 3 mol CO₂."}], "6.4": [{"t": "mc", "q": "A codon is", "o": ["one base", "three bases", "one gene", "one protein"], "c": 1, "w": ""}, {"t": "mc", "q": "Translation happens at", "o": ["the nucleus", "ribosomes", "mitochondria", "the membrane"], "c": 1, "w": ""}, {"t": "mc", "q": "RNA uses which base instead of thymine?", "o": ["adenine", "uracil", "guanine", "cytosine"], "c": 1, "w": ""}, {"t": "mc", "q": "Whose X-ray images were crucial to the DNA structure?", "o": ["Marie Curie", "Rosalind Franklin", "Lynn Margulis", "Barbara McClintock"], "c": 1, "w": ""}, {"t": "mc", "q": "Which base pairs with guanine in DNA?", "o": ["adenine", "thymine", "cytosine", "uracil"], "c": 2, "w": "G–C."}, {"t": "mc", "q": "Write the complementary strand to 5′-ATGCCT-3′ (reading the partner 3′ to 5′).", "o": ["TACGGA", "ATGCCT", "UACGGA", "GCATTC"], "c": 0, "w": "A→T, T→A, G→C, C→G."}, {"t": "num", "q": "A DNA sample is 30% adenine. What percentage is guanine?", "a": 20, "unit": "%", "tol": 0.02, "w": "A = T = 30%, so A + T = 60%. G + C = 40%, G = 20%."}, {"t": "num", "q": "How many amino acids are coded by an mRNA sequence of 300 bases (ignoring stop codons)?", "a": 100, "unit": "", "tol": 0.02, "w": "3 bases per codon: 300 ÷ 3."}], "6.5": [{"t": "mc", "q": "An organism with two different alleles is", "o": ["homozygous", "heterozygous", "recessive", "a mutant"], "c": 1, "w": ""}, {"t": "mc", "q": "Aa × Aa gives a phenotype ratio of", "o": ["1:1", "3:1", "1:2:1", "all dominant"], "c": 1, "w": ""}, {"t": "mc", "q": "Meiosis produces cells with", "o": ["double the chromosomes", "half the chromosomes", "the same number", "no chromosomes"], "c": 1, "w": ""}, {"t": "mc", "q": "X-linked recessive traits are commoner in", "o": ["females", "males", "neither", "plants only"], "c": 1, "w": ""}, {"t": "mc", "q": "A woman who is a carrier of colour blindness (XᴮXᵇ) has children with a man with normal vision. What fraction of their sons are expected to be colour blind?", "o": ["0", "1/4", "1/2", "all"], "c": 2, "w": "Sons get Y from father and one X from mother: half get Xᵇ."}, {"t": "num", "q": "Two Aa parents. What fraction of offspring are expected to be aa? Give a decimal.", "a": 0.25, "unit": "", "tol": 0.02, "w": "One square in four."}, {"t": "num", "q": "AA × aa. What fraction of offspring are heterozygous? Give a decimal.", "a": 1, "unit": "", "tol": 0.02, "w": "Every offspring gets A from one parent and a from the other."}], "6.6": [{"t": "mc", "q": "Evolution happens to", "o": ["individuals", "populations", "single cells only", "species names"], "c": 1, "w": ""}, {"t": "mc", "q": "Darwin and Wallace published in", "o": ["1758", "1858", "1958", "1908"], "c": 1, "w": ""}, {"t": "mc", "q": "Fitness in biology means", "o": ["strength", "reproductive success", "speed", "intelligence"], "c": 1, "w": ""}, {"t": "mc", "q": "A scientific 'theory' is", "o": ["a guess", "a well-tested explanation", "unproven", "an opinion"], "c": 1, "w": ""}, {"t": "mc", "q": "Which three things are needed for natural selection?", "o": ["mutation, migration, mating", "variation, inheritance, differential reproduction", "need, effort, change", "size, speed, strength"], "c": 1, "w": "Darwin's core logic."}, {"t": "mc", "q": "Antibiotic resistance in bacteria is an example of", "o": ["Lamarckism", "natural selection", "genetic drift only", "spontaneous generation"], "c": 1, "w": "Resistant variants survive and reproduce."}, {"t": "num", "q": "An allele has frequency 0.5 and a 10% advantage (s = 0.1). Using p′ = p(1+s)/[p(1+s) + (1 − p)], what is its frequency next generation?", "a": 0.5238095238095238, "unit": "", "tol": 0.02, "w": "p(1 + s) = 0.55. 0.55 ÷ (0.55 + 0.5) ≈ 0.524."}], "6.7": [{"t": "mc", "q": "The organ that releases insulin is the", "o": ["liver", "pancreas", "kidney", "heart"], "c": 1, "w": ""}, {"t": "mc", "q": "Homeostasis mostly uses", "o": ["positive feedback", "negative feedback", "no feedback", "random change"], "c": 1, "w": ""}, {"t": "mc", "q": "Alveoli are adapted by having", "o": ["thick walls", "a large surface area", "few capillaries", "no moisture"], "c": 1, "w": ""}, {"t": "mc", "q": "The heart is best described as", "o": ["a single pump", "a double pump", "a filter", "a gland"], "c": 1, "w": ""}, {"t": "mc", "q": "Where in the lungs does gas exchange occur?", "o": ["trachea", "bronchi", "alveoli", "diaphragm"], "c": 2, "w": "Thin-walled air sacs."}, {"t": "mc", "q": "Which hormone lowers blood glucose?", "o": ["glucagon", "adrenaline", "insulin", "thyroxine"], "c": 2, "w": "Insulin, from the pancreas."}, {"t": "num", "q": "A resting heart beats 70 times a minute with a stroke volume of 70 mL. What is the cardiac output in litres per minute?", "a": 4.9, "unit": "L/min", "tol": 0.02, "w": "70 × 70 = 4900 mL/min."}, {"t": "num", "q": "During exercise, heart rate rises to 150 beats/min and stroke volume to 110 mL. What is cardiac output, in L/min?", "a": 16.5, "unit": "L/min", "tol": 0.02, "w": "150 × 110 = 16 500 mL/min."}], "6.8": [{"t": "mc", "q": "Viruses reproduce", "o": ["by dividing", "only inside host cells", "in soil", "by photosynthesis"], "c": 1, "w": ""}, {"t": "mc", "q": "Immune memory means the second response is", "o": ["slower", "faster and stronger", "absent", "identical"], "c": 1, "w": ""}, {"t": "mc", "q": "If R_eff < 1, an epidemic", "o": ["grows", "declines", "stays level", "doubles"], "c": 1, "w": ""}, {"t": "mc", "q": "Germ theory was established by", "o": ["Darwin and Wallace", "Pasteur and Koch", "Watson and Crick", "Newton"], "c": 1, "w": ""}, {"t": "mc", "q": "Antibiotics are effective against", "o": ["viruses", "bacteria", "both", "neither"], "c": 1, "w": "They target bacterial structures."}, {"t": "mc", "q": "Vaccines work by", "o": ["killing all microbes in the body", "creating immune memory without causing the disease", "acting as antibiotics", "replacing white blood cells"], "c": 1, "w": "They train the adaptive immune system."}, {"t": "num", "q": "A bacterium divides every 20 minutes. Starting from one cell, how many are there after 2 hours?", "a": 64, "unit": "", "tol": 0.02, "w": "2 hours = 6 doublings. 2⁶ = 64."}, {"t": "num", "q": "Measles has R₀ ≈ 15. What is the herd immunity threshold, as a percentage?", "a": 93.33333333333333, "unit": "%", "tol": 0.02, "w": "1 − 1/15 ≈ 0.933. About 93%."}], "6.9": [{"t": "mc", "q": "Energy in ecosystems", "o": ["cycles", "flows one way", "is created by plants", "stays constant at every level"], "c": 1, "w": ""}, {"t": "mc", "q": "Carrying capacity is", "o": ["the starting population", "the maximum sustainable population", "the growth rate", "the death rate"], "c": 1, "w": ""}, {"t": "mc", "q": "Decomposers", "o": ["produce oxygen", "break down dead matter", "are top predators", "photosynthesise"], "c": 1, "w": ""}, {"t": "mc", "q": "Pre-industrial CO₂ was about", "o": ["180 ppm", "280 ppm", "420 ppm", "1000 ppm"], "c": 1, "w": ""}, {"t": "mc", "q": "Which process removes CO₂ from the atmosphere?", "o": ["respiration", "combustion", "photosynthesis", "decomposition"], "c": 2, "w": "Plants fix carbon."}, {"t": "mc", "q": "Why are there fewer top predators than herbivores?", "o": ["predators breed slowly only", "energy is lost at each trophic level", "predators are larger", "herbivores hide"], "c": 1, "w": "Only about 10% passes up each level."}, {"t": "num", "q": "Producers in an ecosystem capture 20 000 kJ. About how much energy reaches the carnivores that eat herbivores?", "a": 200, "unit": "kJ", "tol": 0.02, "w": "Two steps at 10%: 20 000 → 2000 → 200."}, {"t": "num", "q": "In the logistic model, what is dN/dt when N = K/2, r = 0.4 per year and K = 1000?", "a": 100.0, "unit": "per year", "tol": 0.02, "w": "dN/dt = rN(1 − N/K) = 0.4 × 500 × 0.5. = 100 per year (the fastest growth)."}], "2.3P": [{"t": "mc", "q": "In T = 2π√(L/g), which operation do you undo first when solving for g?", "o": ["The division of L by g", "The square root", "The multiplication by 2π", "It doesn't matter"], "c": 2, "w": "2π was applied last when building T from g, so it is the outermost layer and comes off first."}, {"t": "mc", "q": "From 1/f = 1/u + 1/v, which is the correct expression for v?", "o": ["v = f − u", "v = uf/(u − f)", "v = (u − f)/uf", "v = u + f"], "c": 1, "w": "1/v = 1/f − 1/u = (u − f)/uf; only then flip both sides."}, {"t": "mc", "q": "Make x the subject of ax + b = cx + d.", "o": ["x = (d − b)/(a − c)", "x = (d + b)/(a + c)", "x = (d − b)/ac", "x = d/a − b/c"], "c": 0, "w": "Collect: ax − cx = d − b. Factor: x(a − c) = d − b. Divide."}, {"t": "mc", "q": "Solve N = N₀e^(−kt) for t.", "o": ["t = ln(N/N₀)/k", "t = ln(N₀/N)/k", "t = (N₀ − N)/k", "t = −k ln(N₀/N)"], "c": 1, "w": "Divide by N₀, take ln, divide by −k and flip the fraction inside the log."}, {"t": "mc", "q": "Gravitational force goes as 1/r². If r is halved, the force is multiplied by", "o": ["½", "2", "4", "¼"], "c": 2, "w": "(½)⁻² = 4."}, {"t": "mc", "q": "You measure decay counts N over time t. Which plot gives a straight line?", "o": ["N against t", "N against ln t", "ln N against t", "1/N against t"], "c": 2, "w": "ln N = ln N₀ − kt: gradient −k, intercept ln N₀."}, {"t": "mc", "q": "A student rearranges E = ½mv² to get v = √(2E)/m. Which check exposes the error fastest?", "o": ["Units: the right side isn't a speed", "Limiting case: v at E = 0", "Counting the steps", "Re-reading the question"], "c": 0, "w": "√(2E)/m does not have units of m/s; at E = 0 both forms give 0, so that check misses it."}, {"t": "mc", "q": "Solving x² = 16 for a displacement that could be either direction, the full answer is", "o": ["x = 4", "x = ±4", "x = 8", "x = −4"], "c": 1, "w": "Squaring hides the sign, so both roots are candidates."}]};
